#!/usr/bin/env node
/* eslint-disable no-console */
/* eslint-disable @typescript-eslint/no-unused-vars */

import { spawnSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { readAuditSince } from "./audit.js";
import { EnvCodexSchema } from "./contracts.js";
import { EnvSandbox } from "./sandbox.js";
import { resolveStoragePaths } from "./storage.js";
import { LayerNameSchema } from "./types.js";

type Cmd =
    | "init"
    | "layer"
    | "get"
    | "set"
    | "unset"
    | "clear"
    | "profiles"
    | "profile-define"
    | "profile-apply"
    | "snapshot"
    | "snapshots"
    | "restore"
    | "diff"
    | "run"
    | "bind-codex"
    | "gates"
    | "gate-set"
    | "codex"
    | "validate"
    | "history"
    | "help";

function die(msg: string, code = 1): never {
    console.error(msg);
    process.exit(code);
}

function usage(): void {
    console.log(`
env-sandbox-tools (next tier)

Core:
  init
  layer get
  layer set <prime|subtle|material|data-plane>
  get [--effective] [--layer <layer>]
  set <KEY> <VALUE> [--layer <layer>] [--fail-on-unknown] [--actor <name>] [--note <text>]
  unset <KEY> [--layer <layer>] [--actor <name>] [--note <text>]
  clear [--layer <layer>] [--actor <name>] [--note <text>]

Governance:
  codex get
  codex export <file>
  codex import <file>
  validate
  gates
  gate-set <gateName> <true|false>

Audit:
  history [--since <ISO>]

Profiles:
  profiles
  profile-define <name> <jsonFile> [--layer <layer>]
  profile-apply <name> [--layer <layer>] [--actor <name>] [--note <text>]

Snapshots:
  snapshot <name> [--note "text"]
  snapshots
  restore <name>
  diff <snapshotName>

Run:
  run -- <command> [...args]

Codex binder:
  bind-codex <codexJsonFile> [--layer <layer>] [--actor <name>] [--note <text>]

Examples:
  node dist/index.js set LOG_LEVEL trace --layer subtle --actor Colten
  node dist/index.js gate-set production_lock true
  node dist/index.js set SECRET_TOKEN abc --fail-on-unknown
  node dist/index.js history --since 2026-02-01T00:00:00.000Z
`.trim());
}

function parseArgs(argv: string[]): { cmd: Cmd; rest: string[] } {
    const [, , maybeCmd, ...rest] = argv;
    const cmd = (maybeCmd ?? "help") as Cmd;
    return { cmd, rest };
}

function takeFlag(rest: string[], flag: string): { value?: string; rest: string[] } {
    const idx = rest.indexOf(flag);
    if (idx === -1) {
        return { rest };
    }
    const value = rest[idx + 1];
    const next = rest.slice(0, idx).concat(rest.slice(idx + 2));
    if (!value) {
        return { rest: next };
    }
    return { value, rest: next };
}

function hasFlag(rest: string[], flag: string): { has: boolean; rest: string[] } {
    const idx = rest.indexOf(flag);
    if (idx === -1) return { has: false, rest };
    const next = rest.slice(0, idx).concat(rest.slice(idx + 1));
    return { has: true, rest: next };
}

function main() {
    const { cmd, rest } = parseArgs(process.argv);
    const paths = resolveStoragePaths(process.cwd());

    if (cmd === "help") {
        usage();
        return;
    }

    if (cmd === "init") {
        const sb = new EnvSandbox(paths.stateFile);
        console.log(`Γ£à Initialized sandbox at ${paths.stateFile}`);
        console.log(`Active layer: ${sb.getActiveLayer()}`);
        return;
    }

    const sb = new EnvSandbox(paths.stateFile);

    try {
        switch (cmd) {
            case "layer": {
                if (rest[0] === "get") {
                    console.log(sb.getActiveLayer());
                    return;
                }
                if (rest[0] === "set") {
                    const layer = rest[1];
                    if (!layer) die("Missing layer. Example: layer set material");
                    sb.setActiveLayer(LayerNameSchema.parse(layer));
                    console.log(`Γ£à Active layer set to ${sb.getActiveLayer()}`);
                    return;
                }
                die("Usage: layer get | layer set <layer>");
            }

            case "get": {
                const eff = hasFlag(rest, "--effective");
                const layerFlag = takeFlag(eff.rest, "--layer");
                const layer = layerFlag.value ? LayerNameSchema.parse(layerFlag.value) : undefined;

                const env = eff.has ? sb.getEffectiveEnv() : sb.getLayerEnv(layer);
                console.log(JSON.stringify(env, null, 2));
                return;
            }

            case "set": {
                const failUnknown = hasFlag(rest, "--fail-on-unknown");
                const actorFlag = takeFlag(failUnknown.rest, "--actor");
                const noteFlag = takeFlag(actorFlag.rest, "--note");
                const layerFlag = takeFlag(noteFlag.rest, "--layer");

                const layer = layerFlag.value ? LayerNameSchema.parse(layerFlag.value) : undefined;
                const key = layerFlag.rest[0];
                const value = layerFlag.rest[1];

                if (!key || value === undefined) die("Usage: set <KEY> <VALUE> [--layer <layer>] [--fail-on-unknown]");

                sb.setVarTyped({
                    key,
                    raw: value,
                    ...(layer ? { layer } : {}),
                    ...(actorFlag.value ? { actor: actorFlag.value } : {}),
                    ...(noteFlag.value ? { note: noteFlag.value } : {}),
                    failOnUnknownOverride: failUnknown.has
                });

                console.log(`Γ£à Set ${key} on ${layer ?? sb.getActiveLayer()}`);
                return;
            }

            case "unset": {
                const actorFlag = takeFlag(rest, "--actor");
                const noteFlag = takeFlag(actorFlag.rest, "--note");
                const layerFlag = takeFlag(noteFlag.rest, "--layer");

                const layer = layerFlag.value ? LayerNameSchema.parse(layerFlag.value) : undefined;
                const key = layerFlag.rest[0];
                if (!key) die("Usage: unset <KEY> [--layer <layer>]");

                sb.unsetVar({
                    key,
                    ...(layer ? { layer } : {}),
                    ...(actorFlag.value ? { actor: actorFlag.value } : {}),
                    ...(noteFlag.value ? { note: noteFlag.value } : {})
                });
                console.log(`Γ£à Unset ${key} on ${layer ?? sb.getActiveLayer()}`);
                return;
            }

            case "clear": {
                const actorFlag = takeFlag(rest, "--actor");
                const noteFlag = takeFlag(actorFlag.rest, "--note");
                const layerFlag = takeFlag(noteFlag.rest, "--layer");

                const layer = layerFlag.value ? LayerNameSchema.parse(layerFlag.value) : undefined;
                sb.clearLayer({
                    ...(layer ? { layer } : {}),
                    ...(actorFlag.value ? { actor: actorFlag.value } : {}),
                    ...(noteFlag.value ? { note: noteFlag.value } : {})
                });
                console.log(`Γ£à Cleared ${layer ?? sb.getActiveLayer()}`);
                return;
            }

            case "profiles": {
                console.log(JSON.stringify(sb.listProfiles(), null, 2));
                return;
            }

            case "profile-define": {
                const layerFlag = takeFlag(rest, "--layer");
                const layer = layerFlag.value ? LayerNameSchema.parse(layerFlag.value) : undefined;

                const name = layerFlag.rest[0];
                const jsonFile = layerFlag.rest[1];
                if (!name || !jsonFile) die("Usage: profile-define <name> <jsonFile> [--layer <layer>]");
                const filePath = path.resolve(process.cwd(), jsonFile);
                if (!fs.existsSync(filePath)) die(`File not found: ${filePath}`);

                const envObj = JSON.parse(fs.readFileSync(filePath, "utf-8")) as Record<string, string>;
                sb.defineProfile(name, envObj, layer);
                console.log(`Γ£à Defined profile "${name}"`);
                return;
            }

            case "profile-apply": {
                const actorFlag = takeFlag(rest, "--actor");
                const noteFlag = takeFlag(actorFlag.rest, "--note");
                const layerFlag = takeFlag(noteFlag.rest, "--layer");

                const layer = layerFlag.value ? LayerNameSchema.parse(layerFlag.value) : undefined;
                const name = layerFlag.rest[0];
                if (!name) die("Usage: profile-apply <name> [--layer <layer>]");

                sb.applyProfile({
                    name,
                    ...(layer ? { targetLayer: layer } : {}),
                    ...(actorFlag.value ? { actor: actorFlag.value } : {}),
                    ...(noteFlag.value ? { note: noteFlag.value } : {})
                });
                console.log(`Γ£à Applied profile "${name}" -> ${layer ?? sb.getActiveLayer()}`);
                return;
            }

            case "snapshot": {
                const noteFlag = takeFlag(rest, "--note");
                const name = noteFlag.rest[0];
                if (!name) die("Usage: snapshot <name> [--note \"...\"]");
                sb.snapshot(name, noteFlag.value);
                console.log(`Γ£à Snapshot saved: ${name}`);
                return;
            }

            case "snapshots": {
                console.log(JSON.stringify(sb.listSnapshots(), null, 2));
                return;
            }

            case "restore": {
                const name = rest[0];
                if (!name) die("Usage: restore <snapshotName>");
                sb.restore(name);
                console.log(`Γ£à Restored snapshot: ${name}`);
                return;
            }

            case "diff": {
                const name = rest[0];
                if (!name) die("Usage: diff <snapshotName>");
                console.log(JSON.stringify(sb.diffSnapshot(name), null, 2));
                return;
            }

            case "run": {
                const sep = rest.indexOf("--");
                if (sep === -1) die("Usage: run -- <command> [...args]");
                const c = rest[sep + 1];
                const args = rest.slice(sep + 2);
                if (!c) die("Usage: run -- <command> [...args]");

                const injected = sb.getEffectiveEnv();
                const childEnv = { ...process.env, ...injected };

                const res = spawnSync(c, args, {
                    stdio: "inherit",
                    env: childEnv,
                    shell: process.platform === "win32"
                });

                process.exit(res.status ?? 0);
            }

            case "bind-codex": {
                const actorFlag = takeFlag(rest, "--actor");
                const noteFlag = takeFlag(actorFlag.rest, "--note");
                const layerFlag = takeFlag(noteFlag.rest, "--layer");

                const layer = layerFlag.value ? LayerNameSchema.parse(layerFlag.value) : undefined;
                const codexFile = layerFlag.rest[0];
                if (!codexFile) die("Usage: bind-codex <codexJsonFile> [--layer <layer>]");
                const filePath = path.resolve(process.cwd(), codexFile);
                if (!fs.existsSync(filePath)) die(`File not found: ${filePath}`);

                const codexObj = JSON.parse(fs.readFileSync(filePath, "utf-8"));
                const info = sb.bindRecursiveCreationCodex({
                    codexJson: codexObj,
                    ...(layer ? { layer } : {}),
                    ...(actorFlag.value ? { actor: actorFlag.value } : {}),
                    ...(noteFlag.value ? { note: noteFlag.value } : {})
                });

                console.log(`Γ£à Bound Recursive Creation Codex into env (${layer ?? sb.getActiveLayer()})`);
                console.log(JSON.stringify(info, null, 2));
                return;
            }

            case "gates": {
                console.log(JSON.stringify(sb.getEnvCodex().gates, null, 2));
                return;
            }

            case "gate-set": {
                const gate = rest[0];
                const raw = rest[1];
                if (!gate || raw === undefined) die("Usage: gate-set <gateName> <true|false>");
                const v = raw.trim().toLowerCase();
                if (v !== "true" && v !== "false") die(`Invalid boolean: ${raw}`);
                sb.setGate(gate, v === "true");
                console.log(`Γ£à Gate ${gate} = ${v}`);
                return;
            }

            case "codex": {
                const sub = rest[0];
                if (!sub || sub === "get") {
                    console.log(JSON.stringify(sb.getEnvCodex(), null, 2));
                    return;
                }
                if (sub === "export") {
                    const file = rest[1];
                    if (!file) die("Usage: codex export <file>");
                    fs.writeFileSync(path.resolve(process.cwd(), file), JSON.stringify(sb.getEnvCodex(), null, 2) + "\n", "utf-8");
                    console.log(`Γ£à Exported codex -> ${file}`);
                    return;
                }
                if (sub === "import") {
                    const file = rest[1];
                    if (!file) die("Usage: codex import <file>");
                    const fp = path.resolve(process.cwd(), file);
                    if (!fs.existsSync(fp)) die(`File not found: ${fp}`);
                    const obj = JSON.parse(fs.readFileSync(fp, "utf-8"));
                    // Hard validate; importing means you accept governance.
                    const validated = EnvCodexSchema.parse(obj);
                    const stateFile = paths.stateFile;
                    const rawState = JSON.parse(fs.readFileSync(stateFile, "utf-8"));
                    rawState.codex = validated;
                    fs.writeFileSync(stateFile, JSON.stringify(rawState, null, 2) + "\n", "utf-8");
                    console.log(`Γ£à Imported codex from ${file}`);
                    return;
                }
                die("Usage: codex get | codex export <file> | codex import <file>");
            }

            case "validate": {
                const codex = sb.getEnvCodex();
                // Validate codex itself
                EnvCodexSchema.parse(codex);

                // Validate current env keys against codex allowlist if codex says so
                const failUnknown = codex.policy.fail_on_unknown_key;
                if (failUnknown) {
                    const allowed = new Set(codex.registry.map((r) => r.key));
                    const env = sb.getEffectiveEnv();
                    const unknown = Object.keys(env).filter((k) => !allowed.has(k) && !k.startsWith("CODEX_"));
                    if (unknown.length) {
                        die(`Γ¥î Validation failed. Unknown keys:\n- ${unknown.join("\n- ")}`);
                    }
                }

                console.log("Γ£à Validation OK");
                return;
            }

            case "history": {
                const sinceFlag = takeFlag(rest, "--since");
                const events = readAuditSince(paths.stateFile, sinceFlag.value);
                console.log(JSON.stringify(events, null, 2));
                return;
            }

            default:
                usage();
                process.exit(0);
        }
    } catch (err) {
        die(`Γ¥î ${err instanceof Error ? err.message : String(err)}`);
    }
}

main();

/**
 * Sandbox Tools ΓÇö compact environment mutation kit
 * - Boots from Recursive Creation Codex default
 * - Immutable snapshots + restore + diff
 * - JSON path get/set
 * - Event bus
 * - Tick-based scheduler
 * - Policy-enforced mutations
 * - Tool registry
 *
 * Works in Node 18+ with "type": "module"
 */

export type Json =
  | null
  | boolean
  | number
  | string
  | Json[]
  | { [k: string]: Json };

export type SandboxState = {
  meta: {
    title: string;
    version: string;
    created_timestamp: string;
    recursive_nature?: string;
  };
  philosophical_framework?: {
    principles?: string[];
    paradoxes?: string[];
    roles?: string[];
  };
  metaphysical_cosmology?: {
    layers?: Record<string, string>;
    forces?: string[];
    fate_entanglement?: { description?: string; levels?: string };
  };
  recursive_swarm_infrastructure?: {
    components?: string[];
    event_processing_flow?: string[];
  };
  epochs: Array<{
    epoch: string;
    genesis_timestamp: string;
    inherited_imprints?: Array<{
      origin_epoch: string;
      agent_source: string;
      symbolic_fragment: string;
      inherited_message: string;
    }>;
    fate_entanglement_inheritance?: {
      inherited_fate_influence?: string;
      collapse_triggers_carried_forward?: string[];
      unseen_influences_carried_forward?: string[];
    };
    symbolic_field_resonance?: string[];
    initial_agent_manifestation?: Array<{
      agent_name: string;
      symbolic_identity: string;
      inherited_archetypal_fragments?: string[];
    }>;
  }>;
  orchestration?: {
    agents?: Array<{ name: string; role: string; model: string }>;
  };

  // Runtime environmental plane (your mutable sandbox "environment")
  environment: {
    forces: Record<string, { weight: number }>;
    vars: Record<string, Json>;
    scheduler: { tick: number };
    policy: {
      // allowlist patterns for vars and json path mutation
      allowVarKeyRegex: string;
      allowPathRegex: string;
      // if true, mutations must include a reason
      requireReason: boolean;
      // guard rails
      maxSnapshots: number;
      maxScheduled: number;
    };
  };
};

export type SandboxEvent =
  | {
    type: "SNAPSHOT";
    tick: number;
    name: string;
    note?: string;
  }
  | {
    type: "RESTORE";
    tick: number;
    name: string;
  }
  | {
    type: "MUTATION";
    tick: number;
    path: string;
    before: Json | undefined;
    after: Json | undefined;
    reason?: string;
    by?: string;
  }
  | {
    type: "TOOL_RUN";
    tick: number;
    tool: string;
    input: Json;
    reason?: string;
    by?: string;
  }
  | {
    type: "SCHEDULED";
    tick: number;
    id: string;
    dueTick: number;
    label: string;
  }
  | {
    type: "TICK";
    tick: number;
  }
  | {
    type: "ERROR";
    tick: number;
    message: string;
    context?: Json;
  };

export type ToolContext = {
  /** Read-only snapshot of current state */
  state: SandboxState;
  /** Controlled mutation entrypoint (policy enforced) */
  set: (_path: string, _value: Json, _meta?: MutateMeta) => void;
  /** Convenience for environment vars */
  setVar: (_key: string, _value: Json, _meta?: MutateMeta) => void;
  /** Convenience for forces */
  setForceWeight: (_force: string, _weight: number, _meta?: MutateMeta) => void;
  /** Schedule an action to run later */
  schedule: (_afterTicks: number, _label: string, _fn: (_ctx: ToolContext) => void) => string;
};

export type ToolFn<I extends Json = any> = (ctx: ToolContext, input: I) => void;

export type MutateMeta = {
  reason?: string;
  by?: string;
};

type ScheduledJob = {
  id: string;
  dueTick: number;
  label: string;
  fn: (ctx: ToolContext) => void;
};

type SnapshotRecord = {
  name: string;
  tick: number;
  created_at: string;
  note?: string;
  state: SandboxState;
};

function nowIso(): string {
  return new Date().toISOString();
}

function deepClone<T>(v: T): T {
  return JSON.parse(JSON.stringify(v)) as T;
}

/**
 * Minimal diff on JSON values:
 * - compares leaf values recursively
 * - returns list of changed paths
 */
export function diffJson(a: Json, b: Json, basePath = "$"): string[] {
  const out: string[] = [];
  const walk = (x: Json, y: Json, p: string) => {
    if (x === y) return;

    const xIsObj = x !== null && typeof x === "object" && !Array.isArray(x);
    const yIsObj = y !== null && typeof y === "object" && !Array.isArray(y);
    const xIsArr = Array.isArray(x);
    const yIsArr = Array.isArray(y);

    if (xIsObj && yIsObj) {
      const xObj = x as Record<string, Json>;
      const yObj = y as Record<string, Json>;
      const keys = new Set([...Object.keys(xObj), ...Object.keys(yObj)]);
      for (const k of keys) walk(xObj[k] as Json, yObj[k] as Json, `${p}.${k}`);
      return;
    }

    if (xIsArr && yIsArr) {
      const xa = x as Json[];
      const ya = y as Json[];
      const n = Math.max(xa.length, ya.length);
      for (let i = 0; i < n; i++) walk(xa[i] as Json, ya[i] as Json, `${p}[${i}]`);
      return;
    }

    // different primitive types / object vs primitive / etc.
    out.push(p);
  };

  walk(a, b, basePath);
  return out;
}

/**
 * JSON path parser (supports):
 * - $.a.b.c
 * - $.a[0].b
 * - environment.vars["MY_KEY"] (via bracket string)
 */
type PathToken = { kind: "prop"; key: string } | { kind: "index"; index: number };

export function parseJsonPath(path: string): PathToken[] {
  const s = path.trim();
  if (!s.startsWith("$")) throw new Error(`Path must start with "$": ${path}`);

  const tokens: PathToken[] = [];
  let i = 1;

  const isIdentChar = (c: string) => /[A-Za-z0-9_$-]/.test(c);

  while (i < s.length) {
    const c = s[i];
    if (c === ".") {
      i++;
      let key = "";
      while (i < s.length && isIdentChar(s[i]!)) {
        key += s[i++];
      }
      if (!key) throw new Error(`Expected property after "." in path: ${path}`);
      tokens.push({ kind: "prop", key });
      continue;
    }

    if (c === "[") {
      i++;
      // string key?
      if (i < s.length && (s[i] === `"` || s[i] === `'`)) {
        const quoteChar = s[i]!;
        const quote = quoteChar;
        i++;
        let key = "";
        while (i < s.length && s[i] !== quote) {
          key += s[i++];
        }
        if (i >= s.length || s[i] !== quote) throw new Error(`Unterminated string bracket in path: ${path}`);
        i++; // close quote
        if (i >= s.length || s[i] !== "]") throw new Error(`Expected ] in path: ${path}`);
        i++; // close ]
        tokens.push({ kind: "prop", key });
        continue;
      }

      // numeric index
      let num = "";
      while (i < s.length && /[0-9]/.test(s[i]!)) num += s[i++];
      if (!num) throw new Error(`Expected index inside [] in path: ${path}`);
      if (i >= s.length || s[i] !== "]") throw new Error(`Expected ] in path: ${path}`);
      i++;
      tokens.push({ kind: "index", index: Number(num) });
      continue;
    }

    throw new Error(`Unexpected token "${c}" at position ${i} in path: ${path}`);
  }

  return tokens;
}

export function getByPath(root: Json, path: string): Json | undefined {
  const tokens = parseJsonPath(path);
  let cur: any = root;
  for (const t of tokens) {
    if (cur == null) return undefined;
    if (t.kind === "prop") cur = cur[t.key];
    else cur = cur[t.index];
  }
  return cur as Json | undefined;
}

export function setByPath(root: Json, path: string, value: Json): Json {
  const tokens = parseJsonPath(path);
  const next = deepClone(root);
  let cur: any = next;

  for (let ti = 0; ti < tokens.length; ti++) {
    const t = tokens[ti];
    if (!t) throw new Error(`Unexpected missing token at position ${ti}`);
    const isLast = ti === tokens.length - 1;

    if (t.kind === "prop") {
      if (isLast) {
        cur[t.key] = value;
      } else {
        const nxt = tokens[ti + 1];
        const existing = cur[t.key];
        if (existing == null) {
          cur[t.key] = nxt && nxt.kind === "index" ? [] : {};
        }
        cur = cur[t.key];
      }
    } else if (t.kind === "index") {
      // index
      if (!Array.isArray(cur)) throw new Error(`Path index used on non-array at ${path}`);
      if (isLast) {
        cur[t.index] = value;
      } else {
        const existing = cur[t.index];
        const nxt = tokens[ti + 1];
        if (existing == null) {
          cur[t.index] = nxt && nxt.kind === "index" ? [] : {};
        }
        cur = cur[t.index];
      }
    }
  }
  return next;
}

function clamp01(x: number): number {
  if (!Number.isFinite(x)) throw new Error(`Expected finite number, got ${x}`);
  if (x < 0) return 0;
  if (x > 1) return 1;
  return x;
}

function randomId(prefix = "job"): string {
  return `${prefix}_${Math.random().toString(16).slice(2)}_${Date.now().toString(16)}`;
}

/**
 * Sandbox ΓÇö controlled environment mutation engine
 */
export class Sandbox {
  private state: SandboxState;
  private snapshots: SnapshotRecord[] = [];
  private tools = new Map<string, ToolFn>();
  private jobs: ScheduledJob[] = [];
  private listeners: Array<(e: SandboxEvent) => void> = [];

  private constructor(initial: SandboxState) {
    this.state = deepClone(initial);
  }

  static bootstrap(codex?: Partial<SandboxState>): Sandbox {
    const base: SandboxState = {
      meta: {
        title: "Recursive Creation Codex",
        version: "1.0.0",
        created_timestamp: nowIso(),
        recursive_nature: "Nested agentic synthesis with carry-forward imprints"
      },
      philosophical_framework: {
        principles: ["Self-similarity", "Emergence", "Composability"],
        paradoxes: ["Bootstrap", "Observer Effect"],
        roles: ["Observer", "Creator", "Archivist"]
      },
      metaphysical_cosmology: {
        layers: {
