        policy: {
          allowVarKeyRegex: "^[A-Z][A-Z0-9_]*$",
          allowPathRegex: "^\\$\\.(environment|epochs|orchestration|metaphysical_cosmology|philosophical_framework|recursive_swarm_infrastructure|meta)(\\.|\\[).+",
          requireReason: false,
          maxSnapshots: 200,
          maxScheduled: 1000
        }
      }
    };

    const merged = codex ? (deepClone({ ...base, ...codex }) as SandboxState) : base;
    return new Sandbox(merged);
  }

  on(fn: (e: SandboxEvent) => void): () => void {
    this.listeners.push(fn);
    return () => {
      const i = this.listeners.indexOf(fn);
      if (i >= 0) this.listeners.splice(i, 1);
    };
  }

  private emit(e: SandboxEvent): void {
    for (const fn of this.listeners) {
      try {
        fn(e);
      } catch (err) {
        // never let a listener crash the sandbox
        console.error("Listener error:", err);
      }
    }
  }

  getState(): SandboxState {
    return deepClone(this.state);
  }

  /** Strict policy check for JSON-path mutation */
  private assertPathAllowed(path: string): void {
    const rx = new RegExp(this.state.environment.policy.allowPathRegex);
    if (!rx.test(path)) throw new Error(`Policy denied path: ${path}`);
  }

  /** Strict policy check for var keys */
  private assertVarKeyAllowed(key: string): void {
    const rx = new RegExp(this.state.environment.policy.allowVarKeyRegex);
    if (!rx.test(key)) throw new Error(`Policy denied var key: ${key}`);
  }

  /** Require reason if configured */
  private assertReason(meta?: MutateMeta): void {
    if (!this.state.environment.policy.requireReason) return;
    if (!meta?.reason || meta.reason.trim().length < 3) {
      throw new Error(`Policy requires reason (>=3 chars) for mutations.`);
    }
  }

  /** Low-level mutation */
  set(path: string, value: Json, meta?: MutateMeta): void {
    this.assertPathAllowed(path);
    this.assertReason(meta);

    const before = getByPath(this.state as unknown as Json, path);
    const next = setByPath(this.state as unknown as Json, path, value) as unknown as SandboxState;
    this.state = next;

    this.emit({
      type: "MUTATION",
      tick: this.state.environment.scheduler.tick,
      path,
      before,
      after: value,
      ...(meta?.reason ? { reason: meta.reason } : {}),
      ...(meta?.by ? { by: meta.by } : {})
    });
  }

  get(path: string): Json | undefined {
    return getByPath(this.state as unknown as Json, path);
  }

  /** Convenience: runtime vars */
  setVar(key: string, value: Json, meta?: MutateMeta): void {
    this.assertVarKeyAllowed(key);
    this.assertReason(meta);
    this.set(`$.environment.vars["${key}"]`, value, meta);
  }

  /** Convenience: runtime forces */
  setForceWeight(force: string, weight: number, meta?: MutateMeta): void {
    const w = clamp01(weight);
    this.assertReason(meta);
    this.set(`$.environment.forces["${force}"]`, { weight: w }, meta);
  }

  /** Snapshot state immutably */
  snapshot(name: string, note?: string): void {
    if (!name || name.trim().length < 1) throw new Error("Snapshot name required.");
    if (this.snapshots.length >= this.state.environment.policy.maxSnapshots) {
      throw new Error(`Snapshot limit reached (${this.state.environment.policy.maxSnapshots}).`);
    }
    const rec: SnapshotRecord = {
      name,
      tick: this.state.environment.scheduler.tick,
      created_at: nowIso(),
      ...(note ? { note } : {}),
      state: deepClone(this.state)
    };
    this.snapshots.push(rec);
    this.emit({
      type: "SNAPSHOT",
      tick: rec.tick,
      name: rec.name,
      ...(rec.note ? { note: rec.note } : {})
    });
  }

  listSnapshots(): Array<{ name: string; tick: number; created_at: string; note?: string }> {
    return this.snapshots.map(({ name, tick, created_at, note }) => ({
      name,
      tick,
      created_at,
      ...(note ? { note } : {})
    }));
  }

  restore(name: string): void {
    const rec = this.snapshots.find((s) => s.name === name);
    if (!rec) throw new Error(`Unknown snapshot: ${name}`);
    this.state = deepClone(rec.state);
    this.emit({ type: "RESTORE", tick: this.state.environment.scheduler.tick, name });
  }

  diffSnapshots(aName: string, bName: string): { changedPaths: string[] } {
    const a = this.snapshots.find((s) => s.name === aName);
    const b = this.snapshots.find((s) => s.name === bName);
    if (!a || !b) throw new Error(`Unknown snapshots: ${aName}, ${bName}`);
    const changedPaths = diffJson(a.state as unknown as Json, b.state as unknown as Json, "$");
    return { changedPaths };
  }

  diffCurrent(name: string): { changedPaths: string[] } {
    const a = this.snapshots.find((s) => s.name === name);
    if (!a) throw new Error(`Unknown snapshot: ${name}`);
    const changedPaths = diffJson(a.state as unknown as Json, this.state as unknown as Json, "$");
    return { changedPaths };
  }

  /** Tool registry */
  registerTool(name: string, fn: ToolFn): void {
    if (!name || name.trim().length < 1) throw new Error("Tool name required.");
    this.tools.set(name, fn);
  }

  listTools(): string[] {
    return [...this.tools.keys()].sort();
  }

  runTool(name: string, input: Json, meta?: MutateMeta): void {
    const fn = this.tools.get(name);
    if (!fn) throw new Error(`Unknown tool: ${name}`);
    this.assertReason(meta);

    this.emit({
      type: "TOOL_RUN",
      tick: this.state.environment.scheduler.tick,
      tool: name,
      input: deepClone(input),
      ...(meta?.reason ? { reason: meta.reason } : {}),
      ...(meta?.by ? { by: meta.by } : {})
    });

    const ctx = this.makeToolContext();
    fn(ctx, input);
  }

  /** Scheduler */
  schedule(afterTicks: number, label: string, fn: (ctx: ToolContext) => void): string {
    const t = Math.floor(afterTicks);
    if (!Number.isFinite(t) || t < 0) throw new Error(`afterTicks must be >= 0, got ${afterTicks}`);
    if (this.jobs.length >= this.state.environment.policy.maxScheduled) {
      throw new Error(`Scheduled job limit reached (${this.state.environment.policy.maxScheduled}).`);
    }
    const id = randomId("sched");
    const dueTick = this.state.environment.scheduler.tick + t;
    this.jobs.push({ id, dueTick, label, fn });

    this.emit({
      type: "SCHEDULED",
      tick: this.state.environment.scheduler.tick,
      id,
      dueTick,
      label
    });

    return id;
  }

  tick(n = 1): void {
    const steps = Math.max(1, Math.floor(n));
    for (let i = 0; i < steps; i++) {
      // advance tick
      const cur = this.state.environment.scheduler.tick;
      this.state.environment.scheduler.tick = cur + 1;

      this.emit({ type: "TICK", tick: this.state.environment.scheduler.tick });

      // run due jobs (stable order by dueTick then insertion)
      const due = this.jobs.filter((j) => j.dueTick <= this.state.environment.scheduler.tick);
      this.jobs = this.jobs.filter((j) => j.dueTick > this.state.environment.scheduler.tick);

      for (const job of due) {
        try {
          job.fn(this.makeToolContext());
        } catch (err) {
          this.emit({
            type: "ERROR",
            tick: this.state.environment.scheduler.tick,
            message: err instanceof Error ? err.message : String(err),
            context: { id: job.id, label: job.label, dueTick: job.dueTick }
          });
        }
      }
    }
  }

  /** Internal: controlled context given to tools */
  private makeToolContext(): ToolContext {
    return {
      state: this.getState(),
      set: (path, value, meta) => this.set(path, value, meta),
      setVar: (key, value, meta) => this.setVar(key, value, meta),
      setForceWeight: (force, weight, meta) => this.setForceWeight(force, weight, meta),
      schedule: (afterTicks, label, fn) => this.schedule(afterTicks, label, fn)
    };
  }
}

/** Built-in tools */
export const tools = {
  setForceWeight: ((ctx, input) => {
    const obj = input as any;
    const force = String(obj.force ?? "");
    const weight = Number(obj.weight);
    if (!force) throw new Error("setForceWeight: force required");
    ctx.setForceWeight(force, weight);
  }) satisfies ToolFn,

  setVar: ((ctx, input) => {
    const obj = input as any;
    const key = String(obj.key ?? "");
    const value = (obj.value ?? null) as Json;
    if (!key) throw new Error("setVar: key required");
    ctx.setVar(key, value);
  }) satisfies ToolFn,

  addAgent: ((ctx, input) => {
    const obj = input as any;
    const name = String(obj.name ?? "").trim();
    const role = String(obj.role ?? "").trim();
    const model = String(obj.model ?? "real processing and Thinking").trim();
    if (!name) throw new Error("addAgent: name required");
    if (!role) throw new Error("addAgent: role required");

    const agents = (ctx.state.orchestration?.agents ?? []) as Array<{ name: string; role: string; model: string }>;
    const next = [...agents, { name, role, model }];

    ctx.set("$.orchestration.agents", next as unknown as Json);
  }) satisfies ToolFn,

  advanceEpoch: ((ctx, input) => {
    const obj = input as any;
    const label = String(obj.label ?? "").trim();
    if (!label) throw new Error("advanceEpoch: label required");

    const resonance = (Array.isArray(obj.resonance) ? obj.resonance : []) as string[];
    const carryTriggers = (Array.isArray(obj.carryTriggers) ? obj.carryTriggers : []) as string[];
    const carryInfluences = (Array.isArray(obj.carryInfluences) ? obj.carryInfluences : []) as string[];

    const epochs = ctx.state.epochs ?? [];
    const prev = epochs[epochs.length - 1];

    const inherited_imprints =
      prev?.inherited_imprints?.length
        ? JSON.parse(JSON.stringify(prev.inherited_imprints))
        : [
          {
            origin_epoch: prev?.epoch ?? "Γêà",
            agent_source: "sandbox/advanceEpoch",
            symbolic_fragment: "Γå╗",
            inherited_message: "Carry-forward imprint."
          }
        ];

    const nextEpoch = {
      epoch: label,
      genesis_timestamp: new Date().toISOString(),
      inherited_imprints,
      fate_entanglement_inheritance: {
        inherited_fate_influence: "Inherited constraints/affordances (policy-carried).",
        collapse_triggers_carried_forward: carryTriggers.length ? carryTriggers : prev?.fate_entanglement_inheritance?.collapse_triggers_carried_forward ?? [],
        unseen_influences_carried_forward: carryInfluences.length ? carryInfluences : prev?.fate_entanglement_inheritance?.unseen_influences_carried_forward ?? []
      },
      symbolic_field_resonance: resonance.length ? resonance : ["echo", "trace"],
      initial_agent_manifestation: prev?.initial_agent_manifestation ? JSON.parse(JSON.stringify(prev.initial_agent_manifestation)) : []
    };

    ctx.set("$.epochs", [...epochs, nextEpoch] as unknown as Json);
  }) satisfies ToolFn,

  delayedSetVar: ((ctx, input) => {
    const obj = input as any;
    const key = String(obj.key ?? "");
    const value = (obj.value ?? null) as Json;
    const afterTicks = Number(obj.afterTicks ?? 0);
    if (!key) throw new Error("delayedSetVar: key required");
    if (!Number.isFinite(afterTicks) || afterTicks < 0) throw new Error("delayedSetVar: afterTicks must be >= 0");

    ctx.schedule(Math.floor(afterTicks), `delayedSetVar(${key})`, (inner) => {
      inner.setVar(key, value, { reason: "scheduled: delayedSetVar" });
    });
  }) satisfies ToolFn
};

import { z } from "zod";
import { appendAudit } from "./audit.js";
import { EnvCodex, EnvCodexSchema, parseTypedValue } from "./contracts.js";
import { enforceKeyPolicy } from "./policy.js";
import { readJsonFile, writeJsonFile } from "./storage.js";
import {
    EnvMap,
    EnvMapSchema,
    KeySchema,
    LayerName,
    LayerNameSchema,
    RecursiveCreationCodex,
    RecursiveCreationCodexSchema,
    SandboxState,
    SandboxStateSchema
} from "./types.js";

function nowIso(): string {
    return new Date().toISOString();
}

function deepClone<T>(v: T): T {
    return JSON.parse(JSON.stringify(v)) as T;
}

type SandboxPersisted = SandboxState & {
    codex?: EnvCodex; // Env Codex Contract (governance)
};

const SandboxPersistedSchema = SandboxStateSchema.extend({
    codex: EnvCodexSchema.optional()
});

export class EnvSandbox {
    private state: SandboxState;
    private codex: EnvCodex;
    private readonly stateFile: string;

    constructor(stateFile: string) {
        this.stateFile = stateFile;
        const loaded = this.loadOrInit();
        this.state = loaded.state;
        this.codex = loaded.codex;
    }

    private loadOrInit(): { state: SandboxState; codex: EnvCodex } {
        const raw = readJsonFile<unknown>(this.stateFile);
        if (!raw) {
            const initState = SandboxStateSchema.parse({
                meta: { created_at: nowIso() },
                activeLayer: "material",
                layers: { prime: {}, subtle: {}, material: {}, "data-plane": {} },
                profiles: {},
                snapshots: {}
            });

            const initCodex = EnvCodexSchema.parse({
                meta: { title: "Env Codex", version: "1.0.0", created_at: nowIso() },
                gates: {
                    // sane defaults
                    production_lock: false,
                    resource_scarcity: false,
                    observer_effect: false
                },
                registry: [
                    {
                        key: "NODE_ENV",
                        kind: "string",
                        description: "Node environment mode.",
                        default: "development",
                        allowed_layers: ["material"]
                    },
                    {
                        key: "LOG_LEVEL",
                        kind: "string",
                        description: "Logging verbosity (debug/info/warn/error/trace).",
                        default: "info",
                        allowed_layers: ["subtle", "material"]
                    }
                ],
                policy: {
                    fail_on_unknown_key: true,
                    enforce_gates: true,
                    production_locked_prefixes: ["PROD_", "SECRET_", "TOKEN_", "KEY_"]
                }
            });

            writeJsonFile(this.stateFile, { ...initState, codex: initCodex });
            return { state: initState, codex: initCodex };
        }

        const parsed = SandboxPersistedSchema.parse(raw);
        return {
            state: parsed,
            codex: parsed.codex ?? EnvCodexSchema.parse({ meta: { created_at: nowIso() } })
        };
    }

    private persist(): void {
        writeJsonFile(this.stateFile, { ...this.state, codex: this.codex });
    }

    /** --- Codex (Contract) --- */

    getEnvCodex(): EnvCodex {
        return deepClone(this.codex);
    }

    setGate(name: string, value: boolean): void {
        const gate = z.string().min(1).max(64).parse(name);
        this.codex.gates[gate] = z.boolean().parse(value);
        this.persist();
    }

    /** --- Base sandbox --- */

    getActiveLayer(): LayerName {
        return this.state.activeLayer;
    }

    setActiveLayer(layer: LayerName): void {
        this.state.activeLayer = LayerNameSchema.parse(layer);
        this.persist();
    }

    listLayers(): LayerName[] {
        return ["prime", "subtle", "material", "data-plane"];
    }

    getLayerEnv(layer?: LayerName): EnvMap {
        const l = layer ?? this.state.activeLayer;
        const env = this.state.layers[l];
        if (!env) throw new Error(`Layer ${l} not found`);
        return deepClone(env);
    }

    getEffectiveEnv(): Record<string, string> {
        const merged: Record<string, string> = {};
        const order: LayerName[] = ["prime", "subtle", "material", "data-plane"];
        for (const layer of order) {
            const layerEnv = this.state.layers[layer];
            if (layerEnv) {
                for (const [k, v] of Object.entries(layerEnv)) {
                    merged[k] = String(v);
                }
            }
        }
        return merged;
    }

    /**
     * Typed + governed setter.
     * - If key exists in Env Codex registry: parse according to spec.kind
     * - Enforce key policy + required gates
     * - Optionally allow unknown keys if failOnUnknownOverride=false
     */
    setVarTyped(args: {
        key: string;
        raw: string;
        layer?: LayerName;
        actor?: string;
        note?: string;
        failOnUnknownOverride?: boolean;
    }): void {
        const key = KeySchema.parse(args.key);
        const layer = args.layer ?? this.state.activeLayer;

        const { spec } = enforceKeyPolicy({
            ctx: { codex: this.codex, activeGates: this.codex.gates },
            key,
            layer,
            ...(args.failOnUnknownOverride !== undefined ? { failOnUnknownOverride: Boolean(args.failOnUnknownOverride) } : {})
        });

        // Determine kind and parse
        const value = spec
            ? parseTypedValue(spec.kind, args.raw)
            : z.string().parse(args.raw); // unknown keys become strings if allowed

        // Ensure layer exists
        if (!this.state.layers[layer]) {
            this.state.layers[layer] = {};
        }
        this.state.layers[layer]![key] = value;
        this.persist();

        const layerData = this.state.layers[layer];
        if (layerData) {
            appendAudit(this.stateFile, {
                type: "SET",
                layer,
                key,
                value: String(value),
                ...(args.actor ? { actor: args.actor } : {}),
                ...(args.note ? { note: args.note } : {})
            } as any); // Cast to handle exactOptionalPropertyTypes
        }
    }

    unsetVar(args: { key: string; layer?: LayerName; actor?: string; note?: string }): void {
        const key = KeySchema.parse(args.key);
        const layer = args.layer ?? this.state.activeLayer;
        if (this.state.layers[layer]) {
            delete this.state.layers[layer][key];
            this.persist();

            appendAudit(this.stateFile, {
                type: "UNSET",
                layer,
                key,
                ...(args.actor ? { actor: args.actor } : {}),
                ...(args.note ? { note: args.note } : {})
            } as any); // Cast to handle exactOptionalPropertyTypes
        }
    }

    clearLayer(args?: { layer?: LayerName; actor?: string; note?: string }): void {
        const layer = args?.layer ?? this.state.activeLayer;
        this.state.layers[layer] = EnvMapSchema.parse({});
        this.persist();

        appendAudit(this.stateFile, {
            type: "CLEAR_LAYER",
            layer,
            ...(args?.actor ? { actor: args.actor } : {}),
            ...(args?.note ? { note: args.note } : {})
        });
    }

    /** Profiles */
    defineProfile(name: string, env: Record<string, string>, layer?: LayerName): void {
        const profileName = z.string().min(1).max(64).parse(name);
        const parsedEnv = EnvMapSchema.parse(env);
        const parsedLayer = layer ? LayerNameSchema.parse(layer) : undefined;

        this.state.profiles[profileName] = { layer: parsedLayer, env: parsedEnv };
        this.persist();
    }

    listProfiles(): string[] {
        return Object.keys(this.state.profiles).sort();
    }

    applyProfile(args: { name: string; targetLayer?: LayerName; actor?: string; note?: string }): void {
        const profile = this.state.profiles[args.name];
        if (!profile) throw new Error(`Unknown profile: ${args.name}`);

        const layer = args.targetLayer ?? profile.layer ?? this.state.activeLayer;
        for (const [k, v] of Object.entries(profile.env)) {
            // Profile apply uses typed setter with unknowns governed by codex policy
            this.setVarTyped({ key: k, raw: String(v), layer, ...(args.actor ? { actor: args.actor } : {}), ...(args.note ? { note: args.note } : {}) });
        }

        appendAudit(this.stateFile, {
            type: "APPLY_PROFILE",
            layer,
            profile: args.name,
            ...(args.actor ? { actor: args.actor } : {}),
            ...(args.note ? { note: args.note } : {})
        } as any); // Cast to handle exactOptionalPropertyTypes
    }

    /** Snapshots */
    snapshot(name: string, note?: string): void {
        const snapName = z.string().min(1).max(64).parse(name);
        this.state.snapshots[snapName] = {
            created_at: nowIso(),
            note,
            state: deepClone({ ...this.state, codex: this.codex })
        };
        this.persist();
    }

    listSnapshots(): { name: string; created_at: string; note?: string }[] {
        return Object.entries(this.state.snapshots)
            .map(([name, s]) => ({ name, created_at: s.created_at, ...(s.note ? { note: s.note } : {}) }))
            .sort((a, b) => a.name.localeCompare(b.name));
    }

    restore(name: string): void {
        const snap = this.state.snapshots[name];
        if (!snap) throw new Error(`Unknown snapshot: ${name}`);
        const restored = SandboxPersistedSchema.parse(snap.state);

        // Keep snapshots
        restored.snapshots = this.state.snapshots;

        this.state = restored;
        this.codex = restored.codex ?? this.codex;
        this.persist();
    }

    diffSnapshot(name: string): {
        added: Record<string, string>;
        removed: Record<string, string>;
        changed: Record<string, { from: string; to: string }>;
    } {
        const snap = this.state.snapshots[name];
        if (!snap) throw new Error(`Unknown snapshot: ${name}`);

        const snapState = SandboxPersistedSchema.parse(snap.state);
        const a = snapState.layers;
        const b = this.state.layers;

        const flatten = (layers: typeof a) => {
            const merged: Record<string, string> = {};
            (["prime", "subtle", "material", "data-plane"] as const).forEach((l) => Object.assign(merged, layers[l]));
            return merged;
        };

        const A = flatten(a);
        const B = flatten(b);

        const added: Record<string, string> = {};
        const removed: Record<string, string> = {};
        const changed: Record<string, { from: string; to: string }> = {};

        const keys = new Set([...Object.keys(A), ...Object.keys(B)]);
        for (const k of keys) {
            const av = A[k];
            const bv = B[k];
            if (av === undefined && bv !== undefined) added[k] = String(bv);
            else if (av !== undefined && bv === undefined) removed[k] = String(av);
            else if (av !== undefined && bv !== undefined && String(av) !== String(bv)) changed[k] = { from: String(av), to: String(bv) };
        }

        return { added, removed, changed };
    }

    /** Recursive Creation Codex binder (still supported) */
    bindRecursiveCreationCodex(args: {
        codexJson: unknown;
        layer?: LayerName;
        actor?: string;
        note?: string;
    }): { title: string; version: string; created: string; agents: number } {
        const codex: RecursiveCreationCodex = RecursiveCreationCodexSchema.parse(args.codexJson);
        const layer = args.layer ?? this.state.activeLayer;

        const agents = codex.orchestration?.agents ?? [];
        const layerEnv = this.state.layers[layer];
        if (layerEnv) {
            layerEnv["CODEX_TITLE"] = codex.meta.title;
            layerEnv["CODEX_VERSION"] = codex.meta.version;
            layerEnv["CODEX_CREATED"] = codex.meta.created_timestamp;
            layerEnv["CODEX_AGENT_COUNT"] = String(agents.length);
        }

        const roles = codex.philosophical_framework?.roles ?? [];
        if (roles.length && layerEnv) layerEnv["CODEX_ROLES"] = roles.join(",");

        const forces = codex.metaphysical_cosmology?.forces ?? [];
        if (forces?.length && layerEnv) layerEnv["CODEX_FORCES"] = forces.join(",");

        this.persist();

        appendAudit(this.stateFile, {
            type: "BIND_CODEX",
            layer,
            codex_title: codex.meta.title,
            codex_version: codex.meta.version,
            ...(args.actor ? { actor: args.actor } : {}),
            ...(args.note ? { note: args.note } : {})
        } as any); // Cast to handle type definition mismatch

        return {
            title: codex.meta.title,
            version: codex.meta.version,
            created: codex.meta.created_timestamp,
            agents: agents.length
        };
    }
}

