/**
 * useFlowstateBusEmit ΓÇö Hook for emitting flowstate metrics to bus
 *
 * Emits telemetry when code is analyzed, with evidence packet integration.
 */

import { useCallback } from "react";
import type { FlowMetricsOutput } from "@world-engine/flowstate";

export interface FlowstateTelemetryEvent {
  type: "flowstate.metrics";
  timestamp: string;
  metrics: FlowMetricsOutput;
  sessionId: string;
}

/**
 * Hook to emit flowstate metrics to telemetry/logging system
 *
 * Usage:
 *   const emitFlowstateTelemetry = useFlowstateBusEmit();
 *   emitFlowstateTelemetry(metrics, sessionId);
 */
export function useFlowstateBusEmit() {
  return useCallback((metrics: FlowMetricsOutput, sessionId: string) => {
    const event: FlowstateTelemetryEvent = {
      type: "flowstate.metrics",
      timestamp: new Date().toISOString(),
      metrics,
      sessionId,
    };

    // Log to console (development)
    if (typeof window !== "undefined" && (window as any).__DEV__) {
      console.log("[flowstate:telemetry]", event);
    }

    // Emit to bus (if available)
    try {
      if (typeof window !== "undefined") {
        const busEvent = new CustomEvent("flowstate:metrics", {
          detail: event,
          bubbles: true,
          cancelable: false,
        });
        window.dispatchEvent(busEvent);
      }
    } catch (e) {
      console.warn("[flowstate:telemetry] failed to emit bus event", e);
    }
  }, []);
}

import type { BusEnvelopeV1, PipelineEnvelope } from "@world-engine/engine";
import { BusEnvelopeV1Schema } from "@world-engine/engine";

/**
 * WsBusClient
 *
 * IDE-Web client for subscribing to pipeline events via the bus hub.
 * Features:
 * - Auto-reconnect
 * - Local cache of recent envelopes
 * - Callbacks for stage events
 * - Trace-aware (groups events by traceId)
 */

export interface BusClientHandlers {
    onConnect?: () => void;
    onDisconnect?: () => void;
    onEnvelope?: (env: BusEnvelopeV1) => void;
    onPipelineRunStarted?: (env: PipelineEnvelope) => void;
    onPipelineStageStarted?: (env: PipelineEnvelope) => void;
    onPipelineStageCompleted?: (env: PipelineEnvelope) => void;
    onPipelineRunCompleted?: (env: PipelineEnvelope) => void;
    onError?: (err: Error) => void;
}

export interface BusClientConfig {
    /** URL of bus hub (e.g., "ws://localhost:3000") */
    url: string;
    /** Auto-reconnect attempts (-1 = infinite) */
    reconnectAttempts?: number;
    /** Delay between reconnect attempts (ms) */
    reconnectDelayMs?: number;
    /** Max envelopes to cache per trace */
    maxEnvelopesPerTrace?: number;
}

export class WsBusClient {
    private config: Required<BusClientConfig>;
    private ws: WebSocket | null = null;
    private handlers: BusClientHandlers;
    private envelopesCache = new Map<string, BusEnvelopeV1[]>();
    private isConnecting = false;
    private reconnectCount = 0;

    constructor(config: BusClientConfig, handlers: BusClientHandlers = {}) {
        this.config = {
            url: config.url,
            reconnectAttempts: config.reconnectAttempts ?? 5,
            reconnectDelayMs: config.reconnectDelayMs ?? 1000,
            maxEnvelopesPerTrace: config.maxEnvelopesPerTrace ?? 200,
        };
        this.handlers = handlers;
    }

    /**
     * Connect to bus hub
     */
    connect(): Promise<void> {
        return new Promise((resolve, reject) => {
            if (this.isConnecting) {
                reject(new Error("Already connecting"));
                return;
            }

            this.isConnecting = true;

            try {
                this.ws = new WebSocket(this.config.url);

                this.ws.onopen = () => {
                    console.log("[WsBusClient] Connected to bus hub");
                    this.isConnecting = false;
                    this.reconnectCount = 0;
                    this.handlers.onConnect?.();
                    resolve();
                };

                this.ws.onmessage = (evt) => {
                    this.handleMessage(evt.data);
                };

                this.ws.onclose = () => {
                    console.log("[WsBusClient] Disconnected from bus hub");
                    this.isConnecting = false;
                    this.handlers.onDisconnect?.();
                    this.maybeReconnect();
                };

                this.ws.onerror = (evt) => {
                    const err = new Error(`WS error: ${evt.type}`);
                    console.error("[WsBusClient] Error:", err);
                    this.handlers.onError?.(err);
                    reject(err);
                };
            } catch (err) {
                this.isConnecting = false;
                reject(err);
            }
        });
    }

    /**
     * Disconnect from bus hub
     */
    disconnect(): void {
        if (this.ws) {
            this.ws.close();
            this.ws = null;
        }
    }

    /**
     * Get cached envelopes for a trace
     */
    getTraceEnvelopes(traceId: string): BusEnvelopeV1[] {
        return this.envelopesCache.get(traceId) ?? [];
    }

    /**
     * Get recent envelopes (last N by timestamp across all traces)
     */
    getRecentEnvelopes(count: number): BusEnvelopeV1[] {
        const all: BusEnvelopeV1[] = [];
        for (const envs of this.envelopesCache.values()) {
            all.push(...envs);
        }
        // Sort by timestamp desc, take top N
        return all
            .sort((a, b) => new Date(b.ts).getTime() - new Date(a.ts).getTime())
            .slice(0, count);
    }

    /**
     * Clear cache for a trace
     */
    clearTrace(traceId: string): void {
        this.envelopesCache.delete(traceId);
    }

    /**
     * Get all active traceIds in cache
     */
    getActiveTraceIds(): string[] {
        return Array.from(this.envelopesCache.keys());
    }

    /** --- Internal --- */

    private handleMessage(data: string): void {
        try {
            const parsed = JSON.parse(data);
            const validation = BusEnvelopeV1Schema.safeParse(parsed);

            if (!validation.success) {
                console.warn("[WsBusClient] Invalid envelope:", validation.error);
                return;
            }

            const env = validation.data as BusEnvelopeV1;

            // Cache it
            this.cacheEnvelope(env);

            // Notify generic handler
            this.handlers.onEnvelope?.(env);

            // Notify type-specific handlers
            if (env.type === "pipeline.run.started") {
                this.handlers.onPipelineRunStarted?.(env as PipelineEnvelope);
            } else if (env.type === "pipeline.stage.started") {
                this.handlers.onPipelineStageStarted?.(env as PipelineEnvelope);
            } else if (env.type === "pipeline.stage.completed") {
                this.handlers.onPipelineStageCompleted?.(env as PipelineEnvelope);
            } else if (env.type === "pipeline.run.completed") {
                this.handlers.onPipelineRunCompleted?.(env as PipelineEnvelope);
            }
        } catch (err) {
            const error = err instanceof Error ? err : new Error(String(err));
            console.error("[WsBusClient] Failed to handle message:", error);
            this.handlers.onError?.(error);
        }
    }

    private cacheEnvelope(env: BusEnvelopeV1): void {
        const { traceId } = env;

        if (!this.envelopesCache.has(traceId)) {
            this.envelopesCache.set(traceId, []);
        }

        const envs = this.envelopesCache.get(traceId)!;
        envs.push(env);

        // Trim if over limit
        if (envs.length > this.config.maxEnvelopesPerTrace) {
            envs.shift();
        }
    }

    private maybeReconnect(): void {
        if (
            this.config.reconnectAttempts === -1 ||
            this.reconnectCount < this.config.reconnectAttempts
        ) {
            this.reconnectCount++;
            const delay = this.config.reconnectDelayMs * Math.pow(1.5, this.reconnectCount - 1);
            console.log(`[WsBusClient] Reconnecting in ${delay}ms (attempt ${this.reconnectCount})`);
            setTimeout(() => this.connect().catch(console.error), delay);
        }
    }

    /**
     * Adapter API: subscribe to a specific event type (for legacy hooks)
     * Returns an unsubscriber function.
     */
    subscribe(
        eventType: string,
        handler: (envelope: BusEnvelopeV1) => void
    ): () => void {
        // Setup a map of subscriptions if not already
        if (!(this as any)._subscriptions) {
            (this as any)._subscriptions = new Map<string, Set<Function>>();
        }

        const subs = (this as any)._subscriptions as Map<string, Set<Function>>;

        if (!subs.has(eventType)) {
            subs.set(eventType, new Set());
        }

        subs.get(eventType)!.add(handler);

        // Augment onEnvelope to dispatch to subscribers if not already done
        if (!(this as any)._originalOnEnvelope) {
            (this as any)._originalOnEnvelope = this.handlers.onEnvelope;
            this.handlers.onEnvelope = (env: BusEnvelopeV1) => {
                // Call original handler
                (this as any)._originalOnEnvelope?.(env);

                // Dispatch to subscriptions
                const handlers = subs.get(env.type);
                if (handlers) {
                    handlers.forEach((h) => h(env));
                }
            };
        }

        // Return unsubscriber
        return () => {
            subs.get(eventType)?.delete(handler);
        };
    }

    /**
     * Getter: is connection established?
     */
    get isConnected(): boolean {
        return this.ws?.readyState === WebSocket.OPEN;
    }
}

import type { BusEnvelope, MessageMap } from "@world-engine/protocol";
import { EnvelopeSchema } from "@world-engine/protocol";
import { makeEnv, type AnyEnv } from "./protocol";

type FromIde = { role: "ide"; instanceId: string };

export type Handlers = {
  onWelcome: (env: BusEnvelope<"system.welcome", MessageMap["system.welcome"]>) => void;

  onPtyOpened: (env: BusEnvelope<"pty.opened", MessageMap["pty.opened"]>) => void;
  onPtyOutput: (env: BusEnvelope<"pty.output", MessageMap["pty.output"]>) => void;
  onPreviewStats: (env: BusEnvelope<"preview.stats", MessageMap["preview.stats"]>) => void;
  onFilesChanged: (env: BusEnvelope<"files.changed", MessageMap["files.changed"]>) => void;

  onSimStart: (env: BusEnvelope<"sim.start", MessageMap["sim.start"]>) => void;
  onSimLog: (env: BusEnvelope<"sim.log", MessageMap["sim.log"]>) => void;
  onSimDone: (env: BusEnvelope<"sim.done", MessageMap["sim.done"]>) => void;

  onIdeCliRunResponse?: (
    env: BusEnvelope<"ide.cli.run.response", MessageMap["ide.cli.run.response"]>
  ) => void;
  onIdeFsReadResponse?: (
    env: BusEnvelope<"ide.fs.read.response", MessageMap["ide.fs.read.response"]>
  ) => void;

  onBrainChatDelta?: (
    env: BusEnvelope<"brain.chat.delta", MessageMap["brain.chat.delta"]>
  ) => void;
  onBrainChatDone?: (
    env: BusEnvelope<"brain.chat.done", MessageMap["brain.chat.done"]>
  ) => void;
  onBrainChatError?: (
    env: BusEnvelope<"brain.chat.error", MessageMap["brain.chat.error"]>
  ) => void;

  /** Optional lifecycle hooks for status banner */
  onOpen?: () => void;
  onClose?: (ev: CloseEvent) => void;
  onError?: (ev: Event) => void;
  onReconnectAttempt?: (attempt: number, delayMs: number) => void;
  onReconnectSuccess?: () => void;
};

export type WsClientOptions = {
  sessionId?: string;
  instanceId?: string;

  /** Reconnect policy */
  reconnect?: boolean;
  reconnectMaxDelayMs?: number; // cap
  reconnectBaseDelayMs?: number; // base
  reconnectJitterMs?: number; // +/- jitter

  /** Keep-alive */
  pingIntervalMs?: number; // 0 disables
};

type Outbound = { type: keyof MessageMap; payload: MessageMap[keyof MessageMap] };

export class WsClient {
  private url: string;
  private handlers: Handlers;
  private opts: Required<WsClientOptions>;

  private ws: WebSocket | null = null;

  private sessionId: string;
  private instanceId: string;
  private token = "";

  private isWelcomed = false;
  private isManuallyClosed = false;

  private outboundQueue: Outbound[] = [];

  private reconnectAttempt = 0;
  private pingTimer: number | null = null;

  constructor(url: string, handlers: Handlers, options: WsClientOptions = {}) {
    this.url = url;
    this.handlers = handlers;

    this.opts = {
      sessionId: options.sessionId ?? "local",
      instanceId: options.instanceId ?? "ide_1",

      reconnect: options.reconnect ?? true,
      reconnectMaxDelayMs: options.reconnectMaxDelayMs ?? 15_000,
      reconnectBaseDelayMs: options.reconnectBaseDelayMs ?? 300,
      reconnectJitterMs: options.reconnectJitterMs ?? 250,

      pingIntervalMs: options.pingIntervalMs ?? 20_000,
    };

    this.sessionId = this.opts.sessionId;
    this.instanceId = this.opts.instanceId;

    this.connect();
  }

  /** Public API */
  close(code = 1000, reason = "client_close") {
    this.isManuallyClosed = true;
    this.stopPing();
    this.ws?.close(code, reason);
  }

  /** Ready = welcomed + socket open */
  isReady(): boolean {
    return !!this.ws && this.ws.readyState === WebSocket.OPEN && this.isWelcomed;
  }

  /** Send typed env. Queues until welcome. */
  send<T extends keyof MessageMap>(type: T, payload: MessageMap[T]): void {
    if (!this.ws || this.ws.readyState !== WebSocket.OPEN || !this.isWelcomed) {
      this.outboundQueue.push({ type, payload } as Outbound);
      return;
    }

    const env = makeEnv(
      this.sessionId,
      { role: "ide", instanceId: this.instanceId },
      type,
      payload,
      this.token
    );

    this.ws.send(JSON.stringify(env));
  }

  // -------------------- Internals --------------------

  private connect() {
    this.isManuallyClosed = false;
    this.isWelcomed = false;

    const ws = new WebSocket(this.url);
    this.ws = ws;

    ws.onopen = () => {
      this.handlers.onOpen?.();
      this.reconnectAttempt = 0;

      // Handshake without auth (allowed by wsHub middleware)
      ws.send(
        JSON.stringify({
          v: 2,
          id: this.randomId("hello"),
          type: "system.hello",
          ts: Date.now(),
          from: { role: "ide", instanceId: this.instanceId },
          sessionId: this.sessionId,
          payload: { requestedRole: "ide" },
        })
      );

      this.startPing();
    };

    ws.onmessage = (evt) => this.onMessage(evt);

    ws.onerror = (ev) => {
      this.handlers.onError?.(ev);
      // onclose will follow in most implementations; reconnect logic is centralized there.
    };

    ws.onclose = (ev) => {
      this.stopPing();
      this.handlers.onClose?.(ev);

      if (this.isManuallyClosed) return;
      if (!this.opts.reconnect) return;

      this.scheduleReconnect();
    };
  }

  private scheduleReconnect() {
    this.reconnectAttempt++;

    const base = this.opts.reconnectBaseDelayMs;
    const cap = this.opts.reconnectMaxDelayMs;
    const jitter = this.opts.reconnectJitterMs;

    // exponential backoff: base * 2^(attempt-1)
    const exp = base * Math.pow(2, Math.max(0, this.reconnectAttempt - 1));
    const clamped = Math.min(cap, exp);

    // jitter in [-jitter, +jitter]
    const j = (Math.random() * 2 - 1) * jitter;
    const delayMs = Math.max(0, Math.floor(clamped + j));

    this.handlers.onReconnectAttempt?.(this.reconnectAttempt, delayMs);

    window.setTimeout(() => {
      if (this.isManuallyClosed) return;
      this.connect();
      this.handlers.onReconnectSuccess?.();
    }, delayMs);
  }

  private onMessage(evt: MessageEvent) {
    const raw = String(evt.data);

    let parsed: unknown;
    try {
      parsed = JSON.parse(raw);
    } catch {
      return;
    }

    const checked = EnvelopeSchema.safeParse(parsed);
    if (!checked.success) return;

    const env = checked.data as AnyEnv;

    // Fast-path: welcome initializes session/token + flush queue
    if (env.type === "system.welcome") {
      const typed = env as BusEnvelope<"system.welcome", MessageMap["system.welcome"]>;
      this.sessionId = typed.sessionId;
      this.instanceId = typed.payload.assignedInstanceId;
      this.token = (typed.auth as any)?.token ?? "";

      this.isWelcomed = true;
      this.handlers.onWelcome(typed);

      this.flushQueue();
      return;
    }

    this.dispatch(env);
  }

  private flushQueue() {
    if (!this.isReady()) return;
    const pending = this.outboundQueue;
    this.outboundQueue = [];
    for (const item of pending) {
      // item is safe; makeEnv validates contract upstream.
      this.send(item.type as any, item.payload as any);
    }
  }

  private dispatch(env: AnyEnv) {
    // Dispatch table keeps this maintainable + avoids if/else ladder.
    const t = env.type as keyof MessageMap;

    switch (t) {
      case "pty.opened":
        this.handlers.onPtyOpened(env as any);
        return;
      case "pty.output":
        this.handlers.onPtyOutput(env as any);
        return;
      case "preview.stats":
        this.handlers.onPreviewStats(env as any);
        return;
      case "files.changed":
        this.handlers.onFilesChanged(env as any);
        return;

      case "sim.start":
        this.handlers.onSimStart(env as any);
        return;
      case "sim.log":
        this.handlers.onSimLog(env as any);
        return;
      case "sim.done":
        this.handlers.onSimDone(env as any);
        return;

      case "ide.cli.run.response":
        this.handlers.onIdeCliRunResponse?.(env as any);
        return;
      case "ide.fs.read.response":
        this.handlers.onIdeFsReadResponse?.(env as any);
        return;

      case "brain.chat.delta":
        this.handlers.onBrainChatDelta?.(env as any);
        return;
      case "brain.chat.done":
        this.handlers.onBrainChatDone?.(env as any);
        return;
      case "brain.chat.error":
        this.handlers.onBrainChatError?.(env as any);
        return;

      default:
        // Unknown/unused env types can be ignored safely.
        return;
    }
  }

  private startPing() {
    if (this.opts.pingIntervalMs <= 0) return;
    this.stopPing();

    this.pingTimer = window.setInterval(() => {
      // If your server supports a ping message type, emit it here.
      // Otherwise a no-op is fine; some browsers/proxies still keep TCP alive with traffic.
      if (!this.ws || this.ws.readyState !== WebSocket.OPEN) return;

      // Optional: if you have a "system.ping" contract, use this.send("system.ping", {...})
      // For now, send a tiny frame that still validates as JSON? No ΓÇö avoid invalid envelopes.
      // Best is to define a real contract later. Leaving ping silent prevents schema pollution.
    }, this.opts.pingIntervalMs);
  }

  private stopPing() {
    if (this.pingTimer != null) {
      clearInterval(this.pingTimer);
      this.pingTimer = null;
    }
  }

  private randomId(prefix: string): string {
    const r = Math.random().toString(16).slice(2);
    return `${prefix}_${Date.now().toString(16)}_${r}`;
  }
}

/**
 * IDE WebSocket Bus Client Extensions for Build Evidence.
 *
 * Add these methods to your existing WsBusClient in apps/ide-web/src/bus/wsClient.ts
 * or integrate them into your existing bus client architecture.
 *
 * Example usage:
 *   const bus = new WsBusClient("ws://localhost:3000", "ide-web");
 *   bus.connect();
 *   bus.onBuildEvidenceGenerated((packet, evidencePath) => {
 *     console.log("Build Evidence:", packet.bundle_hash);
 *   });
 *   bus.requestBuildEvidence({
 *     compiler: "vite",
 *     buildRoot: "apps/ide-web",
 *     runTwice: true
 *   });
 */

import {
    AnyBuildEvidenceBusMsgSchema,
    EVT_BUILD_EVIDENCE_GENERATED,
    EVT_BUILD_EVIDENCE_REQUEST,
    type BuildEvidenceGeneratedMsg,
} from "./buildEvidenceProtocol";

/** Browser-safe sha-like id (deterministic enough for envelope ids) */
export function makeEnvelopeId(type: string, source: string, ts: string) {
    // No crypto dependency required in browser; stable-ish.
    const s = `${type}:${source}:${ts}:${Math.random().toString(16).slice(2)}`;
    let h = 2166136261;
    for (let i = 0; i < s.length; i++) {
        h ^= s.charCodeAt(i);
        h = Math.imul(h, 16777619);
    }
    return `e_${(h >>> 0).toString(16)}_${Date.now().toString(16)}`;
}

type BusEnvelope = {
    v: "1";
    id: string;
    ts: string;
    type: string;
    source: string;
    data: any;
};

type Listener = (msg: any) => void;

export class WsBusClient {
    private ws: WebSocket | null = null;
    private listeners: Map<string, Set<Listener>> = new Map();

    constructor(private url: string, private source = "ide-web") { }

    connect() {
        if (
            this.ws &&
            (this.ws.readyState === WebSocket.OPEN || this.ws.readyState === WebSocket.CONNECTING)
        )
            return;

        this.ws = new WebSocket(this.url);

        this.ws.onmessage = (ev) => {
            let raw: unknown;
            try {
                raw = JSON.parse(String(ev.data));
            } catch {
                return;
            }

            const parsed = AnyBuildEvidenceBusMsgSchema.safeParse(raw);
            if (!parsed.success) return;

            const msg = parsed.data;
            const set = this.listeners.get(msg.type);
            if (set) for (const cb of set) cb(msg);
        };
    }

    on(type: string, cb: Listener) {
        const set = this.listeners.get(type) ?? new Set<Listener>();
        set.add(cb);
        this.listeners.set(type, set);
        return () => set.delete(cb);
    }

    send(type: string, data: any) {
        if (!this.ws || this.ws.readyState !== WebSocket.OPEN)
            throw new Error("WebSocket not open");
        const ts = new Date().toISOString();
        const env: BusEnvelope = {
            v: "1",
            id: makeEnvelopeId(type, this.source, ts),
            ts,
            type,
            source: this.source,
            data,
        };
        this.ws.send(JSON.stringify(env));
    }

    // ---- Build Evidence API ----

    requestBuildEvidence(req: {
        compiler: "vite" | "singlefile-esbuild";
        buildRoot: string;
        outDir?: string;
        mode?: string;
        runTypecheck?: boolean;
        runTwice?: boolean;
    }) {
        this.send(EVT_BUILD_EVIDENCE_REQUEST, req);
    }

    onBuildEvidenceGenerated(
        cb: (packet: BuildEvidenceGeneratedMsg["data"]["packet"], evidencePath?: string) => void
    ) {
        return this.on(EVT_BUILD_EVIDENCE_GENERATED, (msg: BuildEvidenceGeneratedMsg) => {
            cb(msg.data.packet, msg.data.evidencePath);
        });
    }
}

import { useEffect, useMemo, useRef } from "react";

interface Particle {
  x: number;
  y: number;
  r: number;
  c: string;
  vx: number;
  vy: number;
}

export function NeonPhysicsCanvas(props: { particleCount?: number }) {
  const particleCount = props.particleCount ?? 60;

  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const rafRef = useRef<number | null>(null);
  const intervalRef = useRef<number | null>(null);

  const colors = useMemo(() => ["#00f3ff", "#ffaa00", "#00ff66"], []);
  const mouse = useRef({ x: -1000, y: -1000, active: false });

  // Physics constants
  const GRAVITY = 0.15;
  const FLOOR_BOUNCE = -0.7;
  const WALL_BOUNCE = -0.7;
  const MOUSE_REPEL_RADIUS = 150;
  const MOUSE_FORCE = 2;
  const PULSE_FORCE = 15;

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let w = 0;
    let h = 0;

    const resize = () => {
      const dpr = Math.max(1, Math.min(2, window.devicePixelRatio || 1));
      w = Math.floor(window.innerWidth);
      h = Math.floor(window.innerHeight);

      canvas.width = Math.floor(w * dpr);
      canvas.height = Math.floor(h * dpr);
      canvas.style.width = `${w}px`;
      canvas.style.height = `${h}px`;

      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    };

    resize();
    window.addEventListener("resize", resize);

    const rand = (min: number, max: number) => min + Math.random() * (max - min);

    const makeParticle = (): Particle => ({
      x: Math.random() * w,
      y: Math.random() * h * 0.5,
      r: rand(2, 6),
      c: colors[(Math.random() * colors.length) | 0],
      vx: rand(-2, 2),
      vy: rand(-2, 2),
    });

    const particles: Particle[] = Array.from({ length: particleCount }, makeParticle);

    const pulse = (originX: number, originY: number, strength: number) => {
      for (const p of particles) {
        const dx = p.x - originX;
        const dy = p.y - originY;
        const dist = Math.sqrt(dx * dx + dy * dy) + 0.1;
        let force = strength * (100 / dist);
        force = Math.min(force, 20);

        p.vx += (dx / dist) * force;
        p.vy += (dy / dist) * force - 5;
      }
    };

    const update = (p: Particle) => {
      p.vy += GRAVITY;

      p.x += p.vx;
      p.y += p.vy;

      // floor
      if (p.y + p.r > h) {
        p.y = h - p.r;
        p.vy *= FLOOR_BOUNCE;
        p.vx *= 0.95;
      }
      // ceiling
      if (p.y - p.r < 0) {
        p.y = p.r;
        p.vy *= -0.5;
      }
      // walls
      if (p.x + p.r > w) {
        p.x = w - p.r;
        p.vx *= WALL_BOUNCE;
      } else if (p.x - p.r < 0) {
        p.x = p.r;
        p.vx *= WALL_BOUNCE;
      }

      // mouse repel
      if (mouse.current.active) {
        const dx = p.x - mouse.current.x;
        const dy = p.y - mouse.current.y;
        const dist = Math.sqrt(dx * dx + dy * dy);

        if (dist > 0 && dist < MOUSE_REPEL_RADIUS) {
          const fx = dx / dist;
          const fy = dy / dist;
          const mag = (MOUSE_REPEL_RADIUS - dist) / MOUSE_REPEL_RADIUS;

          p.vx += fx * mag * MOUSE_FORCE;
          p.vy += fy * mag * MOUSE_FORCE;
        }
      }
    };

    const draw = (p: Particle) => {
      if (!ctx) return;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      ctx.fillStyle = p.c;
      ctx.shadowBlur = 10;
      ctx.shadowColor = p.c;
      ctx.fill();
      ctx.shadowBlur = 0;
    };

    const animate = () => {
      ctx.clearRect(0, 0, w, h);
      for (const p of particles) {
        update(p);
        draw(p);
      }
      rafRef.current = requestAnimationFrame(animate);
    };

    // pointer events
    const onMouseMove = (e: MouseEvent) => {
      mouse.current.x = e.clientX;
      mouse.current.y = e.clientY;
      mouse.current.active = true;
    };

    const onTouchMove = (e: TouchEvent) => {
      const t = e.touches[0];
      if (!t) return;
      mouse.current.x = t.clientX;
      mouse.current.y = t.clientY;
      mouse.current.active = true;
    };

    const onPointerLeave = () => {
      mouse.current.active = false;
    };

    const onClick = (e: MouseEvent) => pulse(e.clientX, e.clientY, PULSE_FORCE);

    const onTouchStart = (e: TouchEvent) => {
      const t = e.touches[0];
      if (!t) return;
      pulse(t.clientX, t.clientY, PULSE_FORCE);
    };

    window.addEventListener("mousemove", onMouseMove);
    window.addEventListener("touchmove", onTouchMove, { passive: true });
    window.addEventListener("mouseout", onPointerLeave);
    window.addEventListener("touchend", onPointerLeave);
    window.addEventListener("click", onClick);
    window.addEventListener("touchstart", onTouchStart, { passive: true });

    // stir automation
    intervalRef.current = window.setInterval(() => {
      const rx = Math.random() * w;
      const ry = h - Math.random() * 200;
      pulse(rx, ry, PULSE_FORCE);
    }, 3000);

    animate();

    return () => {
      window.removeEventListener("resize", resize);
      window.removeEventListener("mousemove", onMouseMove);
      window.removeEventListener("touchmove", onTouchMove as any);
      window.removeEventListener("mouseout", onPointerLeave);
      window.removeEventListener("touchend", onPointerLeave);
      window.removeEventListener("click", onClick);
      window.removeEventListener("touchstart", onTouchStart as any);

      if (intervalRef.current) window.clearInterval(intervalRef.current);
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    };
  }, [colors, particleCount]);

  return (
    <canvas ref={canvasRef} className="fixed inset-0 -z-20 neon-bg-radial" aria-hidden="true" />
  );
}

import { Play, Shield, Zap } from "lucide-react";
import { useEffect, useState } from "react";
import { GlassPanel, NeonButton, NeonTitle } from "../ui/neon";

/**
 * LauncherControlPage ΓÇö Master control panel for all services
 *
 * Shows status of all running services and provides one-click launch/shutdown.
 */

interface ServiceStatus {
  name: string;
  url: string;
  port: number;
  status: "running" | "stopped" | "checking";
  color: string;
  icon: React.ReactNode;
}

export function LabLauncherControlPage() {
  const [services, setServices] = useState<ServiceStatus[]>([
    {
      name: "Nucleus Hub",
      url: "ws://localhost:3000",
      port: 3000,
      status: "checking",
      color: "text-cyan-400",
      icon: <Zap size={24} />,
    },
    {
      name: "IDE Web",
      url: "http://localhost:5173",
      port: 5173,
      status: "checking",
      color: "text-green-400",
      icon: <Shield size={24} />,
    },
    {
      name: "Preview Runtime",
      url: "http://localhost:5174",
      port: 5174,
      status: "checking",
      color: "text-magenta-400",
      icon: <Play size={24} />,
    },
    {
      name: "Python Sidecar",
      url: "http://127.0.0.1:8001",
      port: 8001,
      status: "checking",
      color: "text-yellow-400",
      icon: <Zap size={24} />,
    },
  ]);

  const [isLaunching, setIsLaunching] = useState(false);
  const [launchOutput, setLaunchOutput] = useState<string[]>([]);

  // Check service health
  useEffect(() => {
    const checkServices = async () => {
      const updated = await Promise.all(
        services.map(async (service) => {
          try {
            const url = service.port === 3000 ? `http://localhost:${service.port}` : service.url;
            const controller = new AbortController();
            const timeoutId = setTimeout(() => controller.abort(), 2000);

            const response = await fetch(url, {
              signal: controller.signal,
              method: "HEAD",
            }).catch(() => null);

            clearTimeout(timeoutId);

            return {
              ...service,
              status: response ? ("running" as const) : ("stopped" as const),
            };
          } catch {
            return { ...service, status: "stopped" as const };
          }
        }),
      );
      setServices(updated);
    };

    checkServices();
    const interval = setInterval(checkServices, 5000); // Check every 5 seconds
    return () => clearInterval(interval);
  }, []);

  const launchAll = () => {
    setIsLaunching(true);
    setLaunchOutput([
      "≡ƒÜÇ Starting all services...",
      "This window will close when all services are running.",
      "",
      "Monitor progress in your terminal.",
    ]);

    // Simulate opening the launcher script in a new terminal
    // In a real implementation, this would call a backend API or spawn a process
    setTimeout(() => {
      setLaunchOutput((prev) => [
        ...prev,
        "[NUCLEUS] Starting on port 3000...",
        "[IDE-WEB] Starting on port 5173...",
        "[PREVIEW] Starting on port 5174...",
        "[PYTHON] Starting on port 8001...",
      ]);
    }, 500);

    setTimeout(() => {
      setLaunchOutput((prev) => [
        ...prev,
        "",
        "Γ£ô All services launched!",
        "Γ£ô Check your terminal for logs",
        "",
      ]);
      setIsLaunching(false);

      // Refresh service status
      setTimeout(() => {
        alert(
          "Services launched! If you ran the launcher separately, services should be online now. Click OK to refresh status.",
        );
        window.location.reload();
      }, 2000);
    }, 3000);
  };

  const openService = (url: string) => {
    window.open(url, "_blank");
  };

  const allRunning = services.every((s) => s.status === "running");
  const anyRunning = services.some((s) => s.status === "running");

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      {/* Header */}
      <GlassPanel className="rounded-2xl p-8 text-center">
        <NeonTitle as="h1" className="text-5xl mb-2">
          World Engine
        </NeonTitle>
        <p className="text-white/60 text-lg">Master Control & Service Launcher</p>
      </GlassPanel>

      {/* Big Launch Button */}
      <GlassPanel className="rounded-2xl p-8 bg-gradient-to-br from-cyan-950/30 to-slate-950/30 border border-cyan-500/30">
        <div className="text-center space-y-4">
          <div className="text-6xl drop-shadow-[0_0_20px_rgba(0,243,255,0.4)]">ΓÜí</div>

          <h2 className="text-3xl font-bold text-white">LAUNCH ALL SERVICES</h2>
          <p className="text-white/70 mb-6">
            Start all services with one click. Open a terminal and run:
          </p>

          <code className="block bg-slate-900/50 p-4 rounded text-cyan-300 font-mono text-lg mb-6 border border-cyan-500/20">
            pnpm launch
          </code>

          <div className="flex gap-4 justify-center">
            <NeonButton onClick={launchAll} disabled={isLaunching || allRunning}>
              {isLaunching ? "LAUNCHING..." : allRunning ? "Γ£ô ALL RUNNING" : "LAUNCH NOW"}
            </NeonButton>

            {anyRunning && (
              <NeonButton
                variant="ghost"
                onClick={() => {
                  window.location.reload();
                }}
              >
                REFRESH STATUS
              </NeonButton>
            )}
          </div>

          {launchOutput.length > 0 && (
            <div className="mt-6 bg-slate-950/50 p-4 rounded text-left font-mono text-sm text-white/70 max-h-32 overflow-y-auto border border-white/10">
              {launchOutput.map((line, i) => (
                <div key={i}>{line}</div>
              ))}
            </div>
          )}
        </div>
      </GlassPanel>

      {/* Service Status Grid */}
      <div>
        <h3 className="font-bold text-white mb-4 flex items-center gap-2">
          <Shield size={16} className="text-cyan-400" />
          Service Status
        </h3>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {services.map((service) => (
            <GlassPanel
              key={service.name}
              className="p-4 hover:border-cyan-400/50 transition-colors cursor-pointer"
              onClick={() => service.status === "running" && openService(service.url)}
            >
              <div className="flex items-start justify-between mb-3">
                <div className="flex items-center gap-3">
                  <div className={`${service.color}`}>{service.icon}</div>
                  <div>
                    <div className="font-bold text-white">{service.name}</div>
                    <div className="text-xs text-white/50 font-mono">{service.url}</div>
                  </div>
                </div>

                <div
                  className={`px-3 py-1 rounded text-xs font-bold ${
                    service.status === "running"
                      ? "bg-green-500/20 text-green-300"
                      : service.status === "checking"
                        ? "bg-yellow-500/20 text-yellow-300"
                        : "bg-slate-500/20 text-slate-300"
                  }`}
                >
                  {service.status === "running"
                    ? "Γ£ô ONLINE"
                    : service.status === "checking"
                      ? "ΓÅ│ CHECKING"
                      : "Γ£ù OFFLINE"}
                </div>
              </div>

              {service.status === "running" && (
                <button
                  onClick={() => openService(service.url)}
                  className="w-full text-sm bg-cyan-500/10 hover:bg-cyan-500/20 text-cyan-300 py-1 rounded transition-colors"
                >
                  Open Service ΓåÆ
                </button>
              )}
            </GlassPanel>
          ))}
        </div>
      </div>

      {/* Instructions */}
      <GlassPanel className="rounded-2xl p-6 bg-slate-950/30">
        <h3 className="font-bold text-white mb-3 flex items-center gap-2">
          <Zap size={16} className="text-amber-400" />
          Quick Start
        </h3>

        <div className="space-y-2 text-sm text-white/70">
          <p>
            <span className="text-white font-mono">pnpm launch</span> ΓÇö Starts all services in
            parallel
          </p>
          <p>
            <span className="text-white font-mono">pnpm launch:complete</span> ΓÇö Same as above
          </p>
