/**
 * apps/ide-web/src/tools/recordScreen.ts
 *
 * Browser-based screen recording via getDisplayMedia + MediaRecorder.
 * Supports optional audio, duration limit, and locking to prevent overlaps.
 */

export type RecordScreenArgs = {
    durationSeconds?: number; // e.g. 12; default 10
    withAudio?: boolean;      // include system audio where supported; default false
    timeoutMs?: number;       // handler timeout; default 60000
};

export type RecordScreenResult = {
    mimeType: string;  // e.g. "video/webm"
    byteLength: number; // blob size in bytes
};

let recordingLock = false;

/**
 * Record screen using getDisplayMedia + MediaRecorder.
 *
 * Returns metadata about the recording (not the blob itself - too large for WS).
 * In a real app, you'd upload the blob to a server and return a URL/artifact ID.
 *
 * @throws Error if recording is already in progress or user denies permission
 */
export async function recordScreen(args: RecordScreenArgs): Promise<RecordScreenResult> {
    if (recordingLock) {
        throw new Error("record_screen blocked: recording already in progress");
    }
    recordingLock = true;

    try {
        const durationMs = Math.max(1, Number(args.durationSeconds ?? 10)) * 1000;
        const withAudio = Boolean(args.withAudio ?? false);

        console.log(`[recordScreen] Starting ${durationMs}ms capture with audio=${withAudio}`);

        // Request display media (screen/window share)
        const stream = await (navigator.mediaDevices as any).getDisplayMedia({
            video: {
                cursor: "always" as const,
            },
            audio: withAudio,
        });

        const chunks: BlobPart[] = [];

        // Choose best MIME type
        const mimeType = MediaRecorder.isTypeSupported("video/webm;codecs=vp9")
            ? "video/webm;codecs=vp9"
            : MediaRecorder.isTypeSupported("video/webm;codecs=vp8")
                ? "video/webm;codecs=vp8"
                : "video/webm";

        const rec = new MediaRecorder(stream, { mimeType });

        const stopPromise = new Promise<void>((resolve) => {
            rec.onstop = () => {
                console.log(`[recordScreen] Recording stopped`);
                resolve();
            };
        });

        rec.ondataavailable = (e) => {
            if (e.data && e.data.size > 0) {
                chunks.push(e.data);
                console.log(`[recordScreen] Chunk: ${e.data.size} bytes`);
            }
        };

        rec.start(250); // push data every 250ms
        console.log(`[recordScreen] Recorder started`);

        // Auto-stop after duration
        const timer = setTimeout(() => {
            console.log(`[recordScreen] Auto-stopping after ${durationMs}ms`);
            try {
                rec.stop();
            } catch (e) {
                console.warn(`[recordScreen] Error stopping recorder:`, e);
            }
        }, durationMs);

        // Stop if user ends screen share early
        const videoTrack = stream.getVideoTracks()[0];
        if (videoTrack) {
            videoTrack.onended = () => {
                console.log(`[recordScreen] User ended screen share`);
                try {
                    rec.stop();
                } catch (e) {
                    console.warn(`[recordScreen] Error stopping recorder:`, e);
                }
            };
        }

        // Wait for recorder to stop
        await stopPromise;
        clearTimeout(timer);

        // Stop all tracks
        for (const track of stream.getTracks()) {
            track.stop();
        }

        const blob = new Blob(chunks, { type: rec.mimeType || "video/webm" });
        console.log(`[recordScreen] Finished. Total size: ${blob.size} bytes, MIME: ${blob.type}`);

        return {
            mimeType: blob.type,
            byteLength: blob.size,
        };
    } finally {
        recordingLock = false;
    }
}

/**
 * apps/ide-web/src/tools/toolHandler.ts
 *
 * Handles tool.command.v1 envelopes from Nucleus.
 * Executes local tools (record_screen) and responds with tool.effect.v1.
 */

import { recordScreen, type RecordScreenArgs } from "./recordScreen";

export interface AnyEnv {
    v: 2;
    type: string;
    id?: string;
    ts?: number;
    from?: { role: string; instanceId?: string };
    sessionId?: string;
    traceId?: string;
    messageId?: string;
    payload?: any;
}

/**
 * Handle tool.command.v1 from Nucleus.
 * Executes the tool and sends tool.effect.v1 back.
 *
 * @param env - Incoming tool.command.v1 envelope
 * @param send - Function to send response envelope back to WS
 */
export async function handleToolCommand(env: AnyEnv, send: (e: AnyEnv) => void) {
    const call = env.payload;
    const toolCallId = call?.toolCallId;
    const name = call?.name as string;
    const args = call?.args ?? {};
    const traceId = env.traceId;
    const sessionId = env.sessionId;

    console.log(`[toolHandler] Executing ${name} (toolCallId=${toolCallId})`);

    try {
        if (name === "record_screen") {
            const result = await recordScreen({
                durationSeconds: args.durationSeconds,
                withAudio: args.withAudio,
                timeoutMs: args.timeoutMs,
            } as RecordScreenArgs);

            send({
                v: 2,
                type: "tool.effect.v1",
                traceId,
                sessionId,
                payload: {
                    toolCallId,
                    name,
                    status: "ok",
                    result,
                },
            });
            console.log(`[toolHandler] ${name} completed successfully`);
            return;
        }

        // Unknown tool on IDE
        throw new Error(`IDE cannot execute tool: ${name}`);
    } catch (e: any) {
        const errorMsg = String(e?.message ?? e);
        console.error(`[toolHandler] ${name} failed:`, errorMsg);

        send({
            v: 2,
            type: "tool.effect.v1",
            traceId,
            sessionId,
            payload: {
                toolCallId,
                name,
                status: "error",
                error: { message: errorMsg },
            },
        });
    }
}

/**
 * Optional: Display tool effects in the UI (e.g., query_lexicon results).
 */
export function displayToolEffect(env: AnyEnv) {
    const payload = env.payload;
    const name = payload?.name as string;
    const status = payload?.status as string;

    if (status === "ok") {
        console.log(`[toolHandler] ${name} succeeded:`, payload.result);
    } else {
        console.error(`[toolHandler] ${name} failed: ${payload?.error?.message}`);
    }
}

/**
 * ChatClient - WebSocket-based agentic chat interface (engine-grade)
 *
 * Handles:
 * - WebSocket connection to Nucleus root hub (ws://localhost:3000)
 * - System handshake with system.hello / system.welcome
 * - Chat message sending (with world context)
 * - Streaming response rendering (token-by-token)
 * - Tool execution (local UI tools)
 * - Citation rendering
 * - Memory persistence
 *
 * Hardened against undefined errors with real close diagnostics.
 */

import type {
    ChatRequest,
    ToolCall,
    ToolResult
} from "@world-engine/protocol";

export interface ChatClientConfig {
    userId: string;
    convoId: string;
    wsUrl?: string;
    onMessage?: (_text: string) => void;
    onToolCall?: (_tool: ToolCall) => Promise<void>;
    onToolsQueued?: (_tools: ToolCall[]) => void;
    onToolCommand?: (_env: any) => Promise<void>; // Handle tool.command.v1
    onToolEffect?: (_env: any) => void;            // Display tool.effect.v1 results
    onCitation?: (_url: string, _title: string, _snippet?: string) => void;
    onMemoryWrite?: (key: string, value: string) => void;
    onError?: (error: string) => void;
    onStreamStart?: () => void;
    onStreamEnd?: () => void;
}

/**
 * Engine-grade WebSocket diagnostic message
 */
interface WsDiagnostic {
    event: "open" | "error" | "close";
    url: string;
    readyState?: number;
    code?: number;
    reason?: string;
    wasClean?: boolean;
}

export class ChatClient {
    private readonly config: ChatClientConfig;
    private ws: WebSocket | null = null;
    private pendingTraceId: string | null = null;
    private sessionId: string | null = null;
    private sessionToken: string | null = null;
    private instanceId: string | null = null;
    private handshakeDone = false;

    constructor(config: ChatClientConfig) {
        this.config = {
            wsUrl: config.wsUrl || "ws://localhost:3000",
            userId: config.userId,
            convoId: config.convoId,
            onMessage: config.onMessage,
            onToolCall: config.onToolCall,
            onCitation: config.onCitation,
            onMemoryWrite: config.onMemoryWrite,
            onError: config.onError,
            onStreamStart: config.onStreamStart,
            onStreamEnd: config.onStreamEnd,
        } as ChatClientConfig;
    }

    /**
     * Format WebSocket diagnostics for display
     */
    private _formatDiagnostic(d: WsDiagnostic): string {
        return [
            `[${d.event.toUpperCase()}]`,
            `url=${d.url}`,
            ...(d.readyState !== undefined ? [`readyState=${d.readyState}`] : []),
            ...(d.code !== undefined ? [`code=${d.code}`] : []),
            ...(d.reason ? [`reason="${d.reason}"`] : []),
            ...(d.wasClean !== undefined ? [`clean=${d.wasClean}`] : [])
        ].join(" ");
    }

    connect(): Promise<void> {
        return new Promise((resolve, reject) => {
            try {
                const url = this.config.wsUrl!;
                console.log(`[chat] Connecting to ${url}`);

                this.ws = new WebSocket(url);

                const handleWelcome = () => {
                    console.log("[chat] Handshake complete!", {
                        sessionId: this.sessionId,
                        instanceId: this.instanceId,
                    });
                    this.ws!.removeEventListener("open", handleOpen);
                    resolve();
                };

                const handleOpen = () => {
                    console.log("[chat] WebSocket opened, sending system.hello handshake");
                    this._sendHandshake();
                    // Set a timeout to wait for system.welcome response
                    const timeout = setTimeout(() => {
                        if (!this.handshakeDone) {
                            const err = `Handshake timeout after 5s: no system.welcome from ${url}`;
                            console.error("[chat]", err);
                            reject(new Error(err));
                            this.ws?.close();
                        }
                    }, 5000);
                    // Store timeout so we can clear it when welcome arrives
                    (this.ws as any)._handshakeTimeout = timeout;
                };

                this.ws.addEventListener("open", handleOpen);

                this.ws.onmessage = (event) => {
                    try {
                        const data = JSON.parse(event.data);
                        console.log("[chat] Received:", data.type || data.kind);

                        // Handle handshake response
                        if (data.type === "system.welcome") {
                            this.sessionId = data.sessionId;
                            this.sessionToken = data.auth?.token;
                            this.instanceId = data.payload?.assignedInstanceId;
                            this.handshakeDone = true;
                            const timeout = (this.ws as any)._handshakeTimeout;
                            if (timeout) clearTimeout(timeout);
                            handleWelcome();
                            return;
                        }

                        // Handle other messages after handshake is complete
                        if (this.handshakeDone) {
                            this._handleMessage(data);
                        }
                    } catch (err) {
                        console.error("[chat] Failed to parse message:", err);
                    }
                };

                this.ws.onerror = (event: Event) => {
                    // Browser events give no details; rely on onclose
                    const diagnostic: WsDiagnostic = {
                        event: "error",
                        url,
                        readyState: this.ws?.readyState ?? 0,
                    };
                    const msg = `WebSocket error event: ${this._formatDiagnostic(diagnostic)}`;
                    console.error("[chat]", msg, event);
                    // Don't reject here; wait for onclose for details
                };

                this.ws.onclose = (event: CloseEvent) => {
                    // Now we have the real close reason
                    const diagnostic: WsDiagnostic = {
                        event: "close",
                        url,
                        readyState: this.ws?.readyState ?? 0,
                        code: event.code,
                        reason: event.reason || "(no reason)",
                        wasClean: event.wasClean,
                    };
                    const msg = `[chat] Disconnected: ${this._formatDiagnostic(diagnostic)}`;
                    console.log(msg);

                    if (this.handshakeDone) {
                        // Connection closed before handshake complete
                        const fullErr = `Failed to connect and handshake: ${this._formatDiagnostic(diagnostic)}`;
                        console.error("[chat]", fullErr);
                        reject(new Error(fullErr));
                    } else {
                        // Connection closed after successful handshake
                        this.config.onError?.(msg);
                    }
                    this.handshakeDone = false;
                };
            } catch (err) {
                const msg = `WebSocket initialization error: ${err instanceof Error ? err.message : String(err)}`;
                console.error("[chat]", msg);
                reject(new Error(msg));
            }
        });
    }

    private _sendHandshake(): void {
        const helloEnvelope = {
            v: 2,
            id: this._generateId(),
            type: "system.hello",
            ts: Date.now(),
            from: {
                role: "ide",
                instanceId: this._generateId("client")
            },
            sessionId: "",
            payload: {
                requestedRole: "ide"
            }
        };

        if (this.ws?.readyState === WebSocket.OPEN) {
            this.ws.send(JSON.stringify(helloEnvelope));
            console.log("[chat] Sent system.hello handshake");
        }
    }

    private _generateId(prefix = "msg"): string {
        return `${prefix}_${Date.now().toString(16)}_${Math.random().toString(16).slice(2)}`;
    }

    disconnect(): void {
        this.ws?.close();
        this.ws = null;
    }

    /**
     * Send a tool effect back to Nucleus
     * (used when IDE completes a tool.command.v1 like record_screen)
     */
    sendToolEffect(traceId: string, toolCallId: string, name: string, status: string, resultOrError: any): void {
        if (this.ws?.readyState !== WebSocket.OPEN) {
            throw new Error("WebSocket not connected");
        }

        const payload = status === "ok"
            ? { toolCallId, name, status, result: resultOrError }
            : { toolCallId, name, status, error: { message: resultOrError } };

        const envelope = {
            v: 2,
            id: this._generateId("eff"),
            type: "tool.effect.v1",
            ts: Date.now(),
            from: {
                role: "ide",
                instanceId: this.instanceId || "ide_unknown"
            },
            sessionId: this.sessionId,
            traceId,
            payload,
        };

        this.ws.send(JSON.stringify(envelope));
    }

    /**
     * Send a chat message with context
     */
    async sendMessage(
        text: string,
        context?: Record<string, any>
    ): Promise<void> {
        if (this.ws?.readyState !== WebSocket.OPEN) {
            throw new Error("WebSocket not connected");
        }

        if (!this.handshakeDone || !this.sessionId || !this.sessionToken) {
            throw new Error("Handshake not complete");
        }

        const traceId = this._generateId("trace");
        this.pendingTraceId = traceId;

        const chatRequest: ChatRequest = {
            convoId: this.config.convoId,
            userId: this.config.userId,
            text,
            persona: "general",
            recentHistory: [], // TODO: fetch from state
            context: context || {
                mapId: "default",
                playerPos: [0, 0, 0],
                visibleEntities: [],
            },
        };

        // Use BusEnvelope format for Nucleus wire protocol
        const envelope = {
            v: 2,
            id: this._generateId("msg"),
            type: "chat.request.v1",
            ts: Date.now(),
            from: {
                role: "ide",
                instanceId: this.instanceId || "ide_unknown"
            },
            sessionId: this.sessionId,
            nonce: this._generateId("nonce"),
            auth: {
                kind: "session" as const,
                token: this.sessionToken
            },
            payload: chatRequest
        };

        console.log(`[chat] Sending request ${traceId}: "${text.slice(0, 50)}..."`);
        this.config.onStreamStart?.();

        this.ws.send(JSON.stringify(envelope));
    }

    /**
     * Handle messages from Nucleus (after handshake)
     * Supports new streaming protocol: chat.delta.v1, chat.tool_call.v1, chat.done.v1
     */
    private _handleMessage(env: any): void {
        const { type, payload, traceId, messageId } = env;

        // Ignore if not for our current request
        if (traceId !== this.pendingTraceId) {
            console.debug(`[chat] Ignoring event for different trace: ${traceId}`);
            return;
        }

        switch (type) {
            // Stream lifecycle events
            case "chat.stream.started.v1": {
                console.log(`[chat] Stream started: ${messageId}`);
                this.config.onStreamStart?.();
                break;
            }

            // Token/delta streaming
            case "chat.delta.v1": {
                const textDelta = payload?.text_delta || "";
                if (textDelta) {
                    this.config.onMessage?.(textDelta);
                }
                break;
            }

            // Tool invocation
            case "chat.tool_call.v1": {
                const toolPayload = payload?.payload || payload;
                const tool: ToolCall = {
                    name: toolPayload.name || "",
                    args: toolPayload.arguments || {},
                    timeout: toolPayload.timeout || 30000,
                    critical: toolPayload.critical || false,
                };
                // Queue tool calls, don't execute until stream.done
                this._queueToolCall(tool);
                break;
            }

            // Stream completion
            case "chat.done.v1": {
                console.log(`[chat] Stream done: ${payload?.stop_reason}`);
                // Execute any queued tool calls here
                this._executeQueuedToolCalls();
                this.config.onStreamEnd?.();
                break;
            }

            // Error during streaming
            case "chat.stream.error.v1": {
                console.error(`[chat] Stream error: ${payload?.error}`);
                this.config.onError?.(payload?.error || "Unknown stream error");
                this.config.onStreamEnd?.();
                break;
            }

            // Stream ended
            case "chat.stream.ended.v1": {
                console.log(`[chat] Stream ended`);
                break;
            }

            // Tool execution frames
            case "tool.command.v1": {
                this.config.onToolCommand?.(env);
                break;
            }

            case "tool.effect.v1": {
                this.config.onToolEffect?.(env);
                break;
            }

            // Batch tool completion
            case "tool.batch.done.v1": {
                console.log(`[chat] Tool batch done: ${env.payload?.count} tools executed`);
                break;
            }

            // Backward compatibility: legacy message types
            case "chat.stream_event": {
                this._handleStreamEvent(payload);
                break;
            }

            case "chat.response": {
                console.log(`[chat] Chat response received: ${traceId}`);
                this.config.onStreamEnd?.();
                break;
            }

            case "chat.error": {
                console.error(`[chat] Error: ${payload.error}`);
                this.config.onError?.(payload.error);
                this.config.onStreamEnd?.();
                break;
            }

            default:
                console.warn(`[chat] Unknown message type: ${type}`);
        }
    }

    /**
     * Queue of tool calls to execute after stream completes
     */
    private toolCallQueue: ToolCall[] = [];

    /**
     * Queue a tool call for execution
     */
    private _queueToolCall(tool: ToolCall): void {
        console.log(`[chat] Queueing tool call: ${tool.name}`);
        this.toolCallQueue.push(tool);
    }

    /**
     * Execute all queued tool calls
     */
    private async _executeQueuedToolCalls(): Promise<void> {
        if (this.toolCallQueue.length === 0) return;

        console.log(`[chat] Executing ${this.toolCallQueue.length} queued tool calls`);
        // Notify UI of tools that will be executed
        this.config.onToolsQueued?.(this.toolCallQueue);

        for (const tool of this.toolCallQueue) {
            await this._executeToolCall(tool);
        }
        this.toolCallQueue = [];
    }

    /**
     * Handle a single stream event (legacy: from chat.stream_event payload)
     */
    private _handleStreamEvent(event: any): void {
        // event should have a "type" field indicating the event type
        const eventType = event.type;

        switch (eventType) {
            case "text_chunk": {
                const chunk: string = event.chunk || event.text || "";
                this.config.onMessage?.(chunk);
                break;
            }

            case "tool_call": {
                const call = event.call || event;
                const tool: ToolCall = {
                    name: call.name,
                    args: call.args || {},
                    timeout: call.timeout || 30000,
                    critical: call.critical || false,
                };
                this._executeToolCall(tool);
                break;
            }

            case "citation": {
                const cit = event.citation || event;
                this.config.onCitation?.(cit.url, cit.title, cit.snippet);
                break;
            }

            case "memory_write": {
                const mem = event.write || event;
                this.config.onMemoryWrite?.(mem.key, mem.value);
                break;
            }

            case "done": {
                console.debug(`[chat] Stream done: ${event.stop_reason}`);
                this.config.onStreamEnd?.();
                break;
            }

            default:
                console.debug(`[chat] Unknown stream event type: ${eventType}`);
        }
    }

    /**
     * Execute a tool call (UI-local tools)
     */
    private async _executeToolCall(tool: ToolCall): Promise<void> {
        console.log(`[chat] Executing tool: ${tool.name}`, tool.args);

        const startTime = Date.now();
        let result: ToolResult;

        try {
            switch (tool.name) {
                case "record_screen": {
                    result = await this._recordScreen(tool.args);
                    break;
                }

                case "record_audio": {
                    result = await this._recordAudio(tool.args);
                    break;
                }

                case "chart_render": {
                    result = await this._renderChart(tool.args);
                    break;
                }

                default: {
                    throw new Error(`Unknown tool: ${tool.name}`);
                }
            }
        } catch (err) {
            result = {
                name: tool.name,
                ok: false,
                data: null,
                error: String(err),
                durationMs: Date.now() - startTime,
            };
        }

        // TODO: Send ToolResult back to server if tool is critical or needs feedback
        this.config.onToolCall?.(tool);
    }

    /**
     * Record screen (stub)
     */
    private async _recordScreen(args: Record<string, any>): Promise<ToolResult> {
        const duration = args.duration || 10;
        console.log(`[tools] Recording screen for ${duration}s`);

        // TODO: Implement actual screen recording (MediaRecorder, etc.)
        return {
            name: "record_screen",
            ok: true,
            data: {
                url: "blob:recording",
                duration,
                format: "webm",
            },
            durationMs: duration * 1000,
        };
    }

    /**
     * Record audio (stub)
     */
    private async _recordAudio(args: Record<string, any>): Promise<ToolResult> {
        const duration = args.duration || 5;
        console.log(`[tools] Recording audio for ${duration}s`);

        // TODO: Implement actual audio recording (MediaRecorder + AudioContext)
        return {
            name: "record_audio",
            ok: true,
            data: {
                url: "blob:audio",
                duration,
                format: "mp3",
            },
            durationMs: duration * 1000,
        };
    }

    /**
     * Render chart (stub)
     */
    private async _renderChart(args: Record<string, any>): Promise<ToolResult> {
        const dataset = args.dataset || [];
        console.log(`[tools] Rendering chart with ${dataset.length} points`);

        // TODO: Implement actual chart rendering (D3, chart.js, etc.)
        return {
            name: "chart_render",
            ok: true,
            data: {
                url: "blob:chart.svg",
                pointCount: dataset.length,
                type: args.type || "line",
            },
            durationMs: 500,
        };
    }
}

/**
 * Chat Component - React UI for agentic chat
 *
 * Displays:
 * - Chat message history
 * - Input field
 * - Streaming responses
 * - Citations + memory writes
 * - Tool results
 */

import type { ToolCall } from "@world-engine/protocol";
import React, { useEffect, useRef, useState } from "react";
import { displayToolEffect, handleToolCommand, type AnyEnv } from "../tools/toolHandler";
import { ChatClient } from "./ChatClient";
import "./ChatUI.css";

export interface Message {
  id: string;
  role: "user" | "assistant";
  text: string;
  timestamp: number;
  citations?: Array<{ url: string; title: string; snippet?: string }>;
  toolCalls?: ToolCall[];
}

export interface ChatUIProps {
  userId: string;
  convoId: string;
  wsUrl?: string;
  onError?: (error: string) => void;
}

export const ChatUI: React.FC<ChatUIProps> = ({ userId, convoId, wsUrl, onError }) => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState("");
  const [isStreaming, setIsStreaming] = useState(false);
  const [currentResponse, setCurrentResponse] = useState("");
  const [currentToolCalls, setCurrentToolCalls] = useState<ToolCall[]>([]);
  const [citations, setCitations] = useState<
    Array<{ url: string; title: string; snippet?: string }>
  >([]);
  const [memory, setMemory] = useState<Record<string, string>>({});

  const clientRef = useRef<ChatClient | null>(null);
  const messageEndRef = useRef<HTMLDivElement>(null);

  // Initialize chat client
  useEffect(() => {
    const client = new ChatClient({
      userId,
      convoId,
      wsUrl,
      onMessage: (text) => setCurrentResponse((prev) => prev + text),
      onCitation: (url, title, snippet) => {
        setCitations((prev) => [...prev, { url, title, snippet }]);
      },
      onMemoryWrite: (key, value) => {
        setMemory((prev) => ({ ...prev, [key]: value }));
      },
      onToolsQueued: (tools) => {
        setCurrentToolCalls(tools);
      },
      onToolCommand: async (env: AnyEnv) => {
        // Handle tool.command.v1 from Nucleus
        console.log("[ChatUI] Received tool.command.v1:", env.payload?.name);
        const send = (effectEnv: AnyEnv) => {
          client.sendToolEffect(
            effectEnv.traceId || env.traceId || "tr-unknown",
            effectEnv.payload?.toolCallId || "tc-unknown",
            effectEnv.payload?.name || "unknown",
            effectEnv.payload?.status || "error",
            effectEnv.payload?.result || effectEnv.payload?.error || {},
          );
        };
        await handleToolCommand(env, send);
      },
      onToolEffect: (env: AnyEnv) => {
        // Display tool.effect.v1 results (e.g., from query_lexicon)
        console.log("[ChatUI] Received tool.effect.v1:", env.payload?.name);
        displayToolEffect(env);
      },
      onToolCall: async (tool) => {
        console.log("Tool call:", tool);
      },
      onError: (err) => {
        console.error("Chat error:", err);
        onError?.(err);
      },
      onStreamStart: () => {
        setIsStreaming(true);
        setCurrentResponse("");
        setCurrentToolCalls([]);
        setCitations([]);
      },
      onStreamEnd: () => {
        setIsStreaming(false);
        // Add assistant message to history
        if (currentResponse) {
          setMessages((prev) => [
            ...prev,
            {
              id: `msg-${Date.now()}`,
              role: "assistant",
              text: currentResponse,
              timestamp: Date.now(),
              citations,
              toolCalls: currentToolCalls.length > 0 ? currentToolCalls : undefined,
            },
          ]);
        }
      },
    });

    clientRef.current = client;

    // Connect on mount
    client.connect().catch((err) => {
      const errorMsg = err instanceof Error ? err.message : String(err);
      console.error("[ChatUI] Failed to connect to chat:", errorMsg);
      onError?.(`Connection failed: ${errorMsg}`);
    });

    return () => {
      client.disconnect();
    };
  }, [userId, convoId, wsUrl, onError]);

  // Auto-scroll to bottom
  useEffect(() => {
    messageEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, currentResponse]);

  const handleSendMessage = async () => {
    if (!inputText.trim() || !clientRef.current) return;

    // Add user message to history
    const userMsg: Message = {
      id: `msg-${Date.now()}`,
      role: "user",
      text: inputText,
      timestamp: Date.now(),
    };

    setMessages((prev) => [...prev, userMsg]);
    setInputText("");

    try {
      await clientRef.current.sendMessage(inputText, {
        mapId: "default",
        playerPos: [0, 0, 0],
        visibleEntities: [],
      });
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : String(err);
      onError?.(`Failed to send message: ${errorMsg}`);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  return (
    <div className="chat-ui">
      <div className="chat-header">
        <h2>Brain Chat</h2>
        <p className="chat-info">
          User: {userId} | Conversation: {convoId}
        </p>
      </div>

      <div className="chat-messages">
        {messages.map((msg) => (
          <div key={msg.id} className={`message message-${msg.role}`}>
            <div className="message-text">{msg.text}</div>
            {msg.citations && msg.citations.length > 0 && (
              <div className="citations">
                {msg.citations.map((cit, idx) => (
                  <a key={idx} href={cit.url} className="citation-chip" title={cit.snippet}>
                    {cit.title}
                  </a>
                ))}
              </div>
            )}
            {msg.toolCalls && msg.toolCalls.length > 0 && (
              <div className="tool-calls">
                <div className="tool-calls-header">Tools:</div>
                {msg.toolCalls.map((tool, idx) => (
                  <div key={idx} className="tool-call">
                    <span className="tool-name">{tool.name}</span>
                    {Object.keys(tool.args || {}).length > 0 && (
                      <span className="tool-args">{JSON.stringify(tool.args)}</span>
                    )}
                  </div>
                ))}
              </div>
            )}
            <div className="message-time">{new Date(msg.timestamp).toLocaleTimeString()}</div>
          </div>
        ))}

        {isStreaming && (
          <div className="message message-assistant streaming">
            <div className="message-text">{currentResponse}</div>
            {citations.length > 0 && (
              <div className="citations">
                {citations.map((cit, idx) => (
                  <a key={idx} href={cit.url} className="citation-chip" title={cit.snippet}>
                    {cit.title}
                  </a>
                ))}
              </div>
            )}
            {currentToolCalls.length > 0 && (
              <div className="tool-calls">
                <div className="tool-calls-header">Tools queued:</div>
                {currentToolCalls.map((tool, idx) => (
                  <div key={idx} className="tool-call">
                    <span className="tool-name">{tool.name}</span>
                    {Object.keys(tool.args || {}).length > 0 && (
                      <span className="tool-args">{JSON.stringify(tool.args)}</span>
                    )}
                  </div>
                ))}
              </div>
            )}
            <div className="typing-indicator">
              <span></span>
              <span></span>
              <span></span>
            </div>
          </div>
        )}

        <div ref={messageEndRef} />
      </div>

      <div className="chat-input-area">
        <textarea
          value={inputText}
          onChange={(e) => setInputText(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder="Type a message... (Shift+Enter for new line)"
          disabled={isStreaming}
          className="chat-input"
        />
        <button
          onClick={handleSendMessage}
          disabled={isStreaming || !inputText.trim()}
          className="chat-send-btn"
        >
          {isStreaming ? "Waiting..." : "Send"}
        </button>
      </div>

      {Object.keys(memory).length > 0 && (
        <div className="chat-memory">
          <details>
            <summary>Memory ({Object.keys(memory).length} items)</summary>
            <ul>
              {Object.entries(memory).map(([key, value]) => (
                <li key={key}>
                  <strong>{key}:</strong> {value}
                </li>
              ))}
            </ul>
          </details>
        </div>
      )}
    </div>
  );
};

/**
 * Operator Results Panel
 *
 * IDE component for displaying operator execution results.
 * Subscribes to operator.executed events from WS bus.
 *
 * Features:
 * - Live execution status
 * - Result display (diffs, deltas, errors)
 * - Memory writes visualization
 * - Deterministic hash verification
 * - Execution timing
 */

import React, { useEffect, useState } from "react";

interface OperatorResult {
  operator_id: string;
  operator_name: string;
  trace_id: string;
  status: "success" | "validation_error" | "timeout" | "execution_error";
  result: Record<string, any>;
  error?: Record<string, any>;
  memory_writes?: Array<{ key: string; value: string; ttl_seconds?: number }>;
  execution_time_ms: number;
  deterministic_hash?: string;
  timestamp: number;
}

interface Props {
  autoRefresh?: boolean;
  refreshInterval?: number;
}

export const OperatorResultsPanel: React.FC<Props> = ({
  autoRefresh = true,
  refreshInterval = 2000,
}) => {
  const [results, setResults] = useState<OperatorResult[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [expanding, setExpanding] = useState<Set<string>>(new Set());
  const [isLoading, setIsLoading] = useState(false);

  // Fetch operator events from API
  useEffect(() => {
    if (!autoRefresh) return;

    const fetchEvents = async () => {
      try {
        setIsLoading(true);
        const resp = await fetch("http://localhost:3000/operator/events");
        if (!resp.ok) throw new Error(`HTTP ${resp.status}`);

        const data = await resp.json();
        setResults(
          (data.events || []).map((ev: any) => ({
            operator_id: ev.operator_id,
            operator_name: ev.operator_name,
            trace_id: ev.trace_id,
            status: ev.status,
            result: ev.result || {},
            error: ev.error,
            memory_writes: ev.memory_writes || [],
            execution_time_ms: ev.execution_time_ms || 0,
            deterministic_hash: ev.deterministic_hash,
            timestamp: new Date(ev.created_at).getTime() || Date.now(),
          })),
        );
      } catch (err) {
        console.error("[OperatorResultsPanel] Failed to fetch:", err);
      } finally {
        setIsLoading(false);
      }
    };

    fetchEvents();
    const interval = setInterval(fetchEvents, refreshInterval);
    return () => clearInterval(interval);
  }, [autoRefresh, refreshInterval]);

  const selectedResult = results.find((r) => r.operator_id === selectedId);

  const toggleExpand = (id: string) => {
    setExpanding((prev) => {
      const next = new Set(prev);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  };

  const statusColor = (status: string) => {
    switch (status) {
      case "success":
        return "#10b981"; // emerald
      case "validation_error":
        return "#f59e0b"; // amber
      case "timeout":
        return "#f59e0b"; // amber
      case "execution_error":
        return "#e11d48"; // rose
      default:
        return "#8b5cf6";
    }
  };

  const statusIcon = (status: string) => {
    switch (status) {
      case "success":
        return "Γ£à";
      case "validation_error":
        return "ΓÜá∩╕Å";
      case "timeout":
        return "ΓÅ▒∩╕Å";
      case "execution_error":
        return "Γ¥î";
      default:
        return "Γ¥ô";
    }
  };

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        height: "100%",
        backgroundColor: "#0b0f14",
        color: "#e8eef6",
        fontFamily: "monospace",
        borderLeft: "1px solid #223049",
        overflow: "hidden",
      }}
    >
      {/* Header */}
      <div
        style={{
          padding: "12px",
          borderBottom: "1px solid #223049",
          fontSize: "12px",
          fontWeight: "bold",
        }}
      >
        ≡ƒºá Operator Results ({results.length})
      </div>

      {/* List pane */}
      <div
        style={{
          flex: 1,
          overflowY: "auto",
          borderRight: selectedId ? "1px solid #223049" : "none",
        }}
      >
        {results.length === 0 ? (
          <div style={{ padding: "16px", color: "#9fb0c7", fontSize: "12px" }}>
            No operator executions yet...
          </div>
        ) : (
          results.map((result) => (
            <div
              key={result.operator_id}
              onClick={() => setSelectedId(result.operator_id)}
              style={{
                padding: "10px 12px",
                borderBottom: "1px solid rgba(255,255,255,.05)",
                backgroundColor:
                  selectedId === result.operator_id ? "rgba(139,92,246,.1)" : "transparent",
                cursor: "pointer",
                transition: "background-color 0.2s",
              }}
              onMouseEnter={(e) => {
                if (selectedId !== result.operator_id) {
                  (e.currentTarget as HTMLDivElement).style.backgroundColor =
                    "rgba(139,92,246,.05)";
                }
              }}
              onMouseLeave={(e) => {
                if (selectedId !== result.operator_id) {
                  (e.currentTarget as HTMLDivElement).style.backgroundColor = "transparent";
                }
              }}
            >
              <div style={{ fontSize: "11px", color: "#9fb0c7" }}>
                {statusIcon(result.status)} {result.status}
              </div>
              <div style={{ fontSize: "12px", fontWeight: "bold", marginTop: "4px" }}>
                {result.operator_name}
              </div>
              <div style={{ fontSize: "10px", color: "#9fb0c7", marginTop: "4px" }}>
                {result.execution_time_ms}ms ΓÇó {new Date(result.timestamp).toLocaleTimeString()}
              </div>
            </div>
          ))
        )}
      </div>

      {/* Detail pane */}
      {selectedResult && (
        <div
          style={{
            flex: 1,
            overflowY: "auto",
            borderTop: "1px solid #223049",
            padding: "12px",
            backgroundColor: "#0f1420",
            fontSize: "11px",
          }}
        >
          {/* Header */}
          <div style={{ marginBottom: "12px" }}>
            <div style={{ fontWeight: "bold", marginBottom: "6px" }}>
              {statusIcon(selectedResult.status)} {selectedResult.operator_name}
            </div>
            <div style={{ color: "#9fb0c7", fontSize: "10px" }}>
              ID: {selectedResult.operator_id.slice(0, 16)}...
            </div>
            <div style={{ color: "#9fb0c7", fontSize: "10px" }}>
              Time: {selectedResult.execution_time_ms}ms
            </div>
          </div>

          {/* Error */}
          {selectedResult.error && (
            <div
              style={{
                marginBottom: "12px",
                padding: "8px",
                backgroundColor: "rgba(225,29,72,.1)",
                borderRadius: "4px",
                border: "1px solid #e11d48",
              }}
            >
              <div style={{ color: "#e11d48", fontWeight: "bold", marginBottom: "4px" }}>
                Γ¥î {selectedResult.error.code}
              </div>
              <div style={{ color: "#9fb0c7", fontSize: "10px" }}>
                {selectedResult.error.message}
              </div>
            </div>
          )}

          {/* Result */}
          {selectedResult.result && Object.keys(selectedResult.result).length > 0 && (
            <div style={{ marginBottom: "12px" }}>
              <div
                style={{
                  fontWeight: "bold",
                  marginBottom: "4px",
                  cursor: "pointer",
                  color: "#22d3ee",
                }}
                onClick={() => toggleExpand("result")}
              >
                {expanding.has("result") ? "Γû╝" : "Γû╢"} Result
              </div>
              {expanding.has("result") && (
                <pre
                  style={{
                    backgroundColor: "#0b0f14",
                    padding: "8px",
                    borderRadius: "4px",
                    overflow: "auto",
                    fontSize: "10px",
                    border: "1px solid rgba(255,255,255,.05)",
                    maxHeight: "150px",
                  }}
                >
                  {JSON.stringify(selectedResult.result, null, 2)}
                </pre>
              )}
            </div>
          )}

          {/* Memory Writes */}
          {selectedResult.memory_writes && selectedResult.memory_writes.length > 0 && (
            <div style={{ marginBottom: "12px" }}>
              <div
                style={{
                  fontWeight: "bold",
                  marginBottom: "4px",
                  cursor: "pointer",
                  color: "#22d3ee",
                }}
                onClick={() => toggleExpand("memory")}
              >
                {expanding.has("memory") ? "Γû╝" : "Γû╢"} Memory Writes (
                {selectedResult.memory_writes.length})
              </div>
              {expanding.has("memory") && (
                <div
                  style={{
                    backgroundColor: "#0b0f14",
                    padding: "8px",
                    borderRadius: "4px",
                    border: "1px solid rgba(255,255,255,.05)",
                    maxHeight: "150px",
                    overflowY: "auto",
                  }}
                >
                  {selectedResult.memory_writes.map((w, i) => (
                    <div key={i} style={{ marginBottom: "8px", fontSize: "10px" }}>
                      <div style={{ color: "#10b981", fontFamily: "monospace" }}>{w.key}</div>
                      {w.ttl_seconds && (
                        <div style={{ color: "#9fb0c7", fontSize: "9px" }}>
                          TTL: {w.ttl_seconds}s
                        </div>
