/**
 * Operator Trigger Component
 *
 * Allows users to execute operators from the IDE.
 * Shows inline execution status and results.
 *
 * Displays:
 * - Available operators (fetched from /brain/operator/list)
 * - Input form for operator parameters
 * - Real-time execution feedback
 * - Results inline
 */

import React, { useEffect, useState } from "react";

interface OperatorMeta {
  operator_id: string;
  operator_name: string;
  description?: string;
  schema?: Record<string, any>;
}

interface OperatorExecution {
  operator_id: string;
  status: "success" | "validation_error" | "timeout" | "execution_error";
  result?: Record<string, any>;
  error?: { code: string; message: string };
  execution_time_ms: number;
}

export const OperatorTrigger: React.FC = () => {
  const [operators, setOperators] = useState<OperatorMeta[]>([]);
  const [selected, setSelected] = useState<string | null>(null);
  const [params, setParams] = useState<string>("{}");
  const [executing, setExecuting] = useState(false);
  const [result, setResult] = useState<OperatorExecution | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Load operators on mount
  useEffect(() => {
    (async () => {
      try {
        const resp = await fetch("http://localhost:3000/brain/operator/list");
        if (!resp.ok) throw new Error(`HTTP ${resp.status}`);

        const data = await resp.json();
        setOperators(data.operators || []);
        if (data.operators?.length > 0 && !selected) {
          setSelected(data.operators[0].operator_id);
        }
      } catch (err) {
        console.error("Failed to load operators:", err);
      }
    })();
  }, []);

  const handleExecute = async () => {
    if (!selected) return;

    try {
      setError(null);
      setResult(null);
      setExecuting(true);

      // Parse params
      let parsedParams = {};
      try {
        parsedParams = JSON.parse(params);
      } catch {
        throw new Error("Invalid JSON in parameters");
      }

      // Execute operator
      const resp = await fetch("http://localhost:3000/brain/operator/execute", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          operator_id: selected,
          parameters: parsedParams,
        }),
      });

      if (!resp.ok) {
        const data = await resp.json();
        throw new Error(data.error?.message || `HTTP ${resp.status}`);
      }

      const data = await resp.json();
      setResult({
        operator_id: data.operator_id,
        status: data.status,
        result: data.result,
        error: data.error,
        execution_time_ms: data.execution_time_ms,
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
    } finally {
      setExecuting(false);
    }
  };

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "12px",
        padding: "16px",
        backgroundColor: "#0b0f14",
        color: "#e8eef6",
        fontFamily: "monospace",
        borderRadius: "6px",
      }}
    >
      {/* Title */}
      <div style={{ fontSize: "12px", fontWeight: "bold" }}>≡ƒÜÇ Execute Operator</div>

      {/* Operator Select */}
      <div style={{ display: "flex", flexDirection: "column", gap: "6px" }}>
        <label style={{ fontSize: "11px", color: "#9fb0c7" }}>Operator</label>
        <select
          value={selected || ""}
          onChange={(e) => setSelected(e.target.value)}
          disabled={executing}
          style={{
            padding: "6px",
            backgroundColor: "#0f1420",
            color: "#e8eef6",
            border: "1px solid #223049",
            borderRadius: "4px",
            fontSize: "11px",
          }}
        >
          <option value="">Select operator...</option>
          {operators.map((op) => (
            <option key={op.operator_id} value={op.operator_id}>
              {op.operator_name}
            </option>
          ))}
        </select>
      </div>

      {/* Parameters */}
      <div style={{ display: "flex", flexDirection: "column", gap: "6px" }}>
        <label style={{ fontSize: "11px", color: "#9fb0c7" }}>Parameters (JSON)</label>
        <textarea
          value={params}
          onChange={(e) => setParams(e.target.value)}
          disabled={executing}
          placeholder="{}"
          style={{
            padding: "6px",
            backgroundColor: "#0f1420",
            color: "#e8eef6",
            border: "1px solid #223049",
            borderRadius: "4px",
            fontSize: "11px",
            fontFamily: "monospace",
            minHeight: "60px",
            resize: "vertical",
          }}
        />
      </div>

      {/* Error */}
      {error && (
        <div
          style={{
            padding: "8px",
            backgroundColor: "rgba(225,29,72,.1)",
            color: "#e11d48",
            borderRadius: "4px",
            border: "1px solid #e11d48",
            fontSize: "11px",
          }}
        >
          {error}
        </div>
      )}

      {/* Execute Button */}
      <button
        onClick={handleExecute}
        disabled={executing || !selected}
        style={{
          padding: "8px",
          backgroundColor: executing ? "#4b5563" : "#8b5cf6",
          color: "#fff",
          border: "none",
          borderRadius: "4px",
          fontSize: "11px",
          fontWeight: "bold",
          cursor: executing || !selected ? "default" : "pointer",
          opacity: executing || !selected ? 0.6 : 1,
          transition: "opacity 0.2s",
        }}
      >
        {executing ? "ΓÅ│ Executing..." : "Execute"}
      </button>

      {/* Result */}
      {result && (
        <div
          style={{
            padding: "8px",
            backgroundColor: "rgba(34,211,238,.05)",
            border: "1px solid #22d3ee",
            borderRadius: "4px",
            fontSize: "11px",
          }}
        >
          <div style={{ color: "#22d3ee", fontWeight: "bold", marginBottom: "4px" }}>
            {result.status === "success" ? "Γ£à" : "Γ¥î"} Result ({result.execution_time_ms}ms)
          </div>
          <pre
            style={{
              margin: 0,
              overflow: "auto",
              maxHeight: "120px",
              fontSize: "10px",
              color: "#9fb0c7",
            }}
          >
            {JSON.stringify(result.result || result.error || result, null, 2)}
          </pre>
        </div>
      )}
    </div>
  );
};

