/**
 * Adapters to integrate health poller with wsHub's existing structures
 */

/** Adapter that wraps wsHub client/WS infrastructure to appear as HubPresence */
export function createHubPresenceAdapter(clientsSet: Set<any>): HubPresence {
    return {
        isRoleConnected(role: "ide" | "preview" | "brain" | "sidecar"): boolean {
            for (const client of clientsSet) {
                if (client.role === role) return true;
            }
            return false;
        },

        roleCount(role: "ide" | "preview" | "brain" | "sidecar"): number {
            let count = 0;
            for (const client of clientsSet) {
                if (client.role === role) count++;
            }
            return count;
        }
    };
}

/**
 * Adapter wrapping wsHub's broadcastTo function as a BusLike.
 *
 * Note: This publishes to "ide" role so the IDE receives health updates.
 * The actual bus envelope shape follows @world-engine/protocol conventions.
 */
export function createBusLikeAdapter(broadcastToFn: (role: Role | "ide", env: any) => void): BusLike {
    return {
        publish(env: {
            channel: string;
            type: string;
            payload: unknown;
            sessionId: string;
            traceId?: string;
        }): void {
            // Construct a full envelope compatible with BusEnvelope<T, U>
            const fullEnv = {
                v: 2,
                id: `health.${Math.random().toString(36).slice(2, 11)}`,
                type: "system.health",
                ts: Date.now(),
                from: { role: "nucleus", instanceId: "nucleus_1" },
                sessionId: env.sessionId,
                traceId: env.traceId,
                payload: env.payload
            };

            // Broadcast to IDE clients
            broadcastToFn("ide" as const, fullEnv);
        }
    };
}

import {
    HealthState,
    ServiceHealth,
    SYSTEM_CHANNEL,
    SYSTEM_HEALTH_EVENT_TYPE,
    SystemHealthSnapshot
} from "@world-engine/protocol";
import { randomUUID } from "node:crypto";

/**
 * Minimal bus interface expected by this module.
 * Adapt to your actual bus implementation.
 */
export interface BusLike {
    publish: (env: {
        channel: string;
        type: string;
        payload: unknown;
        sessionId: string;
        traceId?: string;
    }) => void;
}

/**
 * Minimal hub presence interface.
 * Your WS hub should already know which roles are connected.
 */
export interface HubPresence {
    /** true if at least 1 client connected for this role */
    isRoleConnected(role: "ide" | "preview" | "brain" | "sidecar"): boolean;

    /** optional count; used for UI or diagnostics */
    roleCount?(role: "ide" | "preview" | "brain" | "sidecar"): number;
}

export type HealthPollerConfig = {
    bus: BusLike;
    hubPresence: HubPresence;

    /** session that this nucleus instance is serving */
    sessionId: string;

    /** sidecar base URL; default matches your launcher */
    sidecarBaseUrl?: string;

    /** poll interval; default 1000ms */
    intervalMs?: number;

    /** nucleus version label (optional) */
    nucleusVersion?: string | undefined;
};

function nowIso(): string {
    return new Date().toISOString();
}

function computeSummary(services: ServiceHealth[]): HealthState {
    if (services.some((s) => s.state === "down")) return "down";
    if (services.some((s) => s.state === "degraded")) return "degraded";
    if (services.every((s) => s.state === "up")) return "up";
    return "unknown";
}

async function checkSidecarHealth(target: string): Promise<ServiceHealth> {
    const started = Date.now();
    try {
        // Node 18+ has global fetch. If you're older, add undici.
        const res = await fetch(target, { method: "GET" });
        const latencyMs = Date.now() - started;

        if (!res.ok) {
            return {
                service: "sidecar",
                state: "down",
                reason: `HTTP ${res.status}`,
                target,
                latencyMs
            };
        }

        const json = (await res.json()) as any;

        // Accept flexible sidecar health shape, but enforce signal:
        // - must indicate ok/up and may include version.
        const ok =
            json?.ok === true ||
            json?.status === "ok" ||
            json?.state === "up" ||
            json?.up === true;

        if (!ok) {
            return {
                service: "sidecar",
                state: "degraded",
                reason: "Sidecar responded but did not report healthy",
                target,
                latencyMs,
                version: typeof json?.version === "string" ? json.version : undefined
            };
        }

        return {
            service: "sidecar",
            state: "up",
            target,
            latencyMs,
            version: typeof json?.version === "string" ? json.version : undefined
        };
    } catch (err: any) {
        const latencyMs = Date.now() - started;
        return {
            service: "sidecar",
            state: "down",
            reason: String(err?.message ?? err),
            target,
            latencyMs
        };
    }
}

function checkPreviewPresence(hub: HubPresence): ServiceHealth {
    const connected = hub.isRoleConnected("preview");
    const count = hub.roleCount?.("preview");
    return {
        service: "preview",
        state: connected ? "up" : "down",
        reason: connected ? (typeof count === "number" ? `connected(${count})` : "connected") : "not connected",
        target: "ws://localhost:3000"
    };
}

function checkIdePresence(hub: HubPresence): ServiceHealth {
    const connected = hub.isRoleConnected("ide");
    const count = hub.roleCount?.("ide");
    return {
        service: "ide",
        state: connected ? "up" : "down",
        reason: connected ? (typeof count === "number" ? `connected(${count})` : "connected") : "not connected",
        target: "ws://localhost:3000"
    };
}

function nucleusSelfHealth(version?: string): ServiceHealth {
    return {
        service: "nucleus",
        state: "up",
        reason: "running",
        target: "ws://localhost:3000",
        version
    };
}

export function startHealthPoller(cfg: HealthPollerConfig): { stop: () => void } {
    const intervalMs = cfg.intervalMs ?? 1000;
    const sidecarUrl = (cfg.sidecarBaseUrl ?? "http://127.0.0.1:8001").replace(/\/+$/, "");
    const sidecarHealthUrl = `${sidecarUrl}/health`;

    let seq = 0;
    let timer: NodeJS.Timeout | null = null;
    let stopped = false;

    const tick = async () => {
        if (stopped) return;

        // Deterministic ordering of checks
        const services: ServiceHealth[] = [];
        services.push(nucleusSelfHealth(cfg.nucleusVersion));
        services.push(checkIdePresence(cfg.hubPresence));
        services.push(checkPreviewPresence(cfg.hubPresence));
        services.push(await checkSidecarHealth(sidecarHealthUrl));

        const snapshot: SystemHealthSnapshot = {
            schema: { name: "system.health.snapshot", version: "1.0.0" },
            id: `health.${randomUUID()}`,
            ts: nowIso(),
            sessionId: cfg.sessionId,
            seq: seq++,
            services,
            summary: computeSummary(services)
        };

        cfg.bus.publish({
            channel: SYSTEM_CHANNEL,
            type: SYSTEM_HEALTH_EVENT_TYPE,
            payload: snapshot,
            sessionId: cfg.sessionId,
            traceId: `trace.health.${snapshot.seq}`
        });
    };

    // fire immediately then interval
    void tick();
    timer = setInterval(() => void tick(), intervalMs);

    return {
        stop: () => {
            stopped = true;
            if (timer) clearInterval(timer);
            timer = null;
        }
    };
}

/**
 * apps/nucleus/src/idle.ts
 *
 * TypeScript IdleAutonomyGuard ΓÇö mirrors Python version
 * Reads idle state from JSON, applies commanded state changes
 *
 * Design:
 * - Read IdleGuardState from notes/idle_state.json (synced with Python)
 * - Apply incoming idle.effect.v1 from Python to update local model
 * - Serve GET /idle/state endpoint for IDE to poll
 * - Route idle.command.v1 to Python via notes/events.jsonl
 */
import { IdleEffectV1PayloadSchema, IdleGuardStateSchema, } from "@world-engine/protocol";
import * as fs from "node:fs";
import * as path from "node:path";
export class IdleAutonomyGuard {
    mode;
    notesDir;
    stateFile;
    state;
    approval_ttl_seconds = 3600;
    constructor(mode = "dream_idle", notesDir = "notes") {
        this.mode = mode;
        this.notesDir = notesDir;
        this.stateFile = path.join(notesDir, `idle_state_${mode}.json`);
        // Ensure notes dir exists
        if (!fs.existsSync(notesDir)) {
            fs.mkdirSync(notesDir, { recursive: true });
        }
        // Load state or initialize
        this.state = this._loadState();
    }
    _loadState() {
        if (fs.existsSync(this.stateFile)) {
            try {
                const data = JSON.parse(fs.readFileSync(this.stateFile, "utf-8"));
                return IdleGuardStateSchema.parse(data);
            }
            catch {
                // Invalid state file, reset
            }
        }
        // Default state
        return {
            mode: this.mode,
            prompted: false,
            prompt_text: "",
            approved: false,
            approval_token: "",
            approval_expires_ts: 0,
            last_activation_ts: 0,
            last_block_reason: "never_checked",
        };
    }
    _saveState() {
        fs.writeFileSync(this.stateFile, JSON.stringify(this.state, null, 2), "utf-8");
    }
    /**
     * Can the idle mode activate?
     * Returns [ok, reason]
     */
    canActivate() {
        const now = Date.now() / 1000;
        if (!this.state.prompted) {
            this.state.last_block_reason = "blocked:not_prompted";
            this._saveState();
            return [false, this.state.last_block_reason];
        }
        if (!this.state.approved) {
            this.state.last_block_reason = "blocked:not_approved";
            this._saveState();
            return [false, this.state.last_block_reason];
        }
        if (now > this.state.approval_expires_ts) {
            this.state.last_block_reason = "blocked:approval_expired";
            this.state.approved = false;
            this.state.approval_token = "";
            this._saveState();
            return [false, this.state.last_block_reason];
        }
        return [true, "ok"];
    }
    /**
     * Mark that idle mode started running
     */
    markActivated() {
        const now = Date.now() / 1000;
        this.state.last_activation_ts = now;
        this._saveState();
    }
    /**
     * Approve idle mode (internal, called by applyEffect)
     */
    approve(phrase) {
        const now = Date.now() / 1000;
        this.state.approved = true;
        this.state.approval_token = this._makeToken(phrase);
        this.state.approval_expires_ts = now + this.approval_ttl_seconds;
        this._saveState();
    }
    /**
     * Revoke approval
     */
    revoke(_reason) {
        this.state.approved = false;
        this.state.approval_token = "";
        this.state.approval_expires_ts = 0;
        this._saveState();
    }
    _makeToken(phrase) {
        const ts = Date.now();
        const rand = Math.random().toString(36).slice(2, 8);
        return `${phrase}_${ts}_${rand}`;
    }
    /**
     * Apply idle.effect.v1 from Python guard
     * This updates local state based on effects
     */
    applyEffect(payload) {
        const parsed = IdleEffectV1PayloadSchema.safeParse(payload);
        if (!parsed.success) {
            return;
        }
        const effect = parsed.data;
        if (effect.mode !== this.mode) {
            return;
        }
        // Apply state changes based on effect status
        if (effect.status === "prompted") {
            this.state.prompted = true;
            this.state.prompt_text = effect.prompt_text ?? "";
        }
        else if (effect.status === "approved") {
            this.approve(effect.approval_token ?? "approve");
        }
        else if (effect.status === "revoked") {
            this.revoke(effect.reason);
        }
        else if (effect.status === "blocked") {
            this.state.last_block_reason = effect.reason ?? "unknown";
        }
        else if (effect.status === "activated") {
            this.markActivated();
        }
        this._saveState();
    }
    /**
     * Get current state (for GET /idle/state endpoint)
     */
    getState() {
        return { ...this.state };
    }
    /**
     * Get approval TTL for HTTP response
     */
    getApprovalTtl() {
        return this.approval_ttl_seconds;
    }
    /**
     * Set approval TTL
     */
    setApprovalTtl(seconds) {
        this.approval_ttl_seconds = Math.max(60, seconds);
    }
}
/**
 * IdleStateManager ΓÇö manage multiple idle modes
 */
export class IdleStateManager {
    guards = new Map();
    notesDir;
    constructor(notesDir = "notes") {
        this.notesDir = notesDir;
    }
    /**
     * Get or create guard for mode
     */
    getGuard(mode) {
        if (!this.guards.has(mode)) {
            this.guards.set(mode, new IdleAutonomyGuard(mode, this.notesDir));
        }
        return this.guards.get(mode);
    }
    /**
     * Get state for mode (or throw)
     */
    getState(mode) {
        return this.getGuard(mode).getState();
    }
    /**
     * Apply effect to mode
     */
    applyEffect(mode, payload) {
        this.getGuard(mode).applyEffect(payload);
    }
    /**
     * Check if mode can activate
     */
    canActivate(mode) {
        return this.getGuard(mode).canActivate();
    }
    /**
     * Mark mode activated
     */
    markActivated(mode) {
        this.getGuard(mode).markActivated();
    }
}

/**
 * Nucleus WS Hub & Router
 *
 * CRITICAL: Two separate WS endpoints exist:
 *
 * 1. ws://localhost:3000 (THE HUB - IDE ONLY)
 *    Γö£ΓöÇ Purpose: Hub for IDE orchestration + session mgmt
 *    Γö£ΓöÇ Auth: Implicit (IDE is trusted local client)
 *    Γö£ΓöÇ Use case: IDE connects here (apps/ide-web/src/main.tsx)
 *    ΓööΓöÇ Security: Rate limiting, nonce validation, role gating
 *
 * 2. ws://localhost:3000/ws/bus (tool/service bus - NOT FOR IDE)
 *    Γö£ΓöÇ Purpose: Raw bus for direct tools/services
 *    Γö£ΓöÇ Auth: Required (token-based)
 *    Γö£ΓöÇ Use case: Sidecar, tools, operator services
 *    ΓööΓöÇ Security: Same gating as hub, but explicit routing
 *
 * ΓÜá∩╕Å  DEVELOPER NOTE:
 *    DO NOT wire IDE to /ws/bus. It bypasses intended architecture.
 *    IDE MUST use ws://localhost:3000 (hub endpoint).
 *    This is not a preference; it's a security boundary.
 *
 */

import http from "node:http";
import { WebSocketServer } from "ws";
import { handleHealthCheck } from "./routes/health";
import { handleBusReplayRequest } from "./routes/busReplay";
import { handleOperatorEvent } from "./routes/operatorEvent";
import { setupBusHttpUpgradeHandler } from "./routes/wsBus";
import { handlePipelineResultsIndex, handlePipelineResultsFile } from "./routes/http/pipelineResults";
import { handleFlowstateAnalyze } from "./routes/http/flowstate";
import { createHub } from "./wsHub";

const PORT = Number(process.env.NUCLEUS_PORT ?? "3000");

const server = http.createServer((req: any, res: any) => {
  // Health check first (used by launcher for readiness gating)
  if (handleHealthCheck(req, res)) return;

  // Pipeline results API (for IDE viewer)
  if (handlePipelineResultsIndex(req, res)) return;
  if (handlePipelineResultsFile(req, res)) return;

  // FlowState analysis endpoint
  if (handleFlowstateAnalyze(req, res)) return;

  // Try operator event routes
  if (handleOperatorEvent(req, res)) return;

  // Try bus replay routes
  if (handleBusReplayRequest(req, res)) return;

  res.writeHead(200, { "content-type": "text/plain" });
  res.end("world-engine nucleus ok\n");
});

const wss = new WebSocketServer({ server });
createHub(wss);

// Register /ws/bus upgrade handler
setupBusHttpUpgradeHandler(wss, (pathname: string, handler: (req: any, socket: any, head: any) => void) => {
  server.on("upgrade", (req: any, socket: any, head: any) => {
    if (req.url?.startsWith(pathname)) {
      handler(req, socket, head);
    }
  });
});

server.listen(PORT, () => {
  console.log(`[nucleus] listening http/ws on :${PORT} (+ /ws/bus + /bus/*)`);
  console.log(`[nucleus] IDE MUST use ws://localhost:${PORT} (hub), NOT /ws/bus`);
});

import { randomId } from "@world-engine/protocol";
import * as pty from "node-pty";
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import type { PtySession } from "./ptySession";

type OpenOpts = {
    cols: number;
    rows: number;
    onData: (ptyId: string, data: string) => void;
};

export class VenoManager {
    private readonly sessions = new Map<string, PtySession>();
    private readonly sessionIndex = new Map<string, Set<string>>();

    async openVeno(sessionId: string, opts: OpenOpts): Promise<string> {
        const venoRoot = this.ensureVenoInstalled();
        const venoScript = path.join(venoRoot, "veno.sh");

        const ptyId = randomId("pty");
        const shell = process.platform === "win32" ? "powershell.exe" : "bash";

        const p = pty.spawn(shell, [], {
            name: "xterm-256color",
            cols: opts.cols,
            rows: opts.rows,
            cwd: venoRoot,
            env: {
                ...process.env,
                TERM: "xterm-256color"
            }
        });

        const sess: PtySession = { ptyId, sessionId, pty: p };
        this.sessions.set(ptyId, sess);
        if (!this.sessionIndex.has(sessionId)) this.sessionIndex.set(sessionId, new Set());
        this.sessionIndex.get(sessionId)!.add(ptyId);

        p.onData((data: string) => opts.onData(ptyId, data));

        // Launch veno
        if (process.platform === "win32") {
            // Windows: run via bash if available (Git Bash / WSL). If not, user must provide a bash env.
            p.write(`bash "${venoScript}"\r`);
        } else {
            p.write(`chmod +x "${venoScript}"\n`);
            p.write(`"${venoScript}"\n`);
        }

        return ptyId;
    }

    write(ptyId: string, data: string): void {
        const s = this.sessions.get(ptyId);
        if (!s) return;
        s.pty.write(data);
    }

    resize(ptyId: string, cols: number, rows: number): void {
        const s = this.sessions.get(ptyId);
        if (!s) return;
        try {
            s.pty.resize(Math.max(2, cols), Math.max(2, rows));
        } catch { }
    }

    closeAllForSession(sessionId: string): void {
        const ids = this.sessionIndex.get(sessionId);
        if (!ids) return;
        for (const ptyId of ids) {
            const s = this.sessions.get(ptyId);
            if (s) {
                try {
                    s.pty.kill();
                } catch { }
                this.sessions.delete(ptyId);
            }
        }
        this.sessionIndex.delete(sessionId);
    }

    private ensureVenoInstalled(): string {
        const root = path.resolve(process.cwd(), "../../tools/veno");
        const marker = path.join(root, ".veno_ready");

        if (fs.existsSync(marker)) return root;

        if (!fs.existsSync(root)) fs.mkdirSync(root, { recursive: true });

        // If folder empty, clone
        const isEmpty = fs.readdirSync(root).length === 0;
        if (isEmpty) {
            console.log("[nucleus] cloning veno into tools/veno ...");
            const clone = spawnSync("git", ["clone", "https://github.com/TomAwezome/veno", root], {
                stdio: "inherit"
            });
            if (clone.status !== 0) {
                throw new Error("Failed to git clone veno. Ensure git is installed and network is available.");
            }
        }

        // Install python deps
        console.log("[nucleus] installing veno python requirements ...");
        const pip = process.platform === "win32" ? "py" : "python3";
        const pipArgs = ["-m", "pip", "install", "-r", "requirements.txt"];

        const pipRun = spawnSync(pip, pipArgs, { cwd: root, stdio: "inherit" });
        if (pipRun.status !== 0) {
            throw new Error(
                "Failed to install veno requirements. Ensure Python 3 + pip are installed and available."
            );
        }

        fs.writeFileSync(marker, "ok\n", "utf8");
        console.log("[nucleus] veno ready Γ£à");
        return root;
    }
}

/**
 * UEE Handler Base Template
 *
 * Extend this class to implement a specific task handler.
 * Provides common utilities: validation, logging, state management, audit tracking.
 *
 * Example:
 *   class MyLexiconOpHandler extends UEEHandlerBase {
 *     async execute(envelope, context) {
 *       const { lexicon_op } = envelope.inputs;
 *       // ... business logic
 *       return this.success({ lexicon_op: outputs }, audit, state_delta);
 *     }
 *   }
 */
import { narrowByTaskType } from "@world-engine/protocol";
import { z } from "zod";
/**
 * Format Zod validation errors for display
 */
function formatValidationErrors(errors) {
    return errors.errors
        .map((e) => `${e.path.join('.')}: ${e.message}`)
        .join('\n');
}
// ============================================================================
// Base Handler Class
// ============================================================================
export class UEEHandlerBase {
    logger;
    taskType;
    constructor(taskType, logger = console) {
        this.taskType = taskType;
        this.logger = logger;
    }
    // ========================================================================
    // Validation Helpers
    // ========================================================================
    /**
     * Assert task type matches expected (for type narrowing)
     */
    assertTaskType(envelope, expected) {
        if (envelope.task.type !== expected) {
            throw new Error(`Expected task type "${expected}", got "${envelope.task.type}"`);
        }
    }
    /**
     * Validate envelope against a Zod schema (useful for semantic validation)
     */
    validate(schema, data) {
        try {
            return schema.parse(data);
        }
        catch (err) {
            if (err instanceof z.ZodError) {
                throw new Error(`Validation failed:\n${formatValidationErrors(err)}`);
            }
            throw err;
        }
    }
    /**
     * Validate and narrow to specific task type
     */
    requireInputs(envelope, taskType) {
        if (!narrowByTaskType(envelope, taskType)) {
            throw new Error(`Task type mismatch: expected ${taskType}`);
        }
        const inputs = envelope.inputs;
        if (!inputs[taskType]) {
            throw new Error(`Missing required inputs for task type: ${taskType}`);
        }
        return inputs;
    }
    // ========================================================================
    // Logging Helpers
    // ========================================================================
    /**
     * Log task start
     */
    logStart(context, details) {
        this.logger.log(`[${this.taskType}] START task=${context.taskId} mode=${context.mode}`, details || "");
    }
    /**
     * Log task success
     */
    logSuccess(context, details) {
        this.logger.log(`[${this.taskType}] SUCCESS task=${context.taskId}`, details || "");
    }
    /**
     * Log task error
     */
    logError(context, error) {
        const message = error instanceof Error ? error.message : String(error);
        this.logger.error(`[${this.taskType}] ERROR task=${context.taskId}: ${message}`);
    }
    /**
     * Log debug info
     */
    logDebug(context, message, data) {
        if (this.logger.debug) {
            this.logger.debug(`[${this.taskType}] DEBUG task=${context.taskId}: ${message}`, data);
        }
    }
    // ========================================================================
    // Response Builders
    // ========================================================================
    /**
     * Build success response
     */
    success(context, outputs, audit, state_delta) {
        const response = {
            ok: true,
            taskId: context.taskId,
            taskType: context.taskType,
        };
        if (outputs)
            response.outputs = outputs;
        if (audit)
            response.audit = audit;
        if (state_delta)
            response.state_delta = state_delta;
        return response;
    }
    /**
     * Build error response
     */
    error(context, message, errors) {
        return {
            ok: false,
            taskId: context.taskId,
            taskType: context.taskType,
            errors: [message, ...(errors || [])],
        };
    }
    /**
     * Build error response from exception
     */
    errorFromException(context, err) {
        const message = err instanceof Error ? err.message : String(err);
        return this.error(context, `Handler execution failed: ${message}`);
    }
    // ========================================================================
    // Audit Tracking
    // ========================================================================
    /**
     * Create audit entry for speculative items
     */
    createSpeculativeItem(id, detail, hypothesized_payoff, due_by) {
        return {
            id,
            detail,
            hypothesized_payoff,
            due_by,
            created_at: new Date().toISOString(),
            speculative: true,
        };
    }
    /**
     * Create foreshadow ledger entry
     */
    createForeshadowEntry(id, detail, payoff_hypothesis, due_by) {
        return {
            id,
            detail,
            payoff_hypothesis,
            due_by,
            speculative: true,
        };
    }
