/**
 * Brain Training Handler
 *
 * Executes brain_train UEE tasks:
 * - Evolve population of neural networks
 * - Optimize for specified fitness function
 * - Return best agents + statistics
 */

import { NeuralNetwork, Population, type EvolutionConfig } from "@world-engine/brain";
import type { UnifiedEngineEnvelope } from "@world-engine/protocol";
import { narrowByTaskType } from "@world-engine/protocol";
import type { UEEHandlerContext, UEEHandlerResponse } from "../uee.js";

interface TrainingState {
  populationId: string;
  population: Population;
  startedAt: number;
  lastCheckpoint: number;
}

// Global training sessions: sessionId -> TrainingState
const trainingSessions = new Map<string, TrainingState>();

/**
 * XOR Task: Can network learn XOR logic?
 * Used as default fitness function for testing
 */
function xorFitness(network: NeuralNetwork): number {
  const data = [
    { inputs: [0, 0], expected: 0 },
    { inputs: [0, 1], expected: 1 },
    { inputs: [1, 0], expected: 1 },
    { inputs: [1, 1], expected: 0 },
  ];

  let score = 0;
  for (const { inputs, expected } of data) {
    const output = network.forward(inputs)[0] ?? 0;
    const error = Math.abs(expected - output);
    score += Math.pow(1 - error, 2);
  }
  return score; // 0-4 scale
}

/**
 * Fitness function factory
 */
function createFitnessFunction(taskType: string): (network: NeuralNetwork) => Promise<number> {
  switch (taskType) {
    case "survive":
      // Agent that avoids damage and maintains health
      return async (network) => {
        const inputs = [
          Math.random(), // health
          Math.random(), // nearby_threat_distance
          Math.random(), // energy
        ];
        const outputs = network.forward(inputs);
        const defensiveness = outputs?.[0] ?? 0; // 0-1
        return defensiveness > 0.5 ? 1 : 0; // Survive if defensive
      };

    case "navigate":
      // Agent that reaches targets efficiently
      return async (network) => {
        let score = 0;
        for (let i = 0; i < 5; i++) {
          const inputs = [Math.random(), Math.random(), Math.random()]; // pos, target, obstacles
          const outputs = network.forward(inputs);
          const moveQuality = 1 - Math.abs((outputs?.[0] ?? 0) - 0.7); // Prefer moderate speed
          score += moveQuality;
        }
        return score / 5;
      };

    case "collect":
      // Agent that gathers resources
      return async (network) => {
        let score = 0;
        for (let i = 0; i < 5; i++) {
          const inputs = [Math.random(), Math.random()]; // resource_distance, carrying_capacity
          const outputs = network.forward(inputs);
          const collectDecision = outputs?.[0] ?? 0; // 0-1
          if (collectDecision > 0.5) score++;
        }
        return score;
      };

    case "explore":
      // Agent that discovers the map
      return async (network) => {
        let score = 0;
        for (let i = 0; i < 5; i++) {
          const inputs = [Math.random(), Math.random()]; // unexplored_ratio, risk_level
          const outputs = network.forward(inputs);
          const exploreDrive = outputs?.[0] ?? 0;
          score += exploreDrive;
        }
        return score / 5;
      };

    default:
      // Default to XOR
      return async (network) => xorFitness(network);
  }
}

/**
 * Handle brain_train task: run genetic algorithm on population
 */
export async function handleBrainTrain(
  envelope: UnifiedEngineEnvelope,
  context: UEEHandlerContext
): Promise<UEEHandlerResponse> {
  if (!narrowByTaskType(envelope, "brain_train")) {
    return {
      ok: false,
      taskId: context.taskId,
      taskType: context.taskType,
      errors: ["Expected brain_train task type"],
    };
  }

  const { brain_train } = envelope.inputs as { brain_train?: any };
  if (!brain_train) {
    return {
      ok: false,
      taskId: context.taskId,
      taskType: context.taskType,
      errors: ["Missing brain_train inputs"],
    };
  }

  try {
    const config: EvolutionConfig = {
      populationSize: brain_train.populationSize || 100,
      mutationRate: brain_train.mutationRate || 0.1,
      mutationStrength: brain_train.mutationStrength || 0.5,
      elitism: brain_train.elitism || 5,
      selectionPressure: "top50",
    };

    const generations = brain_train.generations || 10;
    const fitnessType = brain_train.fitnessFunction || "survive";

    // Create or resume population
    const populationId = `pop-${context.taskId}`;
    let state = trainingSessions.get(context.sessionId);

    if (!state) {
      const population = new Population(config, 2, [4], 1); // 2 input, 4 hidden, 1 output
      state = {
        populationId,
        population,
        startedAt: Date.now(),
        lastCheckpoint: Date.now(),
      };
      trainingSessions.set(context.sessionId, state);
    }

    const { population } = state;
    const fitnessFn = createFitnessFunction(fitnessType);

    // Run evolution for N generations
    for (let gen = 0; gen < generations; gen++) {
      await population.evaluate(fitnessFn);

      if (population.bestFitness >= 3.95) {
        // Early stop (good enough)
        break;
      }

      population.evolve();
    }

    // Final evaluation
    await population.evaluate(fitnessFn);

    const best = population.bestAgent;
    if (!best) {
      throw new Error("No best agent found");
    }

    // Package results
    return {
      ok: true,
      taskId: context.taskId,
      taskType: context.taskType,
      outputs: {
        brain_train: {
          populationId,
          generation: population.generation,
          fitnessType,
          bestFitness: population.bestFitness,
          bestNetwork: best.network.toJSON(),
          populationStats: {
            size: population.agents.length,
            avgFitness:
              population.agents.reduce((sum, a) => sum + a.network.fitness, 0) / population.agents.length,
            maxFitness: population.bestFitness,
            minFitness: Math.min(...population.agents.map((a) => a.network.fitness)),
          },
          fitnessHistory: population.fitnessHistory.slice(-20), // Last 20 generations
          solved: population.bestFitness >= 3.95,
        },
      },
      audit: {
        generations_run: population.generation,
        fitness_function: fitnessType,
        convergence: population.bestFitness / 4, // Percentage of max fitness
        duration_ms: Date.now() - state.startedAt,
      },
    };
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    return {
      ok: false,
      taskId: context.taskId,
      taskType: context.taskType,
      errors: [`Brain training failed: ${message}`],
    };
  }
}

/**
 * Get active training session
 */
export function getTrainingSession(sessionId: string): TrainingState | undefined {
  return trainingSessions.get(sessionId);
}

/**
 * List all training sessions
 */
export function listTrainingSessions(): string[] {
  return Array.from(trainingSessions.keys());
}

/**
 * Clear old training sessions (cleanup)
 */
export function cleanupOldSessions(ageMs: number = 3600000): number {
  const now = Date.now();
  let removed = 0;
  for (const [sessionId, state] of trainingSessions.entries()) {
    if (now - state.lastCheckpoint > ageMs) {
      trainingSessions.delete(sessionId);
      removed++;
    }
  }
  return removed;
}

export default handleBrainTrain;

/**
 * Nucleus UEE Router
 *
 * Routes Unified Engine Envelope tasks to handlers by task.type.
 * Central dispatch point for task execution + orchestration.
 *
 * Architecture:
 * - ParentBusEnvelope (transport) wraps UEE payload
 * - Router dispatches by task.type
 * - Handlers return typed outputs + audit + state_delta
 * - Consistent response shape across all task types
 */

import type { UnifiedEngineEnvelope } from "@world-engine/protocol";
import {
  getTaskId,
  getTaskType,
  hasRequiredInputs,
  narrowByTaskType,
  parseUEE,
  shouldIncludeField
} from "@world-engine/protocol";
import handleBrainControl from "./handlers/brainControl.js";
import handleBrainTrain from "./handlers/brainTrain.js";

// ============================================================================
// Handler Types
// ============================================================================

/**
 * Base handler context: shared by all task handlers
 */
export interface UEEHandlerContext {
  taskId: string;
  taskType: string;
  mode: "generate" | "apply" | "analyze";
  sessionId: string;
  timestamp: number;
}

/**
 * Handler response: consistent structure across all task types
 */
export interface UEEHandlerResponse {
  ok: boolean;
  taskId: string;
  taskType: string;
  outputs?: Record<string, unknown>;
  audit?: Record<string, unknown>;
  state_delta?: { story_state?: Record<string, unknown>; lexicon_state?: Record<string, unknown> };
  errors?: string[];
}

/**
 * Handler function: receives envelope + context, returns typed response
 */
export type UEEHandler = (
  envelope: UnifiedEngineEnvelope,
  context: UEEHandlerContext
) => Promise<UEEHandlerResponse>;

/**
 * Handler registry: task type ΓåÆ handler
 */
interface HandlerRegistry {
  [taskType: string]: UEEHandler;
}

// ============================================================================
// Router Class
// ============================================================================

export class UEERouter {
  private handlers: HandlerRegistry = {};
  private readonly logger = console; // Replace with your logger

  constructor() {
    // Register default handlers (stubs)
    this.registerHandler("lexicon_op", this.handleLexiconOp.bind(this));
    this.registerHandler("hce_run", this.handleHceRun.bind(this));
    this.registerHandler("scene_gen", this.handleSceneGen.bind(this));
    this.registerHandler("analyze_sentence", this.handleAnalyzeSentence.bind(this));

    // Register brain handlers
    this.registerHandler("brain_control", handleBrainControl);
    this.registerHandler("brain_train", handleBrainTrain);
  }

  // ========================================================================
  // Public API
  // ========================================================================

  /**
   * Register a handler for a task type
   */
  registerHandler(taskType: string, handler: UEEHandler): void {
    this.handlers[taskType] = handler;
    this.logger.log(`[UEE Router] Registered handler for task type: ${taskType}`);
  }

  /**
   * Route and execute a UEE envelope
   */
  async route(
    input: unknown,
    sessionId: string
  ): Promise<UEEHandlerResponse> {
    // Parse
    const parseResult = parseUEE(input);
    if (!parseResult.ok) {
      return {
        ok: false,
        taskId: "unknown",
        taskType: "unknown",
        errors: [parseResult.message],
      };
    }

    const envelope = parseResult.envelope;
    const taskType = getTaskType(envelope);
    const taskId = getTaskId(envelope);

    // Validate required inputs
    if (!hasRequiredInputs(envelope)) {
      return {
        ok: false,
        taskId,
        taskType,
        errors: [`Task type "${taskType}" missing required inputs`],
      };
    }

    // Create context
    const context: UEEHandlerContext = {
      taskId,
      taskType,
      mode: envelope.task.mode,
      sessionId,
      timestamp: Date.now(),
    };

    // Dispatch
    const handler = this.handlers[taskType];
    if (!handler) {
      return {
        ok: false,
        taskId,
        taskType,
        errors: [`No handler registered for task type: ${taskType}`],
      };
    }

    try {
      this.logger.log(`[UEE Router] Routing task: ${taskType} (id=${taskId})`);
      const response = await handler(envelope, context);

      // Respect controls.return config: only include requested fields
      if (!shouldIncludeField(envelope, "include_prose")) {
        delete response.outputs;
      }
      if (!shouldIncludeField(envelope, "include_audit")) {
        delete response.audit;
      }
      if (!shouldIncludeField(envelope, "include_state_delta")) {
        delete response.state_delta;
      }

      this.logger.log(
        `[UEE Router] Task complete: ${taskType} (id=${taskId}) ok=${response.ok}`
      );
      return response;
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      this.logger.error(
        `[UEE Router] Handler error for ${taskType} (id=${taskId}):`,
        message
      );
      return {
        ok: false,
