// Global tracking of active tool executors by sessionId
// Used to route tool.effect.v1 responses from IDE back to the executor
const toolExecutorsBySession = new Map<string, ToolExecutor>();

function safeJsonParse(s: string): unknown {
  try {
    return JSON.parse(s);
  } catch {
    return null;
  }
}

function send<T extends keyof MessageMap>(
  ws: WebSocket,
  env: BusEnvelope<T, MessageMap[T]>
): void {
  ws.send(JSON.stringify(env));
}

/**
 * ---- Security policy knobs ----
 */
const HUB_INSTANCE_ID = "nucleus_1";

const MAX_PAYLOAD_BYTES = 256 * 1024; // 256KB (raise later if needed)
const CLOCK_SKEW_MS = 60_000;         // +/- 60s window
const NONCE_TTL_MS = 60_000;          // keep seen nonces for 60s

// Simple token bucket: allow ~120 msgs / 10s burst, refill smoothly
const RL_BUCKET_MAX = 120;
const RL_REFILL_PER_SEC = 12;

type ClientCaps = Set<string>;

type ClientInfo = {
  ws: WebSocket;
  sessionId: string;
  instanceId: string;

  // granted at handshake
  role: Role | "unknown";
  token: string;
  caps: ClientCaps;

  // replay + rate-limit
  nonceSeen: Map<string, number>; // nonce -> expiryMs
  rlTokens: number;
  rlLastRefillMs: number;
};

function setHasAny(caps: ClientCaps, required: readonly string[]): boolean {
  for (const r of required) if (caps.has(r)) return true;
  return false;
}

function refillRateLimit(c: ClientInfo, now: number): void {
  const dtSec = Math.max(0, (now - c.rlLastRefillMs) / 1000);
  if (dtSec <= 0) return;
  c.rlTokens = Math.min(RL_BUCKET_MAX, c.rlTokens + dtSec * RL_REFILL_PER_SEC);
  c.rlLastRefillMs = now;
}

function consumeToken(c: ClientInfo): boolean {
  if (c.rlTokens < 1) return false;
  c.rlTokens -= 1;
  return true;
}

function pruneNonces(c: ClientInfo, now: number): void {
  // prevent unbounded growth
  if (c.nonceSeen.size <= 512) return;
  for (const [nonce, exp] of c.nonceSeen) {
    if (exp <= now) c.nonceSeen.delete(nonce);
    if (c.nonceSeen.size <= 384) break;
  }
}

function verifyNonce(c: ClientInfo, nonce: string, now: number): boolean {
  pruneNonces(c, now);
  const existingExp = c.nonceSeen.get(nonce);
  if (existingExp && existingExp > now) return false; // replay
  c.nonceSeen.set(nonce, now + NONCE_TTL_MS);
  return true;
}

function requireCapOrReject(
  c: ClientInfo,
  ws: WebSocket,
  sessionId: string,
  required: readonly string[],
  reason: string
): boolean {
  if (setHasAny(c.caps, required)) return true;

  // structured error back to caller
  const env: AnyEnv = {
    v: 2,
    id: randomId("srv"),
    type: "system.error" as any,
    ts: nowMs(),
    from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
    sessionId,
    payload: {
      code: "CAP_DENIED",
      message: reason,
      requiredCaps: required,
    },
  };
  try {
    ws.send(JSON.stringify(env));
  } catch { }
  return false;
}

function requiredCapsForMessageType(type: string): readonly string[] {
  // One canonical mapping.
  // NOTE: you can tune names later; the point is stable gating.
  switch (type) {
    case "uee":
      return ["cap:uee:invoke"];
    case "pty.open":
    case "pty.input":
    case "pty.resize":
      return ["cap:pty:write"];
    case "ops.sim.start":
    case "ops.sim.stop":
      return ["cap:sim:control"];
    case "ops.sim.status":
      return ["cap:sim:read"];
    case "preview.stats":
      return ["cap:preview:write"];
    case "preview.ping":
      return ["cap:preview:write"];
    case "chat.request.v1":
      return ["cap:chat:send"];
    case "chat.request":
    case "brain.chat":
      return ["cap:chat:send"];
    default:
      // By default, require nothing for unknown types (or block them if you prefer).
      // Safer option is to block unknown types explicitly.
      return [];
  }
}

function requiredCapsForTaskType(taskType: UEETaskType): readonly string[] {
  switch (taskType) {
    case "brain_control":
      return ["cap:brain:control"];
    case "brain_train":
      return ["cap:brain:train"];
    case "lexicon_op":
      return ["cap:lexicon:write"];
    case "hce_run":
      return ["cap:hce:run"];
    case "scene_gen":
      return ["cap:scene:gen"];
    case "analyze_sentence":
      return ["cap:analyze:run"];
    default:
      return ["cap:uee:invoke"];
  }
}

function grantCapsForRole(role: Role | "unknown"): string[] {
  // This is the real source of truth. Client "caps" are ignored.
  if (role === "ide") {
    return [
      "cap:uee:invoke",
      "cap:pty:write",
      "cap:sim:control",
      "cap:sim:read",
      "cap:preview:read", // IDE receives preview stats
      "cap:files:read",   // later: files.list, etc.
      // OPTIONAL: allow IDE to train (maybe too strong; you decide)
      "cap:brain:control",
      "cap:brain:train",
      "cap:lexicon:write",
      "cap:analyze:run",
      "cap:chat:send",    // Brain-driven chat system
    ];
  }
  if (role === "preview") {
    return [
      "cap:preview:write", // can emit stats/ping/pong
      "cap:uee:invoke",    // OPTIONAL: remove if preview should never call UEE
    ];
  }
  return [];
}

export function createHub(wss: WebSocketServer): void {
  const veno = new VenoManager();
  const sim = new SimRunner();
  let nextSession = 1;

  const clients = new Set<ClientInfo>();

  function broadcastTo(role: Role, env: AnyEnv): void {
    for (const c of clients) {
      if (c.role !== role) continue;
      try {
        c.ws.send(JSON.stringify(env));
      } catch (err) {
        console.warn(`[wsHub] Broadcast to ${role} failed:`, err instanceof Error ? err.message : String(err));
        // Socket likely closed; client will reconnect on next attempt
      }
    }
  }

  // ---- Sim event handlers ----
  sim.on("log", (ev: any) => {
    const env: BusEnvelope<"sim.log", MessageMap["sim.log"]> = {
      v: 2,
      id: randomId("srv"),
      type: "sim.log",
      ts: nowMs(),
      from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
      sessionId: "broadcast",
      payload: { level: ev.level, line: ev.line, ts: ev.ts },
    };
    broadcastTo("ide", env as AnyEnv);
  });

  sim.on("start", (ev: any) => {
    const env: BusEnvelope<"sim.start", MessageMap["sim.start"]> = {
      v: 2,
      id: randomId("srv"),
      type: "sim.start",
      ts: nowMs(),
      from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
      sessionId: "broadcast",
      payload: { simId: ev.simId, port: ev.port },
    };
    broadcastTo("ide", env as AnyEnv);
  });

  sim.on("done", (ev: any) => {
    const env: BusEnvelope<"sim.done", MessageMap["sim.done"]> = {
      v: 2,
      id: randomId("srv"),
      type: "sim.done",
      ts: nowMs(),
      from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
      sessionId: "broadcast",
      payload: {
        ok: ev.ok,
        code: ev.code,
        durationMs: ev.ts - ((sim as any).startTime ?? 0),
      },
    };
    broadcastTo("ide", env as AnyEnv);
  });

  // --- File watcher (repo root) ---
  const repoRoot = path.resolve(process.cwd(), "../..");
  const watcher = chokidar.watch(repoRoot, {
    ignoreInitial: true,
    ignored: [
      "**/node_modules/**",
      "**/.git/**",
      "**/dist/**",
      "**/.next/**",
      "**/.turbo/**",
      "**/.vite/**",
      "**/.cache/**",
      "**/coverage/**",
      "**/tools/veno/**",
    ],
  });

  watcher.on("all", (event: string, changedPath: string) => {
    let kind: "add" | "unlink" | "change";
    if (event === "add") kind = "add";
    else if (event === "unlink") kind = "unlink";
    else kind = "change";

    const env: BusEnvelope<"files.changed", MessageMap["files.changed"]> = {
      v: 2,
      id: randomId("srv"),
      type: "files.changed",
      ts: nowMs(),
      from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
      sessionId: "broadcast",
      payload: { path: changedPath, kind, ts: nowMs() },
    };

    broadcastTo("ide", env as AnyEnv);
  });

  wss.on("connection", (ws: WebSocket) => {
    const sessionId = `sess_${nextSession++}`;
    const instanceId = randomId("client");
    const token = randomId("tok"); // session token (server-issued)

    const client: ClientInfo = {
      ws,
      sessionId,
      instanceId,
      role: "unknown",
      token,
      caps: new Set<string>(),
      nonceSeen: new Map<string, number>(),
      rlTokens: RL_BUCKET_MAX,
      rlLastRefillMs: nowMs(),
    };
    clients.add(client);

    ws.on("message", async (buf: unknown) => {
      // --- size guard (raw) ---
      const raw =
        typeof buf === "string" ? buf : (buf as Buffer).toString("utf8");
      if (raw.length > MAX_PAYLOAD_BYTES) return;

      const parsed = safeJsonParse(raw);
      const checked = EnvelopeSchema.safeParse(parsed);
      if (!checked.success) return;

      const env = checked.data as AnyEnv;
      const now = nowMs();

      // --- rate limit (per session) ---
      refillRateLimit(client, now);
      if (!consumeToken(client)) return;

      // ---- handshake (ONLY message allowed without auth+nonce) ----
      if (env.type === "system.hello") {
        const requested = (env.payload as any)?.requestedRole as
          | Role
          | undefined;

        // DO NOT trust arbitrary roles
        const role: Role | "unknown" =
          requested === "ide" || requested === "preview" ? requested : "unknown";

        client.role = role;
        const caps = grantCapsForRole(role);
        client.caps = new Set(caps);

        // Welcome includes the token the client must use on every subsequent message
        send(ws, {
          v: 2,
          id: randomId("srv"),
          type: "system.welcome",
          ts: now,
          from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
          sessionId,
          auth: { kind: "session", token },
          payload: {
            assignedInstanceId: instanceId,
            caps,
            serverTimeMs: now,
            policy: {
              maxPayloadBytes: MAX_PAYLOAD_BYTES,
              clockSkewMs: CLOCK_SKEW_MS,
              nonceTtlMs: NONCE_TTL_MS,
              rateLimit: {
                bucketMax: RL_BUCKET_MAX,
                refillPerSec: RL_REFILL_PER_SEC,
              },
            },
          },
        } satisfies BusEnvelope<"system.welcome", MessageMap["system.welcome"]>);

        return;
      }

      // --- require session binding ---
      if (env.sessionId !== sessionId) return;

      // --- require auth ---
      const auth = (env as AnyEnv).auth;
      if (!auth || auth.kind !== "session" || auth.token !== client.token) {
        return;
      }

      // --- require nonce + replay protection ---
      const nonce = (env as AnyEnv).nonce;
      if (!nonce || typeof nonce !== "string") return;
      if (!verifyNonce(client, nonce, now)) return;

      // --- clock skew guard ---
      const dt = Math.abs(now - env.ts);
      if (dt > CLOCK_SKEW_MS) return;

      // --- capability gating by message type ---
      const msgCaps = requiredCapsForMessageType(env.type);
      if (msgCaps.length > 0) {
        const ok = requireCapOrReject(
          client,
          ws,
          sessionId,
          msgCaps,
          `Denied message type "${env.type}".`
        );
        if (!ok) return;
      } else {
        // Safer default: block unknown message types after handshake
        // (prevents "new type" from silently becoming an attack path)
        // If you want permissive mode, delete this block.
        const known =
          env.type === "uee" ||
          env.type === "pty.open" ||
          env.type === "pty.resize" ||
          env.type === "pty.input" ||
          env.type === "preview.ping" ||
          env.type === "preview.stats" ||
          env.type === "ops.sim.start" ||
          env.type === "ops.sim.stop" ||
          env.type === "chat.request.v1" ||
          env.type === "chat.request" ||
          env.type === "brain.chat" ||
          env.type === "tool.effect.v1" ||
          env.type === "ops.sim.status";
        if (!known) return;
      }

      // ---- UEE task dispatch ----
      if (env.type === "uee") {
        // validate task envelope before routing (prevents weird inputs)
        const parsedUEE = parseUEE(env.payload);
        if (!parsedUEE.ok) {
          const errorMsg: unknown = {
            v: 2,
            id: randomId("srv"),
            type: "uee.error",
            ts: nowMs(),
            from: { role: "nucleus" as const, instanceId: HUB_INSTANCE_ID },
            sessionId,
            auth: { kind: "session" as const, token: client.token },
            nonce: randomId("n"),
            payload: { error: parsedUEE.message },
          };
          send(ws, errorMsg as any);
          return;
        }

        const taskType = parsedUEE.envelope.task.type;
        const taskCaps = requiredCapsForTaskType(taskType);
        if (
          !requireCapOrReject(
            client,
            ws,
            sessionId,
            taskCaps,
            `Denied task "${taskType}".`
          )
        ) {
          return;
        }

        try {
          const router = getUEERouter();
          const response = await router.route(env.payload, sessionId);

          const successMsg: unknown = {
            v: 2,
            id: randomId("srv"),
            type: "uee.response",
            ts: nowMs(),
            from: { role: "nucleus" as const, instanceId: HUB_INSTANCE_ID },
            sessionId,
            auth: { kind: "session" as const, token: client.token },
            nonce: randomId("n"),
            payload: response,
          };
          send(ws, successMsg as any);
        } catch (err) {
          const errMsg: unknown = {
            v: 2,
            id: randomId("srv"),
            type: "uee.error",
            ts: nowMs(),
            from: { role: "nucleus" as const, instanceId: HUB_INSTANCE_ID },
            sessionId,
            auth: { kind: "session" as const, token: client.token },
            nonce: randomId("n"),
            payload: { error: err instanceof Error ? err.message : String(err) },
          };
          send(ws, errMsg as any);
        }
        return;
      }

      // ---- PTY open ----
      if (env.type === "pty.open") {
        const p = env.payload as MessageMap["pty.open"];
        if (p.program !== "veno") return;

        const opened = await veno.openVeno(sessionId, {
          cols: p.cols,
          rows: p.rows,
          onData: (ptyId, data) => {
            send(ws, {
              v: 2,
              id: randomId("srv"),
              type: "pty.output",
              ts: nowMs(),
              from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
              sessionId,
              auth: { kind: "session", token: client.token },
              nonce: randomId("n"),
              payload: { ptyId, data },
            } satisfies BusEnvelope<"pty.output", MessageMap["pty.output"]>);
          },
        });

        send(ws, {
          v: 2,
          id: randomId("srv"),
          type: "pty.opened",
          ts: nowMs(),
          from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
          sessionId,
          auth: { kind: "session", token: client.token },
          nonce: randomId("n"),
          payload: { ptyId: opened },
        } satisfies BusEnvelope<"pty.opened", MessageMap["pty.opened"]>);

        return;
      }

      // ---- PTY resize ----
      if (env.type === "pty.resize") {
        const p = env.payload as MessageMap["pty.resize"];
        veno.resize(p.ptyId, p.cols, p.rows);
        return;
      }

      // ---- PTY input ----
      if (env.type === "pty.input") {
        const p = env.payload as MessageMap["pty.input"];
        veno.write(p.ptyId, p.data);
        return;
      }

      // ---- chat request (streaming NDJSON) ----
      if (env.type === "chat.request.v1") {
        await handleChatRequestStreaming(ws, env, sessionId, client.token, HUB_INSTANCE_ID, toolExecutorsBySession);
        return;
      }

      // ---- chat request ----
      if (env.type === "chat.request") {
        await chatHandler.handleChatRequest(env as any, ws);
        return;
      }

      // ---- brain chat (streamed mode) ----
      if (env.type === "brain.chat") {
        await chatHandler.handleBrainChat(env as any, ws);
        return;
      }

      // ---- tool effect (IDE response to tool.command.v1) ----
      if (env.type === "tool.effect.v1") {
        const executor = toolExecutorsBySession.get(sessionId);
        if (executor) {
          executor.handleToolEffectFromIde(env as any);
        }
        return;
      }

      // ---- ide.cli.run.request ----
      if (env.type === "ide.cli.run.request") {
        const p = env.payload as MessageMap["ide.cli.run.request"];
        let exitCode = 0;
        let stdout = "";
        let stderr = "";
        let ok = true;

        try {
          const cwd = p.cwd ? path.resolve(p.cwd) : process.cwd();
          // Execute command synchronously with timeout
          const result = execSync(p.command, {
            cwd,
            encoding: "utf8",
            timeout: p.timeoutMs,
            stdio: ["pipe", "pipe", "pipe"],
          });
          stdout = result;
        } catch (err: any) {
          ok = false;
          exitCode = err.status ?? 1;
          stdout = err.stdout?.toString() ?? "";
          stderr = err.stderr?.toString() ?? err.message ?? "Unknown error";
        }

        send(ws, {
          v: 2,
          id: randomId("srv"),
          type: "ide.cli.run.response",
          ts: nowMs(),
          from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
          sessionId,
          auth: { kind: "session", token: client.token },
          nonce: randomId("n"),
          payload: { ok, exitCode, stdout, stderr },
        } as any);
        return;
      }

      // ---- ide.fs.read.request ----
      if (env.type === "ide.fs.read.request") {
        const p = env.payload as MessageMap["ide.fs.read.request"];
        let ok = true;
        let content: string | undefined;
        let error: string | undefined;

        try {
          const filePath = path.resolve(p.path);
          // Read file with size limit
          const stats = fs.statSync(filePath);
          if (stats.size > p.maxBytes) {
            throw new Error(
              `File size (${stats.size} bytes) exceeds limit (${p.maxBytes} bytes)`
            );
          }
          content = fs.readFileSync(filePath, p.encoding);
        } catch (err: any) {
          ok = false;
          error = err.message ?? "Unknown error";
        }

        send(ws, {
          v: 2,
          id: randomId("srv"),
          type: "ide.fs.read.response",
          ts: nowMs(),
          from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
          sessionId,
          auth: { kind: "session", token: client.token },
          nonce: randomId("n"),
          payload: { ok, path: p.path, content, error },
        } as any);
        return;
      }

      // ---- preview ping/pong ----
      if (env.type === "preview.ping") {
        const p = env.payload as MessageMap["preview.ping"];
        send(ws, {
          v: 2,
          id: randomId("srv"),
          type: "preview.pong",
          ts: nowMs(),
          from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
          sessionId,
          auth: { kind: "session", token: client.token },
          nonce: randomId("n"),
          payload: { n: p.n },
        } satisfies BusEnvelope<"preview.pong", MessageMap["preview.pong"]>);
        return;
      }

      // ---- preview.stats: broadcast to IDE ----
      if (env.type === "preview.stats") {
        const p = env.payload as MessageMap["preview.stats"];
        const broadcast: BusEnvelope<"preview.stats", MessageMap["preview.stats"]> =
        {
          v: 2,
          id: randomId("srv"),
          type: "preview.stats",
          ts: nowMs(),
          from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
          sessionId: "broadcast",
          payload: p,
        };
        broadcastTo("ide", broadcast as AnyEnv);
        return;
      }

      // ---- ops.sim.start ----
      if (env.type === "ops.sim.start") {
        const p = env.payload as MessageMap["ops.sim.start"];
        sim.request({ mode: p.mode ?? "dev", port: p.port ?? 4010 });
        return;
      }

      // ---- ops.sim.stop ----
      if (env.type === "ops.sim.stop") {
        sim.stop();
        return;
      }

      // ---- ops.sim.status ----
      if (env.type === "ops.sim.status") {
        const status = sim.getStatus();
        send(ws, {
          v: 2,
          id: randomId("srv"),
          type: "ops.sim.status.reply",
          ts: nowMs(),
          from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
          sessionId,
          auth: { kind: "session", token: client.token },
          nonce: randomId("n"),
          payload: status,
        } satisfies BusEnvelope<
          "ops.sim.status.reply",
          MessageMap["ops.sim.status.reply"]
        >);
        return;
      }
    });

    ws.on("close", () => {
      veno.closeAllForSession(sessionId);
      clients.delete(client);
    });
  });

  // ---- Health Poller ----
  // Start polling system health and broadcast to IDE clients
  const hubPresence = createHubPresenceAdapter(clients);
  const busLike = createBusLikeAdapter(broadcastTo);
  const sessionId = `nucleus.${HUB_INSTANCE_ID}`;

  startHealthPoller({
    bus: busLike,
    hubPresence,
    sessionId,
    sidecarBaseUrl: process.env.SIDECAR_URL ?? "http://127.0.0.1:8001",
    intervalMs: 1000,
    nucleusVersion: process.env.npm_package_version
  });
}

import chokidar from "chokidar";
import path from "node:path";
import type { WebSocket, WebSocketServer } from "ws";

import {
    EnvelopeSchema,
    nowMs,
    randomId,
    type BusEnvelope,
    type MessageMap,
    type Role,
 parseUEE, type UEETaskType } from "@world-engine/protocol";

import { VenoManager } from "./pty/venoManager";
import { getUEERouter } from "./router/uee.js";
import { SimRunner } from "./services/simRunner";

type AnyEnv = BusEnvelope<string, unknown>;

function safeJsonParse(s: string): unknown {
    try {
        return JSON.parse(s);
    } catch {
        return null;
    }
}

function send<T extends keyof MessageMap>(
    ws: WebSocket,
    env: BusEnvelope<T, MessageMap[T]>
): void {
    ws.send(JSON.stringify(env));
}

/**
 * ---- Security policy knobs ----
 */
const HUB_INSTANCE_ID = "nucleus_1";

const MAX_PAYLOAD_BYTES = 256 * 1024; // 256KB (raise later if needed)
const CLOCK_SKEW_MS = 60_000;         // +/- 60s window
const NONCE_TTL_MS = 60_000;          // keep seen nonces for 60s

// Simple token bucket: allow ~120 msgs / 10s burst, refill smoothly
const RL_BUCKET_MAX = 120;
const RL_REFILL_PER_SEC = 12;

type ClientCaps = Set<string>;

type ClientInfo = {
    ws: WebSocket;
    sessionId: string;
    instanceId: string;

    // granted at handshake
    role: Role | "unknown";
    token: string;
    caps: ClientCaps;

    // replay + rate-limit
    nonceSeen: Map<string, number>; // nonce -> expiryMs
    rlTokens: number;
    rlLastRefillMs: number;
};

function setHasAny(caps: ClientCaps, required: readonly string[]): boolean {
    for (const r of required) if (caps.has(r)) return true;
    return false;
}

function refillRateLimit(c: ClientInfo, now: number): void {
    const dtSec = Math.max(0, (now - c.rlLastRefillMs) / 1000);
    if (dtSec <= 0) return;
    c.rlTokens = Math.min(RL_BUCKET_MAX, c.rlTokens + dtSec * RL_REFILL_PER_SEC);
    c.rlLastRefillMs = now;
}

function consumeToken(c: ClientInfo): boolean {
    if (c.rlTokens < 1) return false;
    c.rlTokens -= 1;
    return true;
}

function pruneNonces(c: ClientInfo, now: number): void {
    // prevent unbounded growth
    if (c.nonceSeen.size <= 512) return;
    for (const [nonce, exp] of c.nonceSeen) {
        if (exp <= now) c.nonceSeen.delete(nonce);
        if (c.nonceSeen.size <= 384) break;
    }
}

function verifyNonce(c: ClientInfo, nonce: string, now: number): boolean {
    pruneNonces(c, now);
    const existingExp = c.nonceSeen.get(nonce);
    if (existingExp && existingExp > now) return false; // replay
    c.nonceSeen.set(nonce, now + NONCE_TTL_MS);
    return true;
}

function requireCapOrReject(
    c: ClientInfo,
    ws: WebSocket,
    sessionId: string,
    required: readonly string[],
    reason: string
): boolean {
    if (setHasAny(c.caps, required)) return true;

    // structured error back to caller
    const env: AnyEnv = {
        v: 2,
        id: randomId("srv"),
        type: "system.error" as any,
        ts: nowMs(),
        from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
        sessionId,
        payload: {
            code: "CAP_DENIED",
            message: reason,
            requiredCaps: required,
        },
    };
    try {
        ws.send(JSON.stringify(env));
    } catch { }
    return false;
}

function requiredCapsForMessageType(type: string): readonly string[] {
    // One canonical mapping.
    // NOTE: you can tune names later; the point is stable gating.
    switch (type) {
        case "uee":
            return ["cap:uee:invoke"];
        case "pty.open":
        case "pty.input":
        case "pty.resize":
            return ["cap:pty:write"];
        case "ops.sim.start":
        case "ops.sim.stop":
            return ["cap:sim:control"];
        case "ops.sim.status":
            return ["cap:sim:read"];
        case "preview.stats":
            return ["cap:preview:write"];
        case "preview.ping":
            return ["cap:preview:write"];
        default:
            // By default, require nothing for unknown types (or block them if you prefer).
            // Safer option is to block unknown types explicitly.
            return [];
    }
}

function requiredCapsForTaskType(taskType: UEETaskType): readonly string[] {
    switch (taskType) {
        case "brain_control":
            return ["cap:brain:control"];
        case "brain_train":
            return ["cap:brain:train"];
        case "lexicon_op":
            return ["cap:lexicon:write"];
        case "hce_run":
            return ["cap:hce:run"];
        case "scene_gen":
            return ["cap:scene:gen"];
        case "analyze_sentence":
            return ["cap:analyze:run"];
        default:
            return ["cap:uee:invoke"];
    }
}

function grantCapsForRole(role: Role | "unknown"): string[] {
    // This is the real source of truth. Client "caps" are ignored.
    if (role === "ide") {
        return [
            "cap:uee:invoke",
            "cap:pty:write",
            "cap:sim:control",
            "cap:sim:read",
            "cap:preview:read", // IDE receives preview stats
            "cap:files:read",   // later: files.list, etc.
            // OPTIONAL: allow IDE to train (maybe too strong; you decide)
            "cap:brain:control",
            "cap:brain:train",
            "cap:lexicon:write",
            "cap:analyze:run",
        ];
    }
    if (role === "preview") {
        return [
            "cap:preview:write", // can emit stats/ping/pong
            "cap:uee:invoke",    // OPTIONAL: remove if preview should never call UEE
        ];
    }
    return [];
}

export function createHub(wss: WebSocketServer): void {
    const veno = new VenoManager();
    const sim = new SimRunner();
    let nextSession = 1;

    const clients = new Set<ClientInfo>();

    function broadcastTo(role: Role, env: AnyEnv): void {
        for (const c of clients) {
            if (c.role !== role) continue;
            try {
                c.ws.send(JSON.stringify(env));
            } catch { }
        }
    }

    // ---- Sim event handlers ----
    sim.on("log", (ev: any) => {
        const env: BusEnvelope<"sim.log", MessageMap["sim.log"]> = {
            v: 2,
            id: randomId("srv"),
            type: "sim.log",
            ts: nowMs(),
            from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
            sessionId: "broadcast",
            payload: { level: ev.level, line: ev.line, ts: ev.ts },
        };
        broadcastTo("ide", env as AnyEnv);
    });

    sim.on("start", (ev: any) => {
        const env: BusEnvelope<"sim.start", MessageMap["sim.start"]> = {
            v: 2,
            id: randomId("srv"),
            type: "sim.start",
            ts: nowMs(),
            from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
            sessionId: "broadcast",
            payload: { simId: ev.simId, port: ev.port },
        };
        broadcastTo("ide", env as AnyEnv);
    });

    sim.on("done", (ev: any) => {
        const env: BusEnvelope<"sim.done", MessageMap["sim.done"]> = {
            v: 2,
            id: randomId("srv"),
            type: "sim.done",
            ts: nowMs(),
            from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
            sessionId: "broadcast",
            payload: {
                ok: ev.ok,
                code: ev.code,
                durationMs: ev.ts - ((sim as any).startTime ?? 0),
            },
        };
        broadcastTo("ide", env as AnyEnv);
    });

    // --- File watcher (repo root) ---
    const repoRoot = path.resolve(process.cwd(), "../..");
    const watcher = chokidar.watch(repoRoot, {
        ignoreInitial: true,
        ignored: [
            "**/node_modules/**",
            "**/.git/**",
            "**/dist/**",
            "**/.next/**",
            "**/.turbo/**",
            "**/.vite/**",
            "**/.cache/**",
            "**/coverage/**",
            "**/tools/veno/**",
        ],
    });

    watcher.on("all", (event: string, changedPath: string) => {
        let kind: "add" | "unlink" | "change";
        if (event === "add") kind = "add";
        else if (event === "unlink") kind = "unlink";
        else kind = "change";

        const env: BusEnvelope<"files.changed", MessageMap["files.changed"]> = {
            v: 2,
            id: randomId("srv"),
            type: "files.changed",
            ts: nowMs(),
            from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
            sessionId: "broadcast",
            payload: { path: changedPath, kind, ts: nowMs() },
        };

        broadcastTo("ide", env as AnyEnv);
    });

    wss.on("connection", (ws: WebSocket) => {
        const sessionId = `sess_${nextSession++}`;
        const instanceId = randomId("client");
        const token = randomId("tok"); // session token (server-issued)

        const client: ClientInfo = {
            ws,
            sessionId,
            instanceId,
            role: "unknown",
            token,
            caps: new Set<string>(),
            nonceSeen: new Map<string, number>(),
            rlTokens: RL_BUCKET_MAX,
            rlLastRefillMs: nowMs(),
        };
        clients.add(client);

        ws.on("message", async (buf: unknown) => {
            // --- size guard (raw) ---
            const raw =
                typeof buf === "string" ? buf : (buf as Buffer).toString("utf8");
            if (raw.length > MAX_PAYLOAD_BYTES) return;

            const parsed = safeJsonParse(raw);
            const checked = EnvelopeSchema.safeParse(parsed);
            if (!checked.success) return;

            const env = checked.data as AnyEnv;
            const now = nowMs();

            // --- rate limit (per session) ---
            refillRateLimit(client, now);
            if (!consumeToken(client)) return;

            // ---- handshake (ONLY message allowed without auth+nonce) ----
            if (env.type === "system.hello") {
                const requested = (env.payload as any)?.requestedRole as
                    | Role
                    | undefined;

                // DO NOT trust arbitrary roles
                const role: Role | "unknown" =
                    requested === "ide" || requested === "preview" ? requested : "unknown";

                client.role = role;
                const caps = grantCapsForRole(role);
                client.caps = new Set(caps);

                // Welcome includes the token the client must use on every subsequent message
                send(ws, {
                    v: 2,
                    id: randomId("srv"),
                    type: "system.welcome",
                    ts: now,
                    from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
                    sessionId,
                    auth: { kind: "session", token },
                    payload: {
                        assignedInstanceId: instanceId,
                        caps,
                        serverTimeMs: now,
                        policy: {
                            maxPayloadBytes: MAX_PAYLOAD_BYTES,
                            clockSkewMs: CLOCK_SKEW_MS,
                            nonceTtlMs: NONCE_TTL_MS,
                            rateLimit: {
                                bucketMax: RL_BUCKET_MAX,
                                refillPerSec: RL_REFILL_PER_SEC,
                            },
                        },
                    },
                } satisfies BusEnvelope<"system.welcome", MessageMap["system.welcome"]>);

                return;
            }

            // --- require session binding ---
            if (env.sessionId !== sessionId) return;

            // --- require auth ---
            const auth = (env as AnyEnv).auth;
            if (!auth || auth.kind !== "session" || auth.token !== client.token) {
                return;
            }

            // --- require nonce + replay protection ---
            const nonce = (env as AnyEnv).nonce;
            if (!nonce || typeof nonce !== "string") return;
            if (!verifyNonce(client, nonce, now)) return;

            // --- clock skew guard ---
            const dt = Math.abs(now - env.ts);
            if (dt > CLOCK_SKEW_MS) return;

            // --- capability gating by message type ---
            const msgCaps = requiredCapsForMessageType(env.type);
            if (msgCaps.length > 0) {
                const ok = requireCapOrReject(
                    client,
                    ws,
                    sessionId,
                    msgCaps,
                    `Denied message type "${env.type}".`
                );
                if (!ok) return;
            } else {
                // Safer default: block unknown message types after handshake
                // (prevents "new type" from silently becoming an attack path)
                // If you want permissive mode, delete this block.
                const known =
                    env.type === "uee" ||
                    env.type === "pty.open" ||
                    env.type === "pty.resize" ||
                    env.type === "pty.input" ||
                    env.type === "preview.ping" ||
                    env.type === "preview.stats" ||
                    env.type === "ops.sim.start" ||
                    env.type === "ops.sim.stop" ||
                    env.type === "ops.sim.status";
                if (!known) return;
            }

            // ---- UEE task dispatch ----
            if (env.type === "uee") {
                // validate task envelope before routing (prevents weird inputs)
                const parsedUEE = parseUEE(env.payload);
                if (!parsedUEE.ok) {
                    send(ws, {
                        v: 2,
                        id: randomId("srv"),
                        type: "uee.error",
                        ts: nowMs(),
                        from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
                        sessionId,
                        auth: { kind: "session", token: client.token },
                        nonce: randomId("n"),
                        payload: { error: parsedUEE.message },
                    } satisfies BusEnvelope<"uee.error", any>);
                    return;
                }

                const taskType = parsedUEE.envelope.task.type;
                const taskCaps = requiredCapsForTaskType(taskType);
                if (
                    !requireCapOrReject(
                        client,
                        ws,
                        sessionId,
                        taskCaps,
                        `Denied task "${taskType}".`
                    )
                ) {
                    return;
                }

                try {
                    const router = getUEERouter();
                    const response = await router.route(env.payload, sessionId);

                    send(ws, {
                        v: 2,
                        id: randomId("srv"),
                        type: "uee.response",
                        ts: nowMs(),
                        from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
                        sessionId,
                        auth: { kind: "session", token: client.token },
                        nonce: randomId("n"),
                        payload: response,
                    } satisfies BusEnvelope<"uee.response", any>);
                } catch (err) {
                    send(ws, {
                        v: 2,
                        id: randomId("srv"),
                        type: "uee.error",
                        ts: nowMs(),
                        from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
                        sessionId,
                        auth: { kind: "session", token: client.token },
                        nonce: randomId("n"),
                        payload: { error: err instanceof Error ? err.message : String(err) },
                    } satisfies BusEnvelope<"uee.error", any>);
                }
                return;
            }

            // ---- PTY open ----
            if (env.type === "pty.open") {
                const p = env.payload as MessageMap["pty.open"];
                if (p.program !== "veno") return;

                const opened = await veno.openVeno(sessionId, {
                    cols: p.cols,
                    rows: p.rows,
                    onData: (ptyId, data) => {
                        send(ws, {
                            v: 2,
                            id: randomId("srv"),
                            type: "pty.output",
                            ts: nowMs(),
                            from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
                            sessionId,
                            auth: { kind: "session", token: client.token },
                            nonce: randomId("n"),
                            payload: { ptyId, data },
                        } satisfies BusEnvelope<"pty.output", MessageMap["pty.output"]>);
                    },
                });

                send(ws, {
                    v: 2,
                    id: randomId("srv"),
                    type: "pty.opened",
                    ts: nowMs(),
                    from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
                    sessionId,
                    auth: { kind: "session", token: client.token },
                    nonce: randomId("n"),
                    payload: { ptyId: opened },
                } satisfies BusEnvelope<"pty.opened", MessageMap["pty.opened"]>);

                return;
            }

            // ---- PTY resize ----
            if (env.type === "pty.resize") {
                const p = env.payload as MessageMap["pty.resize"];
                veno.resize(p.ptyId, p.cols, p.rows);
                return;
            }

            // ---- PTY input ----
            if (env.type === "pty.input") {
                const p = env.payload as MessageMap["pty.input"];
                veno.write(p.ptyId, p.data);
                return;
            }

            // ---- preview ping/pong ----
            if (env.type === "preview.ping") {
                const p = env.payload as MessageMap["preview.ping"];
                send(ws, {
                    v: 2,
                    id: randomId("srv"),
                    type: "preview.pong",
                    ts: nowMs(),
                    from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
                    sessionId,
                    auth: { kind: "session", token: client.token },
                    nonce: randomId("n"),
                    payload: { n: p.n },
                } satisfies BusEnvelope<"preview.pong", MessageMap["preview.pong"]>);
                return;
            }

            // ---- preview.stats: broadcast to IDE ----
            if (env.type === "preview.stats") {
                const p = env.payload as MessageMap["preview.stats"];
                const broadcast: BusEnvelope<"preview.stats", MessageMap["preview.stats"]> =
                {
                    v: 2,
                    id: randomId("srv"),
                    type: "preview.stats",
                    ts: nowMs(),
                    from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
                    sessionId: "broadcast",
                    payload: p,
                };
                broadcastTo("ide", broadcast as AnyEnv);
                return;
            }

            // ---- ops.sim.start ----
            if (env.type === "ops.sim.start") {
                const p = env.payload as MessageMap["ops.sim.start"];
                sim.request({ mode: p.mode ?? "dev", port: p.port ?? 4010 });
                return;
            }

            // ---- ops.sim.stop ----
            if (env.type === "ops.sim.stop") {
                sim.stop();
                return;
            }

            // ---- ops.sim.status ----
            if (env.type === "ops.sim.status") {
                const status = sim.getStatus();
                send(ws, {
                    v: 2,
                    id: randomId("srv"),
                    type: "ops.sim.status.reply",
                    ts: nowMs(),
                    from: { role: "nucleus", instanceId: HUB_INSTANCE_ID },
                    sessionId,
                    auth: { kind: "session", token: client.token },
                    nonce: randomId("n"),
                    payload: status,
                } satisfies BusEnvelope<
                    "ops.sim.status.reply",
                    MessageMap["ops.sim.status.reply"]
                >);
                return;
            }
        });

        ws.on("close", () => {
            veno.closeAllForSession(sessionId);
            clients.delete(client);
        });
    });
}

