#!/usr/bin/env node
/**
 * Fix TSV: move grapheme/out/pos/before/after data from cols [10,11,12,13]
 * back to cols [9,10,11,12,13] by removing the extra empty column
 */

import fs from "node:fs";

const inPath = "tooling/speech/sounds.tsv";
const lines = fs.readFileSync(inPath, "utf8").split(/\r?\n/);

const fixed = [];
for (let i = 0; i < lines.length; i++) {
  const line = lines[i];
  if (i === 0) {
    // Keep header as-is
    fixed.push(line);
  } else if (!line.trim()) {
    fixed.push("");
  } else {
    const cols = line.split("\t");
    // If this is a grapheme/exception row with extra columns, rebalance
    if (cols.length >= 14) {
      // Columns 0-8: kind, id, priority, notes, pattern, flags, replace, exception_in, exception_out
      // Column 9 appears to be empty (extra)
      // Columns 10+: the data we want
      // Shift left: keep 0-9, move 10+ down to 9+
      const fixed_cols = cols.slice(0, 9).concat(cols.slice(10));
      while (fixed_cols.length < 14) fixed_cols.push("");
      fixed.push(fixed_cols.join("\t"));
    } else {
      fixed.push(line);
    }
  }
}

fs.writeFileSync(inPath, fixed.join("\n"), "utf8");
console.log(`Γ£ô Fixed ${fixed.length} lines`);

import { LexiconEntryFileSchema } from "@world-engine/engine/contracts/lexicon";
import fs from "node:fs";
import path from "node:path";
import { LexiconIndexSchema } from "../lexicon/lexiconIndex.schema";

function usage(): never {
    console.error(
        [
            "Usage:",
            "  pnpm tsx packages/brain/src/cli/lexicon-index.ts <entriesDir> <outFile>",
            "",
            "Example:",
            "  pnpm tsx packages/brain/src/cli/lexicon-index.ts docs/lexicon/entries docs/lexicon/lexicon.index.json"
        ].join("\n")
    );
    process.exit(2);
}

function listLexiconFiles(dirAbs: string): string[] {
    if (!fs.existsSync(dirAbs)) return [];
    const files = fs.readdirSync(dirAbs).filter((f) => f.endsWith(".lexicon.json"));
    return files.map((f) => path.join(dirAbs, f));
}

function main() {
    const [entriesDir, outFile] = process.argv.slice(2);
    if (!entriesDir || !outFile) usage();

    const absEntries = path.resolve(entriesDir);
    const absOut = path.resolve(outFile);

    const files = listLexiconFiles(absEntries);
    if (files.length === 0) {
        console.error(`No *.lexicon.json files found in: ${absEntries}`);
        process.exit(1);
    }

    const entries = files.map((fp) => {
        const raw = fs.readFileSync(fp, "utf8");
        const json = JSON.parse(raw);
        const parsed = LexiconEntryFileSchema.parse(json);

        // store relative file path for portability
        const relFile = path
            .relative(path.dirname(absOut), fp)
            .split(path.sep)
            .join("/");

        return {
            process_tag: parsed.entry.process_tag,
            term: parsed.entry.term,
            canonical_term: parsed.entry.canonical_term,
            type: parsed.entry.type,
            operator_class: parsed.entry.operator_class,
            file: relFile
        };
    });

    // stable sort
    entries.sort((a, b) => a.process_tag.localeCompare(b.process_tag));

    // detect duplicates
    const seen = new Set<string>();
    for (const e of entries) {
        if (seen.has(e.process_tag)) {
            console.error(`Duplicate process_tag in index build: ${e.process_tag}`);
            process.exit(1);
        }
        seen.add(e.process_tag);
    }

    const indexDoc = LexiconIndexSchema.parse({
        schema: { name: "ai_prompt_lexicon.index", version: "1.0.0" },
        generatedAt: new Date().toISOString(),
        rootDir: path
            .relative(path.dirname(absOut), absEntries)
            .split(path.sep)
            .join("/"),
        entries
    });

    fs.mkdirSync(path.dirname(absOut), { recursive: true });
    fs.writeFileSync(absOut, JSON.stringify(indexDoc, null, 2) + "\n", "utf8");

    console.log(`Γ£à lexicon index built: ${outFile}`);
    console.log(`   entries: ${entries.length}`);
}

main();

import fs from "node:fs";
import path from "node:path";
import { ChainLinkSchema, MemoryChainSchema, type ChainLink, type MemoryChain } from "../thought/memoryChain.schema";
import { KnowledgeArtifactSchema, type KnowledgeArtifact } from "../thought/thoughtTypes";

type Args = {
    file: string;
    concept: string;
    json: boolean;
    jsonl: boolean;
};

function usage(): never {
    console.error(
        [
            "Usage:",
            "  pnpm tsx packages/brain/src/cli/memory-chain.ts --file <ndjson> --concept <word> [--json|--jsonl]",
            "",
            "Examples:",
            "  pnpm tsx packages/brain/src/cli/memory-chain.ts --file .brain/memory/knowledge.ndjson --concept webgpu",
            "  pnpm tsx packages/brain/src/cli/memory-chain.ts --file .brain/memory/knowledge.ndjson --concept webgpu --json",
            "  pnpm tsx packages/brain/src/cli/memory-chain.ts --file .brain/memory/knowledge.ndjson --concept performance --jsonl"
        ].join("\n")
    );
    process.exit(2);
}

function parseArgs(argv: string[]): Args {
    const a: Partial<Args> = { json: false, jsonl: false };
    for (let i = 0; i < argv.length; i++) {
        const k = argv[i];
        const v = argv[i + 1];
        if (k === "--file") { a.file = v; i++; continue; }
        if (k === "--concept") { a.concept = v; i++; continue; }
        if (k === "--json") { a.json = true; continue; }
        if (k === "--jsonl") { a.jsonl = true; continue; }
    }
    if (!a.file || !a.concept) usage();
    return a as Args;
}

function normalize(s: string): string {
    return s.toLowerCase();
}

/**
 * Find where concept appears in artifact.
 * Returns the text snippet where it was mentioned.
 */
function findMention(concept: string, artifact: KnowledgeArtifact): string | null {
    const norm = normalize(concept);
    const texts = [
        artifact.userGoal,
        artifact.decision,
        artifact.responseSummary,
        ...artifact.facts,
        ...artifact.assumptions,
        ...artifact.memory.persist
    ];

    for (const t of texts) {
        if (normalize(t).includes(norm)) {
            return t.slice(0, 100); // snippet
        }
    }
    return null;
}

/**
 * Infer belief before/after from artifact facts and assumptions.
 */
function extractBelief(artifact: KnowledgeArtifact): { before: string[]; after: string[] } {
    // Heuristic: assumptions are "before", facts are "after"
    return {
        before: artifact.assumptions.slice(0, 2),
        after: artifact.facts.slice(0, 2)
    };
}

function main() {
    const args = parseArgs(process.argv.slice(2));
    const abs = path.resolve(args.file);

    if (!fs.existsSync(abs)) {
        console.error(`File not found: ${abs}`);
        process.exit(1);
    }

    const raw = fs.readFileSync(abs, "utf8");
    const lines = raw.split("\n").map((l) => l.trim()).filter(Boolean);

    const links: ChainLink[] = [];
    let firstMention: string | null = null;
    let lastMention: string | null = null;

    for (const line of lines) {
        let artifact: KnowledgeArtifact | null = null;
        try {
            artifact = KnowledgeArtifactSchema.parse(JSON.parse(line));
        } catch {
            continue;
        }

        const mention = findMention(args.concept, artifact);
        if (!mention) continue;

        if (!firstMention) firstMention = artifact.createdAt;
        lastMention = artifact.createdAt;

        const belief = extractBelief(artifact);
        const link = ChainLinkSchema.parse({
            artifactId: artifact.id,
            createdAt: artifact.createdAt,
            concept: args.concept,
            mention,
            reasoningMode: artifact.selectedReasoningMode,
            decision: artifact.decision.slice(0, 80),
            outcome: artifact.responseSummary.slice(0, 80),
            beliefBefore: belief.before,
            beliefAfter: belief.after,
            confidence: Math.min(0.95, 0.5 + artifact.facts.length * 0.1) // rough heuristic
        });

        links.push(link);
    }

    if (links.length === 0) {
        console.error(`No mentions of "${args.concept}" found.`);
        process.exit(1);
    }

    // Build evolution summary
    const beliefEvolution = [
        `Concept "${args.concept}" mentioned ${links.length} times`,
        `First: ${firstMention}`,
        `Last: ${lastMention}`,
        `Reasoning modes: ${Array.from(new Set(links.map((l) => l.reasoningMode))).join(", ")}`,
        `Confidence increased from ${(links[0].confidence * 100).toFixed(0)}% to ${(links[links.length - 1].confidence * 100).toFixed(0)}%`
    ];

    const chain: MemoryChain = MemoryChainSchema.parse({
        concept: args.concept,
        firstMention: firstMention!,
        lastMention: lastMention!,
        chainLength: links.length,
        links,
        beliefEvolution
    });

    if (args.jsonl) {
        // Stream chain links
        for (const link of chain.links) {
            process.stdout.write(JSON.stringify(link) + "\n");
        }
        return;
    }

    if (args.json) {
        process.stdout.write(JSON.stringify(chain, null, 2) + "\n");
        return;
    }

    // Human output
    console.log(`\n≡ƒôè Memory Chain for "${args.concept}"\n`);
    console.log(`Length: ${chain.chainLength} mentions`);
    console.log(`Timeline: ${chain.firstMention} ΓåÆ ${chain.lastMention}\n`);

    for (const line of chain.beliefEvolution) {
        console.log(`  ${line}`);
    }

    console.log(`\n${"ΓöÇ".repeat(80)}`);
    for (let i = 0; i < chain.links.length; i++) {
        const link = chain.links[i];
        console.log(`\n[${i + 1}] ${link.createdAt}`);
        console.log(`    Artifact: ${link.artifactId}`);
        console.log(`    Mention: "${link.mention}"`);
        console.log(`    Reasoning: ${link.reasoningMode}`);
        console.log(`    Outcome: ${link.outcome}`);
        console.log(`    Confidence: ${(link.confidence * 100).toFixed(0)}%`);
    }

    console.log(`\n${"ΓöÇ".repeat(80)}`);
    console.log(`Γ£à Chain complete: ${chain.chainLength} links traced\n`);
}

main();

import fs from "node:fs";
import path from "node:path";
import { KnowledgeArtifactSchema, type KnowledgeArtifact } from "../thought/thoughtTypes";

type Args = {
    file: string;
    contains?: string;
    operator?: string;
    concept?: string;
    since?: string; // YYYY-MM-DD
    until?: string; // YYYY-MM-DD
    limit: number;
    json: boolean;
    jsonl: boolean; // streaming NDJSON output
};

function usage(): never {
    console.error(
        [
            "Usage:",
            "  pnpm tsx packages/brain/src/cli/memory-query.ts --file <ndjson> [--contains <text>] [--operator <process_tag>] [--concept <text>] [--since <YYYY-MM-DD>] [--until <YYYY-MM-DD>] [--limit N] [--json|--jsonl]",
            "",
            "Examples:",
            "  pnpm tsx packages/brain/src/cli/memory-query.ts --file .brain/memory/knowledge.ndjson --operator prompt.operator.decision",
            "  pnpm tsx packages/brain/src/cli/memory-query.ts --file .brain/memory/knowledge.ndjson --contains \"WebGPU\" --limit 20 --json",
            "  pnpm tsx packages/brain/src/cli/memory-query.ts --file .brain/memory/knowledge.ndjson --contains \"webgpu\" --jsonl (stream results line by line)",
            "  pnpm tsx packages/brain/src/cli/memory-query.ts --file .brain/memory/knowledge.ndjson --since 2026-02-01 --until 2026-02-12"
        ].join("\n")
    );
    process.exit(2);
}

function parseArgs(argv: string[]): Args {
    const a: Partial<Args> = { limit: 50, json: false, jsonl: false };
    for (let i = 0; i < argv.length; i++) {
        const k = argv[i];
        const v = argv[i + 1];
        if (k === "--file") { a.file = v; i++; continue; }
        if (k === "--contains") { a.contains = v; i++; continue; }
        if (k === "--operator") { a.operator = v; i++; continue; }
        if (k === "--concept") { a.concept = v; i++; continue; }
        if (k === "--since") { a.since = v; i++; continue; }
        if (k === "--until") { a.until = v; i++; continue; }
        if (k === "--limit") { a.limit = Number(v); i++; continue; }
        if (k === "--json") { a.json = true; continue; }
        if (k === "--jsonl") { a.jsonl = true; continue; }
    }
    if (!a.file) usage();
    if (!Number.isFinite(a.limit!) || (a.limit as number) <= 0) a.limit = 50;
    return a as Args;
}

function normalize(s: string): string {
    return s.toLowerCase();
}

function artifactText(a: KnowledgeArtifact): string {
    const parts: string[] = [
        a.userGoal,
        a.decision,
        a.responseSummary,
        ...a.facts,
        ...a.assumptions,
        ...a.uncertainties,
        ...a.constraints,
        ...a.tradeoffPriority,
        ...a.acceptanceTestsOrMetrics,
        ...a.memory.persist,
        ...a.memory.ephemeral
    ];
    return normalize(parts.join("\n"));
}

function dateStartIso(ymd: string): string {
    // normalize to UTC day start
    return new Date(`${ymd}T00:00:00.000Z`).toISOString();
}

function dateEndIso(ymd: string): string {
    // inclusive end of day -> next day start exclusive
    const d = new Date(`${ymd}T00:00:00.000Z`);
    d.setUTCDate(d.getUTCDate() + 1);
    return d.toISOString();
}

function inRange(createdAtIso: string, since?: string, until?: string): boolean {
    if (since) {
        const s = dateStartIso(since);
        if (createdAtIso < s) return false;
    }
    if (until) {
        const u = dateEndIso(until);
        if (createdAtIso >= u) return false;
    }
    return true;
}

type QueryResult = {
    id: string;
    createdAt: string;
    selectedReasoningMode: string;
    operatorsUsed: string[];
    userGoal: string;
    responseSummary: string;
};

function toQueryResult(a: KnowledgeArtifact): QueryResult {
    return {
        id: a.id,
        createdAt: a.createdAt,
        selectedReasoningMode: a.selectedReasoningMode,
        operatorsUsed: a.operatorsUsed,
        userGoal: a.userGoal,
        responseSummary: a.responseSummary
    };
}

function main() {
    const args = parseArgs(process.argv.slice(2));
    const abs = path.resolve(args.file);

    if (!fs.existsSync(abs)) {
        console.error(`File not found: ${abs}`);
        process.exit(1);
    }

    const raw = fs.readFileSync(abs, "utf8");
    const lines = raw.split("\n").map((l) => l.trim()).filter(Boolean);

    const results: KnowledgeArtifact[] = [];
    let scanned = 0;
    let parsedCount = 0;

    for (const line of lines) {
        scanned++;
        let parsed: KnowledgeArtifact | null = null;
        try {
            parsed = KnowledgeArtifactSchema.parse(JSON.parse(line));
            parsedCount++;
        } catch {
            continue; // ignore bad lines
        }

        if (!inRange(parsed.createdAt, args.since, args.until)) continue;

        if (args.operator && !parsed.operatorsUsed.includes(args.operator)) continue;

        const text = artifactText(parsed);

        if (args.contains && !text.includes(normalize(args.contains))) continue;

        if (args.concept && !text.includes(normalize(args.concept))) continue;

        results.push(parsed);
        if (results.length >= args.limit) break;
    }

    if (args.jsonl) {
        // Stream results as newline-delimited JSON (one result per line)
        for (const r of results) {
            const result = toQueryResult(r);
            process.stdout.write(JSON.stringify(result) + "\n");
        }
        return;
    }

    if (args.json) {
        const out = {
            schema: { name: "brain.memory.query_result", version: "1.0.0" },
            file: path.relative(process.cwd(), abs).split(path.sep).join("/"),
            filters: {
                contains: args.contains ?? null,
                operator: args.operator ?? null,
                concept: args.concept ?? null,
                since: args.since ?? null,
                until: args.until ?? null,
                limit: args.limit
            },
            meta: { scannedLines: scanned, parsedArtifacts: parsedCount, returned: results.length },
            results: results.map(toQueryResult)
        };
        process.stdout.write(JSON.stringify(out, null, 2) + "\n");
        return;
    }

    if (results.length === 0) {
        console.log("No matches.");
        return;
    }

    for (const r of results) {
        console.log("------------------------------------------------------------");
        console.log(`id: ${r.id}`);
        console.log(`createdAt: ${r.createdAt}`);
        console.log(`mode: ${r.selectedReasoningMode}`);
        console.log(`operators: ${r.operatorsUsed.join(", ")}`);
        console.log(`goal: ${r.userGoal}`);
        console.log(`summary: ${r.responseSummary}`);
    }
    console.log("------------------------------------------------------------");
    console.log(`Γ£à matches: ${results.length}`);
}

main();

import fs from "node:fs";
import path from "node:path";
import { KnowledgeArtifactSchema, type KnowledgeArtifact } from "../thought/thoughtTypes";

type Args = {
    file: string;
    since?: string; // YYYY-MM-DD
    until?: string; // YYYY-MM-DD
    top: number;
    json: boolean;
    jsonl: boolean; // streaming NDJSON output
};

function usage(): never {
    console.error(
        [
            "Usage:",
            "  pnpm tsx packages/brain/src/cli/memory-stats.ts --file <ndjson> [--since <YYYY-MM-DD>] [--until <YYYY-MM-DD>] [--top N] [--json|--jsonl]",
            "",
            "Examples:",
            "  pnpm tsx packages/brain/src/cli/memory-stats.ts --file .brain/memory/knowledge.ndjson --json",
            "  pnpm tsx packages/brain/src/cli/memory-stats.ts --file .brain/memory/knowledge.ndjson --since 2026-02-01 --until 2026-02-12 --top 25 --jsonl",
            "  pnpm tsx packages/brain/src/cli/memory-stats.ts --file .brain/memory/knowledge.ndjson --jsonl (stream stats line by line)"
        ].join("\n")
    );
    process.exit(2);
}

function parseArgs(argv: string[]): Args {
    const a: Partial<Args> = { top: 20, json: false, jsonl: false };
    for (let i = 0; i < argv.length; i++) {
        const k = argv[i];
        const v = argv[i + 1];
        if (k === "--file") { a.file = v; i++; continue; }
        if (k === "--since") { a.since = v; i++; continue; }
        if (k === "--until") { a.until = v; i++; continue; }
        if (k === "--top") { a.top = Number(v); i++; continue; }
        if (k === "--json") { a.json = true; continue; }
        if (k === "--jsonl") { a.jsonl = true; continue; }
    }
    if (!a.file) usage();
    if (!Number.isFinite(a.top!) || (a.top as number) <= 0) a.top = 20;
    return a as Args;
}

function dateStartIso(ymd: string): string {
    return new Date(`${ymd}T00:00:00.000Z`).toISOString();
}

function dateEndIso(ymd: string): string {
    const d = new Date(`${ymd}T00:00:00.000Z`);
    d.setUTCDate(d.getUTCDate() + 1);
    return d.toISOString();
}

function inRange(createdAtIso: string, since?: string, until?: string): boolean {
    if (since) {
        const s = dateStartIso(since);
        if (createdAtIso < s) return false;
    }
    if (until) {
        const u = dateEndIso(until);
        if (createdAtIso >= u) return false;
    }
    return true;
}

function ymdFromIso(iso: string): string {
    return iso.slice(0, 10);
}

function normalize(s: string): string {
    return s.toLowerCase();
}

/**
 * Simple concept extraction for stats:
 * - collect words length>=4
 * - remove common stopwords
 * - count frequency
 * This is deterministic and good enough to drive UI graphs.
 */
const STOP = new Set([
    "this", "that", "with", "from", "into", "your", "youre", "have", "will", "then", "than", "also", "just",
    "make", "build", "create", "generate", "convert", "write", "explain", "optimize", "reasoning",
    "what", "when", "where", "which", "would", "should", "could", "about", "under", "over", "most",
    "must", "need", "want", "like", "used", "uses", "using", "each", "every", "more", "less", "some",
    "only", "very", "them", "they", "their", "there", "here", "been", "were", "been", "does", "did"
]);

function extractConceptTokens(a: KnowledgeArtifact): string[] {
    const text = normalize(
        [
            a.userGoal,
            a.responseSummary,
            ...a.facts,
            ...a.assumptions,
            ...a.uncertainties,
            ...a.memory.persist
        ].join(" ")
    );

    const tokens = text
        .replace(/[^a-z0-9\s-]/g, " ")
        .split(/\s+/)
        .map((t) => t.trim())
        .filter((t) => t.length >= 4)
        .filter((t) => !STOP.has(t));

    // Unique tokens per artifact so one big paragraph doesn't overcount
    return Array.from(new Set(tokens)).slice(0, 50);
}

function topN(map: Map<string, number>, n: number) {
    return Array.from(map.entries())
        .sort((a, b) => b[1] - a[1])
        .slice(0, n)
        .map(([key, count]) => ({ key, count }));
}

function main() {
    const args = parseArgs(process.argv.slice(2));
    const abs = path.resolve(args.file);

    if (!fs.existsSync(abs)) {
        console.error(`File not found: ${abs}`);
        process.exit(1);
    }

    const raw = fs.readFileSync(abs, "utf8");
    const lines = raw.split("\n").map((l) => l.trim()).filter(Boolean);

    let scanned = 0;
    let parsedCount = 0;
    let included = 0;

    const byOperator = new Map<string, number>();
    const byDay = new Map<string, number>();
    const byConcept = new Map<string, number>();

    for (const line of lines) {
        scanned++;
        let art: KnowledgeArtifact | null = null;
        try {
            art = KnowledgeArtifactSchema.parse(JSON.parse(line));
            parsedCount++;
        } catch {
            continue;
        }

        if (!inRange(art.createdAt, args.since, args.until)) continue;
        included++;

        // day
        const day = ymdFromIso(art.createdAt);
        byDay.set(day, (byDay.get(day) ?? 0) + 1);

        // operators
        for (const op of art.operatorsUsed) {
            byOperator.set(op, (byOperator.get(op) ?? 0) + 1);
        }

        // concepts (tokens)
        for (const c of extractConceptTokens(art)) {
            byConcept.set(c, (byConcept.get(c) ?? 0) + 1);
        }
    }

    const out = {
        schema: { name: "brain.memory.stats", version: "1.0.0" },
        file: path.relative(process.cwd(), abs).split(path.sep).join("/"),
        filters: {
            since: args.since ?? null,
            until: args.until ?? null,
            top: args.top
        },
        meta: { scannedLines: scanned, parsedArtifacts: parsedCount, includedArtifacts: included },
        counts: {
            totalArtifacts: included,
            byDay: topN(byDay, 10_000), // keep all days; UI can trim
            topOperators: topN(byOperator, args.top),
            topConcepts: topN(byConcept, args.top)
        }
    };

    if (args.jsonl) {
        // Stream stats as newline-delimited JSON
        // Meta + counts each on separate line for real-time processing
        process.stdout.write(JSON.stringify({ schema: out.schema, meta: out.meta, counts: {} }) + "\n");
        for (const op of out.counts.topOperators) {
            process.stdout.write(JSON.stringify({ type: "operator", ...op }) + "\n");
        }
        for (const concept of out.counts.topConcepts) {
            process.stdout.write(JSON.stringify({ type: "concept", ...concept }) + "\n");
        }
        for (const day of out.counts.byDay) {
            process.stdout.write(JSON.stringify({ type: "day", ...day }) + "\n");
        }
        return;
    }

    if (args.json) {
        process.stdout.write(JSON.stringify(out, null, 2) + "\n");
        return;
    }

    // human output
    console.log(`file: ${out.file}`);
    console.log(`includedArtifacts: ${included}`);
    console.log("\nTop operators:");
    for (const r of out.counts.topOperators) console.log(`  ${r.count}  ${r.key}`);
    console.log("\nTop concepts:");
    for (const r of out.counts.topConcepts) console.log(`  ${r.count}  ${r.key}`);
    console.log("\nBy day:");
    for (const r of out.counts.byDay) console.log(`  ${r.count}  ${r.key}`);
}

main();

import { LexiconEntryFileSchema } from "@world-engine/engine/contracts/lexicon";
import fs from "node:fs";
import path from "node:path";

function usage(): never {
    console.error(
        [
            "Usage:",
            "  pnpm tsx packages/brain/src/cli/validate-lexicon-all.ts <entriesDir>",
            "",
            "Example:",
            "  pnpm tsx packages/brain/src/cli/validate-lexicon-all.ts docs/lexicon/entries"
        ].join("\n")
    );
    process.exit(2);
}

function findFiles(dirAbs: string, suffix: string): string[] {
    const out: string[] = [];
    if (!fs.existsSync(dirAbs)) return out;

    const walk = (d: string) => {
        for (const name of fs.readdirSync(d)) {
            const p = path.join(d, name);
            const st = fs.statSync(p);
            if (st.isDirectory()) walk(p);
            else if (st.isFile() && p.endsWith(suffix)) out.push(p);
        }
    };

    walk(dirAbs);
    return out;
}

function main() {
    const [entriesDir] = process.argv.slice(2);
    if (!entriesDir) usage();

    const absDir = path.resolve(entriesDir);
    const files = findFiles(absDir, ".lexicon.json");

    if (files.length === 0) {
        console.error(`No *.lexicon.json files found under: ${absDir}`);
        process.exit(1);
    }

    let failed = 0;
    const tagToFile = new Map<string, string>();

    for (const fp of files) {
        const rel = path.relative(process.cwd(), fp).split(path.sep).join("/");
        try {
            const raw = fs.readFileSync(fp, "utf8");
            const json = JSON.parse(raw);
            const parsed = LexiconEntryFileSchema.parse(json);

            const tag = parsed.entry.process_tag;
            const prev = tagToFile.get(tag);
            if (prev) {
                failed++;
                console.error(`Γ¥î duplicate process_tag: ${tag}`);
                console.error(`   - ${prev}`);
                console.error(`   - ${rel}`);
                continue;
            }
            tagToFile.set(tag, rel);

            console.log(`Γ£à valid: ${rel}`);
        } catch (err: any) {
            failed++;
            console.error(`Γ¥î invalid: ${rel}`);
            if (err?.issues) {
                for (const issue of err.issues) {
                    console.error(`  - ${issue.path.join(".")}: ${issue.message}`);
                }
            } else {
                console.error(`  - ${String(err?.message ?? err)}`);
            }
        }
    }

    if (failed > 0) {
        console.error(`\nΓ¥î validate-all failed: ${failed} file(s) invalid or duplicated.`);
        process.exit(1);
    }

    console.log(`\nΓ£à validate-all success: ${files.length} entries`);
}

main();

/**
 * Agent Controller
 *
 * Uses neural network to decide actions for game entities.
 * Interfaces between the brain and the game engine.
 */

import type { NeuralNetwork } from "./network.js";

/**
 * Sensor inputs that feed into the brain
 * (game state ΓåÆ neural network inputs)
 */
export interface BrainSensors {
    // Positional
    position: { x: number; y: number; z: number };
    velocity: { x: number; y: number; z: number };

    // Proximity
    nearbyEntitiesDistance: number[]; // Distances to nearby entities (normalized 0-1)
    nearbyEntitiesHealth: number[]; // Health of nearby entities (normalized 0-1)

    // State
    health: number; // 0-1
    energy: number; // 0-1
    facing: number; // 0-1 (normalized angle)

    // Environmental
    groundHeight: number; // 0-1 normalized
    temperature: number; // 0-1 normalized
    lightLevel: number; // 0-1
}

/**
 * Motor outputs: what the agent decides to do
 * (neural network outputs ΓåÆ game actions)
 */
export interface BrainActions {
    moveForward: number; // 0-1 (throttle)
    moveSideways: number; // -1 to 1 (strafe)
    moveVertical: number; // -1 to 1 (up/down)
    turn: number; // -1 to 1 (rotation)
    sprint: number; // 0-1 (boost)
    crouch: number; // 0-1 (lower profile)
    attack: number; // 0-1 (action strength)
    defend: number; // 0-1 (defensive stance)
    interact: number; // 0-1 (use/grab)
}

/**
 * Goal specification: what the agent should optimize for
 */
export interface BrainGoal {
    type: "avoid" | "chase" | "collect" | "survive" | "explore" | "custom";
    weight: number; // How much this goal matters (relative to other goals)
    target?: string; // Target entity ID or resource type
    reward?: (state: AgentState) => number; // Custom reward function
}

/**
 * Agent state: position, health, etc.
 */
export interface AgentState {
    id: string;
    sensors: BrainSensors;
    actions: BrainActions;
    health: number;
    energy: number;
    score: number;
    timeAlive: number;
    distanceTraveled: number;
}

/**
 * Agent controller: operates the neural network brain
 */
export class AgentBrain {
    readonly agentId: string;
    readonly network: NeuralNetwork;
    readonly goals: BrainGoal[];
    readonly maxSensors: number = 4; // Max nearby entities to sense

    state: AgentState;
    decisionCache: BrainActions | null = null;
    lastDecisionTime: number = 0;
    decisionInterval: number = 100; // ms between decisions (for performance)

    constructor(agentId: string, network: NeuralNetwork, goals: BrainGoal[] = []) {
        this.agentId = agentId;
        this.network = network;
        this.goals = goals || [{ type: "survive", weight: 1.0 }];

        this.state = {
            id: agentId,
            sensors: {
                position: { x: 0, y: 0, z: 0 },
                velocity: { x: 0, y: 0, z: 0 },
                nearbyEntitiesDistance: Array(this.maxSensors).fill(1),
                nearbyEntitiesHealth: Array(this.maxSensors).fill(0.5),
                health: 1,
                energy: 1,
                facing: 0.5,
                groundHeight: 0,
                temperature: 0.5,
                lightLevel: 0.5,
            },
            actions: {
                moveForward: 0,
                moveSideways: 0,
                moveVertical: 0,
                turn: 0,
                sprint: 0,
                crouch: 0,
                attack: 0,
                defend: 0,
                interact: 0,
            },
            health: 100,
            energy: 100,
            score: 0,
            timeAlive: 0,
            distanceTraveled: 0,
        };
    }

    /**
     * Update sensors from game state
     */
    updateSensors(sensors: Partial<BrainSensors>): void {
        this.state.sensors = { ...this.state.sensors, ...sensors };
    }

    /**
     * Run one decision cycle: convert sensors ΓåÆ actions
     * Caches decisions to reduce computation
     */
    decide(forceRecompute = false): BrainActions {
        const now = Date.now();
        if (!forceRecompute && this.decisionCache && now - this.lastDecisionTime < this.decisionInterval) {
            return this.decisionCache;
        }

        const inputs = this.sensorsToInputs();
        const outputs = this.network.forward(inputs);
        const actions = this.outputsToActions(outputs);

        this.state.actions = actions;
        this.decisionCache = actions;
        this.lastDecisionTime = now;

        return actions;
    }

    /**
     * Convert sensor data to neural network input vector
     */
    private sensorsToInputs(): number[] {
        const s = this.state.sensors;
        return [
            // Position (relative, normalized)
            Math.min(Math.abs(s.position.x) / 100, 1),
            Math.min(Math.abs(s.position.y) / 100, 1),
            Math.min(Math.abs(s.position.z) / 50, 1),

            // Velocity
            Math.min(Math.abs(s.velocity.x) / 50, 1),
            Math.min(Math.abs(s.velocity.y) / 50, 1),
            Math.min(Math.abs(s.velocity.z) / 50, 1),

            // Nearby threats/allies (distance + health)
            ...s.nearbyEntitiesDistance.slice(0, this.maxSensors),
            ...s.nearbyEntitiesHealth.slice(0, this.maxSensors),

            // Self state
            s.health,
            s.energy,
            s.facing,

            // Environment
            s.groundHeight,
            s.temperature,
            s.lightLevel,
        ];
    }

    /**
     * Convert neural network outputs to actions (0-1 values)
     */
    private outputsToActions(outputs: number[]): BrainActions {
        const actions: BrainActions = {
            moveForward: outputs[0] ?? 0,
            moveSideways: outputs[1] ? outputs[1] * 2 - 1 : 0, // -1 to 1
            moveVertical: outputs[2] ? outputs[2] * 2 - 1 : 0,
            turn: outputs[3] ? outputs[3] * 2 - 1 : 0,
            sprint: outputs[4] ?? 0,
            crouch: outputs[5] ?? 0,
            attack: outputs[6] ?? 0,
            defend: outputs[7] ?? 0,
            interact: outputs[8] ?? 0,
        };
        return actions;
    }

    /**
     * Calculate reward based on goals
     * Higher is better
     */
    calculateReward(): number {
        let totalReward = 0;

        for (const goal of this.goals) {
            let goalReward = 0;

            switch (goal.type) {
                case "survive":
                    // Reward staying alive, penalize low health
                    goalReward = this.state.health > 0 ? 1 : -10;
                    break;

                case "explore":
                    // Reward movement and distance traveled
                    goalReward = Math.min(this.state.distanceTraveled / 1000, 1);
                    break;

                case "collect":
                    // Reward score (assume game increments this)
                    goalReward = this.state.score / 100;
                    break;

                case "avoid":
                    // Reward high energy (avoid obstacles = less damage)
                    goalReward = this.state.energy / 100;
                    break;

                case "chase":
                    // Custom: assume reward fn is provided
                    if (goal.reward) {
                        goalReward = goal.reward(this.state);
                    }
                    break;
            }

            totalReward += goalReward * goal.weight;
        }

        return totalReward;
    }

    /**
     * Update internal state (called each game tick)
     */
    tick(deltaTime: number): void {
        this.state.timeAlive += deltaTime;
        this.state.score += (this.state.actions.attack * 10); // Example: score from attacking
    }
}

/**
 * Brain Lexicon Tool
 *
 * Wraps lexicon queries with governance policy enforcement.
 * Implements confidence-based decision making with escalation rules.
 *
 * Policy:
 * - confidence ΓëÑ 0.80 + not in review ΓåÆ USE (automatic)
 * - 0.65 Γëñ confidence < 0.80 ΓåÆ SUGGEST (non-binding, audit trail)
 * - confidence < 0.65 ΓåÆ ESCALATE (request human review before use)
 * - in review queue ΓåÆ DEFER (wait for review completion)
 */


// ============================================================================
// Types & Enums
// ============================================================================

export enum ConfidenceLevel {
    HIGH = "high",        // ΓëÑ 0.80, not in review
    MEDIUM = "medium",    // 0.65ΓÇô0.80
    LOW = "low",          // < 0.65
    BLOCKED = "blocked",  // in review or failed gates
}

export enum ActionType {
    USE = "use",           // Apply automatically (high confidence)
    SUGGEST = "suggest",   // Propose for audit (medium confidence)
    ESCALATE = "escalate", // Request review (low confidence)
    DEFER = "defer",       // Blocked pending review
    DENY = "deny",         // Failed governance
}

export interface GovernanceDecision {
    action: ActionType;
    confidence: number;
    reason: string;
    symbols: string[];
    review_queue_size?: number;
    recommendation?: string;
}

export interface BrainSymbolContext {
    term: string;
    language: string;
    impact_level: "read" | "write" | "system" | "critical";
}

// ============================================================================
// Brain Lexicon Tool Implementation
// ============================================================================

export class BrainLexiconTool {
    constructor(private lexiconClient: any) { }

    /**
     * Classify confidence level
     */
    private classifyConfidence(
        confidence: number,
        inReview: boolean,
    ): ConfidenceLevel {
        if (inReview) return ConfidenceLevel.BLOCKED;
        if (confidence >= 0.80) return ConfidenceLevel.HIGH;
        if (confidence >= 0.65) return ConfidenceLevel.MEDIUM;
        return ConfidenceLevel.LOW;
    }

    /**
     * Compute action based on confidence + impact level
     */
    private computeAction(
        level: ConfidenceLevel,
        impact: BrainSymbolContext["impact_level"],
    ): ActionType {
        if (level === ConfidenceLevel.BLOCKED) {
            return ActionType.DEFER;
        }

        if (level === ConfidenceLevel.HIGH) {
            return ActionType.USE;
        }

        if (level === ConfidenceLevel.MEDIUM) {
            // For writes/critical, escalate medium confidence
            if (impact === "write" || impact === "critical") {
                return ActionType.ESCALATE;
            }
            return ActionType.SUGGEST;
        }

        if (level === ConfidenceLevel.LOW) {
            if (impact === "critical") {
                return ActionType.DENY;
            }
            return ActionType.ESCALATE;
        }

        return ActionType.DENY;
    }

    /**
     * Resolve symbols from brain execution context
     * Returns governance decision for each symbol
     */
    async resolveSymbols(
        symbols: BrainSymbolContext[],
    ): Promise<Map<string, GovernanceDecision>> {
        const decisions = new Map<string, GovernanceDecision>();
        const reviewQueue = await this.lexiconClient.getReviewQueue();
        const reviewItemIds = new Set(
            reviewQueue.map((item: any) => item.item_id),
        );

        for (const context of symbols) {
            try {
                const lookup = await this.lexiconClient.lookupSymbol(
                    context.term,
                    context.language,
                );

                if (lookup.entries.length === 0) {
                    // Symbol not found in lexicon
                    decisions.set(context.term, {
                        action: ActionType.ESCALATE,
                        confidence: 0,
                        reason: "Symbol not found in lexicon baseline",
                        symbols: [context.term],
                        recommendation:
                            "Symbol is novel or not yet indexed. Request manual review before use.",
                    });
                    continue;
                }

                const bestEntry = lookup.entries[0]; // Highest confidence
                const inReview = reviewItemIds.has(bestEntry.entry_id);
                const confLevel = this.classifyConfidence(
                    bestEntry.overall_confidence,
                    inReview,
                );
                const action = this.computeAction(confLevel, context.impact_level);

                let reason = "";
                let recommendation = "";

                switch (action) {
                    case ActionType.USE:
                        reason = `High confidence (${(bestEntry.overall_confidence * 100).toFixed(1)}%) + not in review`;
                        recommendation = "Apply automatically, log decision for audit.";
                        break;

                    case ActionType.SUGGEST:
                        reason = `Medium confidence (${(bestEntry.overall_confidence * 100).toFixed(1)}%), safe for read operations`;
                        recommendation =
                            "Suggest to user; non-binding. Escalate if write/system impact.";
                        break;

                    case ActionType.ESCALATE:
                        reason = `Low confidence (${(bestEntry.overall_confidence * 100).toFixed(1)}%) or impact=critical`;
                        recommendation =
                            "Request human review + approval before use. Add to escalation queue.";
                        break;

                    case ActionType.DEFER:
                        reason = `Symbol in review queue (${inReview ? "WAITING" : "UNKNOWN"})`;
                        recommendation =
                            "Block use until review completes. Re-query after review approval.";
                        break;

                    case ActionType.DENY:
                        reason = `Failed governance: confidence < 0.65 + impact=critical`;
                        recommendation =
                            "Block use entirely. Escalate to human team for triage.";
                        break;
                }

                decisions.set(context.term, {
                    action,
                    confidence: bestEntry.overall_confidence,
                    reason,
                    symbols: [context.term, ...lookup.runes.map((r) => r.symbol)],
                    review_queue_size: reviewQueue.length,
                    recommendation,
                });
            } catch (err) {
                console.error(`Failed to resolve symbol "${context.term}":`, err);
                decisions.set(context.term, {
                    action: ActionType.DENY,
                    confidence: 0,
                    reason: `Error during lookup: ${(err as Error).message}`,
                    symbols: [context.term],
                    recommendation: "Lookup failed. Block use and escalate to support.",
                });
            }
        }

        return decisions;
    }

    /**
     * Apply governance policy to a batch of symbol resolutions
     * Returns overall action + per-symbol decisions
     */
    async enforcePolicy(
        symbols: BrainSymbolContext[],
    ): Promise<{
        overall_action: ActionType;
        decisions: Map<string, GovernanceDecision>;
        audit_entry: {
            timestamp: string;
            symbols_count: number;
            actions: Record<string, number>;
            escalations: string[];
        };
    }> {
        const decisions = await this.resolveSymbols(symbols);

        // Aggregate action: if any DENY ΓåÆ overall DENY; if any ESCALATE ΓåÆ ESCALATE; etc.
        let overallAction = ActionType.USE;
        const actionCounts: Record<ActionType, number> = {
            [ActionType.USE]: 0,
            [ActionType.SUGGEST]: 0,
            [ActionType.ESCALATE]: 0,
            [ActionType.DEFER]: 0,
            [ActionType.DENY]: 0,
        };
        const escalations: string[] = [];

        decisions.forEach((decision) => {
            actionCounts[decision.action]++;

            if (decision.action === ActionType.DENY) {
                overallAction = ActionType.DENY;
            } else if (decision.action === ActionType.ESCALATE && overallAction !== ActionType.DENY) {
                overallAction = ActionType.ESCALATE;
            } else if (decision.action === ActionType.DEFER && overallAction === ActionType.USE) {
                overallAction = ActionType.DEFER;
            }

            if (
                decision.action === ActionType.ESCALATE ||
                decision.action === ActionType.DENY
            ) {
                escalations.push(decision.symbols[0]);
            }
        });

        return {
            overall_action: overallAction,
            decisions,
            audit_entry: {
                timestamp: new Date().toISOString(),
                symbols_count: symbols.length,
                actions: actionCounts,
                escalations,
            },
        };
    }
}

