    return new BrainLexiconTool(lexiconClient);
}

/**
 * Population Genetics & Evolution
 *
 * Manages a population of neural networks that evolve toward solving
 * a fitness function. Used to optimize agent behavior in World Engine.
 */

import { NeuralNetwork } from "./network.js";

/**
 * Agent: Neural network + metadata
 */
export interface Agent {
    id: string;
    network: NeuralNetwork;
    generation: number;
    parentIds: string[];
}

/**
 * Evolution parameters
 */
export interface EvolutionConfig {
    populationSize: number;
    mutationRate: number; // 0-1
    mutationStrength: number; // Standard deviation
    elitism: number; // Top N agents to keep unchanged
    selectionPressure: "roulette" | "tournament" | "top50"; // Selection strategy
}

/**
 * Population of neural networks
 */
export class Population {
    agents: Agent[];
    generation: number = 1;
    bestFitness: number = 0;
    bestAgent: Agent | null = null;
    fitnessHistory: number[] = [];
    config: EvolutionConfig;

    constructor(
        config: EvolutionConfig,
        inputSize: number,
        hiddenSizes: number[],
        outputSize: number
    ) {
        this.config = config;
        this.agents = Array.from({ length: config.populationSize }, (_, i) => ({
            id: `agent-${this.generation}-${i}`,
            network: new NeuralNetwork(inputSize, hiddenSizes, outputSize),
            generation: this.generation,
            parentIds: [],
        }));
    }

    /**
     * Evaluate all agents using fitness function
     */
    async evaluate(fitnessFn: (network: NeuralNetwork) => Promise<number>): Promise<void> {
        for (const agent of this.agents) {
            agent.network.fitness = await fitnessFn(agent.network);
        }

        // Track best
        this.agents.sort((a, b) => b.network.fitness - a.network.fitness);
        const best = this.agents[0];
        if (best) {
            this.bestAgent = best;
            this.bestFitness = best.network.fitness;
            this.fitnessHistory.push(this.bestFitness);
        }
    }

    /**
     * Evolve population for next generation
     */
    evolve(): void {
        const sorted = [...this.agents].sort((a, b) => b.network.fitness - a.network.fitness);
        const newAgents: Agent[] = [];

        // Elitism: keep best unchanged
        for (let i = 0; i < this.config.elitism && i < sorted.length; i++) {
            const agent = sorted[i];
            if (!agent) continue;
            newAgents.push({
                id: `agent-${this.generation + 1}-${newAgents.length}`,
                network: agent.network.clone(),
                generation: this.generation + 1,
                parentIds: [agent.id],
            });
        }

        // Selection pool based on strategy
        let selectionPool = sorted;
        if (this.config.selectionPressure === "top50") {
            selectionPool = sorted.slice(0, Math.ceil(sorted.length / 2));
        } else if (this.config.selectionPressure === "tournament") {
            // Tournament selection: done per breeding iteration
            selectionPool = sorted;
        }

        // Breeding: fill rest of population
        while (newAgents.length < this.config.populationSize) {
            let parentA: Agent | undefined = selectionPool[0];
            let parentB: Agent | undefined = selectionPool[Math.floor(Math.random() * selectionPool.length)];

            if (this.config.selectionPressure === "tournament") {
                // Simple tournament: random pair, keep better
                const idx1 = Math.floor(Math.random() * selectionPool.length);
                const idx2 = Math.floor(Math.random() * selectionPool.length);
                const p1 = selectionPool[idx1];
                const p2 = selectionPool[idx2];
                if (p1 && p2) {
                    parentA = p1.network.fitness >= p2.network.fitness ? p1 : p2;
                }
                parentB = selectionPool[Math.floor(Math.random() * selectionPool.length)];
            } else if (this.config.selectionPressure === "roulette") {
                // Fitness proportionate selection
                const totalFitness = selectionPool.reduce((sum, a) => sum + a.network.fitness, 0);
                const probs = selectionPool.map((a) => a.network.fitness / (totalFitness || 1));

                parentA = this.selectByProbability(selectionPool, probs);
                parentB = this.selectByProbability(selectionPool, probs);
            }

            if (!parentA || !parentB) continue;

            // Crossover + Mutation
            const child = NeuralNetwork.crossover(parentA.network, parentB.network);
            child.mutate(this.config.mutationRate, this.config.mutationStrength);

            newAgents.push({
                id: `agent-${this.generation + 1}-${newAgents.length}`,
                network: child,
                generation: this.generation + 1,
                parentIds: [parentA.id, parentB.id],
            });
        }

        this.agents = newAgents;
        this.generation++;
    }

    /**
     * Select agent by probability distribution
     */
    private selectByProbability(agents: Agent[], probs: number[]): Agent | undefined {
        let rand = Math.random();
        for (let i = 0; i < agents.length; i++) {
            const prob = probs[i];
            if (prob !== undefined) {
                rand -= prob;
                if (rand <= 0) return agents[i];
            }
        }
        return agents[agents.length - 1];
    }

    /**
     * Get top N agents
     */
    getTopAgents(n: number): Agent[] {
        return [...this.agents].sort((a, b) => b.network.fitness - a.network.fitness).slice(0, n);
    }
}

import type { ThoughtState } from "../thoughtTypes";

export function stageReasoning(state: ThoughtState): ThoughtState {
    // Choose mode based on task type
    const msg = state.userMessage.toLowerCase();
    let mode: ThoughtState["reasoningMode"] = "mixed";

    if (/\bprove|must|therefore|deduce\b/.test(msg)) mode = "deductive";
    else if (/\blikely|trend|pattern|generally\b/.test(msg)) mode = "inductive";
    else if (/\bexplain|cause|why\b/.test(msg)) mode = "abductive";
    else mode = "mixed";

    const draftPlan =
        "Produce a structured response pipeline using lexicon operators: concept ΓåÆ perspective ΓåÆ self-questioning ΓåÆ reasoning ΓåÆ decision ΓåÆ optimize. " +
        "Also emit a KnowledgeArtifact record for memory, with acceptance tests and storage rules.";

    return {
        ...state,
        stage: "decision",
        reasoningMode: mode,
        draftPlan,
        operatorsUsed: [...state.operatorsUsed, "prompt.operator.reasoning"]
    };
}

/**
 * Codex Event Bus: typed event subscription system
 * Emitted by CodexRegistry on load/watch/validation state changes
 */

import type { CodexManifest } from "./manifest.js";

export type CodexLoadIssue = {
    file: string;
    error: string;
};

export type CodexLoadResult = {
    ok: boolean;
    issues: CodexLoadIssue[];
    countLoaded: number;
    manifest?: CodexManifest;
};

export type CodexEventMap = {
    /** Emitted before a load/reload begins */
    CODEX_LOAD_START: { reason: "boot" | "manual" | "fs_watch" };

    /** Emitted after a load finishes (even if issues exist) */
    CODEX_LOAD_RESULT: { result: CodexLoadResult };

    /** Emitted when registry becomes healthy (no issues) */
    CODEX_READY: { manifest: CodexManifest };

    /** Emitted when registry has issues (some files invalid/unreadable) */
    CODEX_INVALID: { issues: CodexLoadIssue[] };

    /** Emitted when manifest is written/updated (if manifestPath enabled) */
    CODEX_MANIFEST_UPDATED: { manifest: CodexManifest };

    /** Emitted when file watcher is started/stopped */
    CODEX_WATCH_STARTED: { rootDir: string };
    CODEX_WATCH_STOPPED: { rootDir: string };

    /** Emitted when watcher sees file activity (before debounce reload triggers) */
    CODEX_FS_EVENT: { event: "add" | "change" | "unlink"; file: string };
};

export type CodexEventName = keyof CodexEventMap;

export type CodexListener<T extends CodexEventName> = (payload: CodexEventMap[T]) => void;

/**
 * Typed event bus for CodexRegistry state transitions
 *
 * Usage:
 *   const bus = new CodexEventBus();
 *   const unsubscribe = bus.on('CODEX_READY', ({manifest}) => {
 *     console.log(`Registry ready with ${manifest.count} codexes`);
 *   });
 */
export class CodexEventBus {
    private listeners = new Map<CodexEventName, Set<(payload: any) => void>>();

    /**
     * Subscribe to an event. Returns unsubscribe function.
     */
    on<T extends CodexEventName>(event: T, listener: CodexListener<T>): () => void {
        const set = this.listeners.get(event) ?? new Set();
        set.add(listener as any);
        this.listeners.set(event, set);

        // Return unsubscribe function
        return () => this.off(event, listener);
    }

    /**
     * Unsubscribe from an event
     */
    off<T extends CodexEventName>(event: T, listener: CodexListener<T>): void {
        const set = this.listeners.get(event);
        if (!set) return;
        set.delete(listener as any);
        if (set.size === 0) this.listeners.delete(event);
    }

    /**
     * Emit an event to all subscribed listeners
     */
    emit<T extends CodexEventName>(event: T, payload: CodexEventMap[T]): void {
        const set = this.listeners.get(event);
        if (!set) return;
        for (const fn of set) fn(payload);
    }

    /**
     * Clear all listeners
     */
    clear(): void {
        this.listeners.clear();
    }

    /**
     * Get listener count for an event (useful for testing/debugging)
     */
    listenerCount(event: CodexEventName): number {
        return this.listeners.get(event)?.size ?? 0;
    }
}

