import fs from "node:fs";
import path from "node:path";
import { PromptEnvelopeSchema } from "./promptEnvelope.schema";
import { getOperatorSchema, listKnownOperatorTags } from "./promptOperatorRegistry";

type JsonValue = any;

function readJson(filePath: string): JsonValue {
  const raw = fs.readFileSync(filePath, "utf8");
  try {
    return JSON.parse(raw);
  } catch {
    throw new Error(`Invalid JSON: ${filePath}`);
  }
}

function isDirectory(p: string): boolean {
  return fs.existsSync(p) && fs.statSync(p).isDirectory();
}

function listJsonFilesRecursive(root: string): string[] {
  const out: string[] = [];
  const stack = [root];

  while (stack.length) {
    const cur = stack.pop()!;
    const entries = fs.readdirSync(cur, { withFileTypes: true });
    for (const e of entries) {
      const full = path.join(cur, e.name);
      if (e.isDirectory()) stack.push(full);
      else if (e.isFile() && e.name.toLowerCase().endsWith(".json")) out.push(full);
    }
  }
  return out;
}

function parseArgs(argv: string[]) {
  const args = new Set(argv.slice(2));
  const target = argv[2];

  // naive parse for --since=<iso>
  const sinceArg = argv.find((a) => a.startsWith("--since="));
  const since = sinceArg ? sinceArg.slice("--since=".length) : undefined;

  return {
    target,
    failOnUnknownTag: args.has("--fail-on-unknown-tag"),
    listTags: args.has("--list-tags"),
    since
  };
}

function shouldCheckBySince(filePath: string, sinceIso?: string): boolean {
  if (!sinceIso) return true;

  // If file has mtime newer than since, include it.
  // This is CI-friendly even if JSON doesn't have updatedAt.
  const sinceMs = Date.parse(sinceIso);
  if (!Number.isFinite(sinceMs)) {
    throw new Error(`Invalid --since value (must be ISO datetime): ${sinceIso}`);
  }
  const mtimeMs = fs.statSync(filePath).mtimeMs;
  return mtimeMs >= sinceMs;
}

function formatZodIssues(issues: { path: (string | number)[]; message: string }[]) {
  return issues.map((i) => {
    const at = i.path.length ? i.path.join(".") : "<root>";
    return `${at}: ${i.message}`;
  });
}

function main() {
  const { target, failOnUnknownTag, listTags, since } = parseArgs(process.argv);

  if (listTags) {
    console.log(listKnownOperatorTags().join("\n"));
    process.exit(0);
  }

  if (!target) {
    console.error(
      [
        "Usage:",
        "  pnpm tsx packages/engine/src/contracts/lexicon/validate-prompts.ts <fileOrFolder> [--fail-on-unknown-tag] [--since=<ISO>] [--list-tags]",
        "",
        "Examples:",
        "  pnpm tsx .../validate-prompts.ts docs/prompts",
        "  pnpm tsx .../validate-prompts.ts docs/prompts --fail-on-unknown-tag",
        "  pnpm tsx .../validate-prompts.ts docs/prompts --since=2026-02-12T00:00:00.000Z",
        "  pnpm tsx .../validate-prompts.ts --list-tags"
      ].join("\n")
    );
    process.exit(2);
  }

  const files = isDirectory(target) ? listJsonFilesRecursive(target) : [target];
  const filtered = files.filter((f) => shouldCheckBySince(f, since));

  if (filtered.length === 0) {
    console.log("OK: no files matched filter.");
    process.exit(0);
  }

  let invalidCount = 0;
  let checkedCount = 0;
  let skippedNonPromptCount = 0;
  let unknownTagCount = 0;

  for (const f of filtered) {
    let data: JsonValue;
    try {
      data = readJson(f);
    } catch (err: any) {
      invalidCount++;
      console.error(`Γ£û ${f}\n  - <root>: ${err.message}`);
      continue;
    }

    // Must at least match envelope
    const env = PromptEnvelopeSchema.safeParse(data);
    if (!env.success) {
      // Not a prompt artifact at all; skip silently to allow mixed folders
      skippedNonPromptCount++;
      continue;
    }

    const tag = env.data.code_process_tag;
    const schema = getOperatorSchema(tag);

    if (!schema) {
      unknownTagCount++;
      if (failOnUnknownTag) {
        invalidCount++;
        console.error(`Γ£û ${f}`);
        console.error(`  - code_process_tag: unknown operator tag "${tag}"`);
      }
      continue;
    }

    checkedCount++;
    const parsed = schema.safeParse(data);
    if (!parsed.success) {
      invalidCount++;
      console.error(`Γ£û ${f}`);
      for (const line of formatZodIssues(parsed.error.issues)) {
        console.error(`  - ${line}`);
      }
    }
  }

  if (invalidCount > 0) {
    console.error(
      `\nFAILED: ${invalidCount} invalid file(s). Checked: ${checkedCount}. Unknown tags: ${unknownTagCount}. Skipped non-prompts: ${skippedNonPromptCount}.`
    );
    process.exit(1);
  }

  console.log(
    `OK: checked: ${checkedCount}. unknown tags: ${unknownTagCount}. skipped non-prompts: ${skippedNonPromptCount}.`
  );
  process.exit(0);
}

main();

import fs from "node:fs";
import path from "node:path";
import { parseMultiGpuFramePlan } from "./plan";

function readJson(p: string): unknown {
  const raw = fs.readFileSync(p, "utf8");
  return JSON.parse(raw);
}

function usage(): never {
  console.error(
    [
      "Usage:",
      "  pnpm tsx packages/engine/src/contracts/multigpu/validate-multigpu.ts [options] <plan.json> [...more]",
      "",
      "Options:",
      "  --fail-fast           Exit on first failure",
      "  --require-from-exists Require sync.fromSubmissionId to exist in plan.work.submissions (stricter)",
    ].join("\n")
  );
  process.exit(2);
}

function assertUnique(label: string, ids: string[]) {
  const seen = new Set<string>();
  for (const id of ids) {
    if (seen.has(id)) throw new Error(`Duplicate ${label} id: ${id}`);
    seen.add(id);
  }
}

function main() {
  const args = process.argv.slice(2);
  if (args.length === 0) usage();

  const failFast = args.includes("--fail-fast");
  const requireFromExists = args.includes("--require-from-exists");

  const files = args.filter((a) => a !== "--fail-fast" && a !== "--require-from-exists");
  if (files.length === 0) usage();

  let failed = 0;

  for (const file of files) {
    const abs = path.resolve(file);

    try {
      const json = readJson(abs);
      const plan = parseMultiGpuFramePlan(json);

      // -------------------------
      // Semantic checks (beyond schema)
      // -------------------------

      // work.frameIndex matches plan.frameIndex
      if (plan.work.frameIndex !== plan.frameIndex) {
        throw new Error(
          `work.frameIndex (${plan.work.frameIndex}) must equal plan.frameIndex (${plan.frameIndex})`
        );
      }

      // submissions frameIndex match plan frameIndex
      for (const s of plan.work.submissions) {
        if (s.frameIndex !== plan.frameIndex) {
          throw new Error(`submission ${s.id}: frameIndex must equal plan.frameIndex (${plan.frameIndex})`);
        }
      }

      // submission IDs unique
      assertUnique("submission", plan.work.submissions.map((s) => s.id));

      // dep IDs unique
      assertUnique("dependency", plan.deps.dependencies.map((d) => d.id));

      // sync edge IDs unique
      assertUnique("sync edge", plan.sync.edges.map((e) => e.id));

      // deps: producer <= consumer
      for (const d of plan.deps.dependencies) {
        if (d.producerFrameIndex > d.consumerFrameIndex) {
          throw new Error(`dep ${d.id}: producerFrameIndex must be <= consumerFrameIndex`);
        }
      }

      // sync: plan.sync.frameIndex matches plan.frameIndex
      if (plan.sync.frameIndex !== plan.frameIndex) {
        throw new Error(`sync.frameIndex (${plan.sync.frameIndex}) must equal plan.frameIndex (${plan.frameIndex})`);
      }

      // sync: "to" must exist in this plan's submissions
      const submissionSet = new Set(plan.work.submissions.map((s) => s.id));
      for (const e of plan.sync.edges) {
        if (!submissionSet.has(e.toSubmissionId)) {
          throw new Error(
            `sync edge ${e.id}: toSubmissionId (${e.toSubmissionId}) must exist in plan.work.submissions`
          );
        }
        if (requireFromExists && !submissionSet.has(e.fromSubmissionId)) {
          throw new Error(
            `sync edge ${e.id}: fromSubmissionId (${e.fromSubmissionId}) must exist in plan.work.submissions (strict mode)`
          );
        }
      }

      console.log(`Γ£à valid: ${file}`);
    } catch (err: any) {
      failed++;
      console.error(`Γ¥î invalid: ${file}`);

      // Zod errors have .issues; other errors use message
      if (err?.issues && Array.isArray(err.issues)) {
        for (const issue of err.issues) {
          console.error(`  - ${issue.path.join(".")}: ${issue.message}`);
        }
      } else {
        console.error(`  - ${String(err?.message ?? err)}`);
      }

      if (failFast) process.exit(1);
    }
  }

  process.exit(failed === 0 ? 0 : 1);
}

main();

/**
 * Exhaustive discriminated union checking
 * Forces TypeScript to catch missing handlers at compile time
 *
 * @example
 * type Op = { type: "start" } | { type: "stop" };
 *
 * function handleOp(op: Op) {
 *   switch (op.type) {
 *     case "start": ...
 *     case "stop": ...
 *     // TS error if you forgot a case!
 *     default: assertNever(op);
 *   }
 * }
 */

export function assertNever(x: never): never {
    throw new Error(`Unreachable code reached with value: ${x}`);
}

/**
 * Type-safe exhaustive handler for discriminated unions
 * Returns never, can be used in expressions
 *
 * @example
 * const result = exhaustive(op, {
 *   start: () => "started",
 *   stop: () => "stopped"
 *   // TS error if cases don't match op.type union!
 * });
 */
export function exhaustive<
    T extends { type: string },
    Handlers extends { [K in T["type"]]: (x: Extract<T, { type: K }>) => any }
>(value: T, handlers: Handlers): ReturnType<Handlers[T["type"]]> {
    const handler = handlers[value.type as T["type"]];
    if (!handler) {
        throw new Error(`No handler for discriminant: ${value.type}`);
    }
    return handler(value as never);
}

/**
 * Entity Component System (ECS) runtime
 * Deterministic simulation core for World Engine
 */

function makeEntityId(): string {
  const cryptoObj = globalThis.crypto;
  if (cryptoObj && typeof cryptoObj.randomUUID === "function") {
    return cryptoObj.randomUUID();
  }
  return `${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 10)}`;
}

export interface Component {
  readonly id: string;
  [key: string]: unknown;
}

export interface Entity {
  readonly id: string;
  components: Map<string, Component>;
}

export interface System {
  readonly id: string;
  query?: string[];
  update(entities: Entity[], deltaMs: number): void;
}

export class ECSEngine {
  private readonly entities: Map<string, Entity> = new Map();
  private readonly systems: System[] = [];
  private readonly componentIndex: Map<string, Set<string>> = new Map();
  private tickId: number = 0;

  createEntity(id?: string): Entity {
    const entityId = id || `entity_${makeEntityId()}`;
    const entity: Entity = {
      id: entityId,
      components: new Map(),
    };
    this.entities.set(entityId, entity);
    return entity;
  }

  addComponent(entityId: string, component: Component): void {
    const entity = this.entities.get(entityId);
    if (!entity) throw new Error(`Entity ${entityId} not found`);

    entity.components.set(component.id, component);

    // Update component index
    if (!this.componentIndex.has(component.id)) {
      this.componentIndex.set(component.id, new Set());
    }
    this.componentIndex.get(component.id)!.add(entityId);
  }

  removeComponent(entityId: string, componentId: string): void {
    const entity = this.entities.get(entityId);
    if (!entity) throw new Error(`Entity ${entityId} not found`);

    entity.components.delete(componentId);
    this.componentIndex.get(componentId)?.delete(entityId);
  }

  removeEntity(entityId: string): void {
    const entity = this.entities.get(entityId);
    if (!entity) return;

    entity.components.forEach((_, componentId) => {
      this.componentIndex.get(componentId)?.delete(entityId);
    });
    this.entities.delete(entityId);
  }

  registerSystem(system: System): void {
    this.systems.push(system);
  }

  tick(deltaMs: number): void {
    this.tickId++;

    // Run systems
    for (const system of this.systems) {
      if (!system.query) {
        system.update(Array.from(this.entities.values()), deltaMs);
      } else {
        // Filter entities that have all required components
        const matching = Array.from(this.entities.values()).filter(entity =>
          system.query!.every(componentId => entity.components.has(componentId))
        );
        system.update(matching, deltaMs);
      }
    }
  }

  getSnapshot() {
    return {
      tickId: this.tickId,
      entities: Array.from(this.entities.values()).map(entity => ({
        id: entity.id,
        components: Object.fromEntries(entity.components),
      })),
    };
  }

  getEntity(entityId: string): Entity | undefined {
    return this.entities.get(entityId);
  }

  getEntitiesByComponent(componentId: string): Entity[] {
    const entityIds = this.componentIndex.get(componentId) || new Set();
    return Array.from(entityIds).map(id => this.entities.get(id)!);
  }

  clear(): void {
    this.entities.clear();
    this.componentIndex.clear();
    this.tickId = 0;
  }
}

