/**
 * Orbit Renderer - Token node network visualization
 */

import { mulberry32, hashString32 } from "../core/seed";
import type { CanvasFit, FlowVizFrame } from "./types";

const clamp = (n: number, a: number, b: number) => Math.max(a, Math.min(b, n));
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

export type OrbitNode = {
  x: number;
  y: number;
  r: number;
  label: string;
  count: number;
};

export function buildOrbitNodes(
  topTokens: Array<{ token: string; count: number }>,
  w: number,
  h: number,
  sessionHash: number
): OrbitNode[] {
  const cx = w / 2;
  const cy = h / 2;
  const R = Math.min(w, h) * 0.35;

  const rng = mulberry32(sessionHash ^ 0x67626868);
  return topTokens
    .sort((a, b) => b.count - a.count)
    .slice(0, 12)
    .map((token, i) => {
      const ╬╕ = (i / Math.max(topTokens.length, 1)) * Math.PI * 2 + rng() * 0.2;
      const r_inner = lerp(20, 60, clamp(token.count / 100, 0, 1));

      return {
        x: cx + Math.cos(╬╕) * R,
        y: cy + Math.sin(╬╕) * R,
        r: r_inner,
        label: token.token,
        count: token.count,
      };
    });
}

export function drawOrbit(fit: CanvasFit, frame: FlowVizFrame, nodes: OrbitNode[]) {
  const { ctx, w, h } = fit;
  const cx = w / 2;
  const cy = h / 2;

  ctx.clearRect(0, 0, w, h);

  // background tint
  ctx.save();
  ctx.fillStyle = "rgba(0, 0, 0, 0.02)";
  ctx.fillRect(0, 0, w, h);
  ctx.restore();

  // center point
  ctx.save();
  ctx.fillStyle = "rgba(100, 255, 218, 0.3)";
  ctx.beginPath();
  ctx.arc(cx, cy, 3, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  // connections between nodes
  ctx.save();
  ctx.lineWidth = 0.8;
  ctx.globalAlpha = 0.15;
  ctx.strokeStyle = "rgba(100, 255, 218, 1)";
  for (let i = 0; i < nodes.length; i++) {
    const curr = nodes[i];
    const next = nodes[(i + 1) % nodes.length];
    if (curr && next) {
      ctx.beginPath();
      ctx.moveTo(curr.x, curr.y);
      ctx.lineTo(next.x, next.y);
      ctx.stroke();
    }
  }
  ctx.restore();

  // spokes to center
  ctx.save();
  ctx.lineWidth = 0.6;
  ctx.globalAlpha = 0.12 + frame.energySmooth * 0.08;
  ctx.strokeStyle = "rgba(100, 255, 218, 1)";
  for (const node of nodes) {
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(node.x, node.y);
    ctx.stroke();
  }
  ctx.restore();

  // render nodes
  ctx.save();
  for (const node of nodes) {
    const pulse = 0.5 + 0.5 * Math.sin(frame.t * 1.8);
    const size = node.r * (0.8 + pulse * 0.4);
    const energy_mod = 1 + frame.energySmooth * 0.6;

    // halo
    ctx.fillStyle = `rgba(100, 255, 218, ${0.08 * frame.boost})`;
    ctx.beginPath();
    ctx.arc(node.x, node.y, size * 1.8, 0, Math.PI * 2);
    ctx.fill();

    // core
    ctx.fillStyle = `rgba(100, 255, 218, ${0.25 * energy_mod})`;
    ctx.beginPath();
    ctx.arc(node.x, node.y, size, 0, Math.PI * 2);
    ctx.fill();

    // stroke
    ctx.lineWidth = 1.2;
    ctx.strokeStyle = `rgba(100, 255, 218, ${0.5 * energy_mod})`;
    ctx.beginPath();
    ctx.arc(node.x, node.y, size, 0, Math.PI * 2);
    ctx.stroke();
  }
  ctx.restore();

  // labels
  ctx.save();
  ctx.font = "11px monospace";
  ctx.fillStyle = "rgba(230, 241, 255, 0.6)";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  for (const node of nodes) {
    ctx.fillText(node.label, node.x, node.y + node.r + 16);
  }
  ctx.restore();
}

/**
 * Renderer bridge for graphics systems
 * Adapts engine state to Three.js or WebGL output
 */

export interface RenderCommand {
  type: string;
  data: unknown;
}

export interface GraphicsContext {
  canvas: HTMLCanvasElement;
  fps: number;
  frameTime: number;
  drawCalls: number;
}

export class RendererBridge {
  private context: GraphicsContext;
  private frameTime: number = 0;
  private frameCount: number = 0;
  private lastTime: number = performance.now();

  constructor(canvas: HTMLCanvasElement) {
    this.context = {
      canvas,
      fps: 0,
      frameTime: 0,
      drawCalls: 0,
    };
  }

  updateStats(drawCalls: number): void {
    const now = performance.now();
    const delta = now - this.lastTime;
    this.frameTime = delta;
    this.frameCount++;

    if (this.frameCount % 60 === 0) {
      this.context.fps = Math.round(1000 / (this.frameTime / 60));
    }

    this.context.drawCalls = drawCalls;
    this.lastTime = now;
  }

  getStats() {
    return {
      fps: this.context.fps,
      frameTime: this.context.frameTime,
      drawCalls: this.context.drawCalls,
    };
  }

  getContext(): GraphicsContext {
    return this.context;
  }

  processCommand(command: RenderCommand): void {
    // Command processing will be implemented per renderer
    // This is a placeholder for the bridge interface
  }
}

export default RendererBridge;

/**
 * Render Extraction: ECS ΓåÆ GPU-ready typed arrays
 * Converts archetype SoA to render packets (instances for WebGPU/Three.js)
 * Zero allocations during extraction (pre-allocated buffers)
 */

type ArchetypeLike = Record<string, unknown>;

/**
 * Render packet: GPU-ready buffers for one draw call
 * All buffers are typed arrays (SoA layout)
 */
export type RenderPacket = {
    meshId: Uint32Array; // per-instance mesh ID
    materialId: Uint32Array; // per-instance material ID
    positions: Float32Array; // vec3 per instance (stride=3)
    rotations: Float32Array; // quat per instance (stride=4)
    scales: Float32Array; // vec3 per instance (stride=3)
    // Optional: custom attributes
    colors?: Uint8Array; // RGBA per instance
    metallic?: Float32Array;
    roughness?: Float32Array;
    custom?: Map<string, TypedArray>;

    visibleCount: number; // how many instances actually drawn
};

type TypedArray = Int8Array | Uint8Array | Int16Array | Uint16Array | Int32Array | Uint32Array | Float32Array | Float64Array;

/** Extraction context: pre-allocated buffers for reuse */
export class ExtractionContext {
    private packets = new Map<string, RenderPacket>();
    private readonly maxInstances: number;

    constructor(maxInstances: number = 100000) {
        this.maxInstances = maxInstances;
    }

    /** Get or create packet for a mesh+material combo */
    getPacket(key: string): RenderPacket {
        if (this.packets.has(key)) return this.packets.get(key)!;

        const packet: RenderPacket = {
            meshId: new Uint32Array(this.maxInstances),
            materialId: new Uint32Array(this.maxInstances),
            positions: new Float32Array(this.maxInstances * 3),
            rotations: new Float32Array(this.maxInstances * 4),
            scales: new Float32Array(this.maxInstances * 3),
            colors: new Uint8Array(this.maxInstances * 4),
            metallic: new Float32Array(this.maxInstances),
            roughness: new Float32Array(this.maxInstances),
            custom: new Map(),
            visibleCount: 0,
        };

        this.packets.set(key, packet);
        return packet;
    }

    /** Extract visible entities from archetype into packets */
    extractArchetype(
        arch: ArchetypeLike,
        entityIds: number[],
        getMeshId: (e: number) => number,
        getMaterialId: (e: number) => number,
        getTransform: (e: number) => { pos: [number, number, number]; rot: [number, number, number, number]; scale: [number, number, number] }
    ) {
        // Group instances by mesh+material
        const byMaterial = new Map<string, number[]>();
        for (const e of entityIds) {
            const meshId = getMeshId(e);
            const matId = getMaterialId(e);
            const key = `${meshId}:${matId}`;
            if (!byMaterial.has(key)) byMaterial.set(key, []);
            byMaterial.get(key)!.push(e);
        }

        // Write to packets (one per mesh+material)
        for (const [key, instances] of byMaterial) {
            const packet = this.getPacket(key);
            const [meshIdRaw, matIdRaw] = key.split(":");
            const meshId = Number(meshIdRaw ?? 0);
            const matId = Number(matIdRaw ?? 0);

            for (let i = 0; i < instances.length; i++) {
                const e = instances[i];
                if (e === undefined) continue;
                const { pos, rot, scale } = getTransform(e);

                // Write instance data
                packet.meshId[i] = meshId;
                packet.materialId[i] = matId;

                // Position (vec3)
                packet.positions[i * 3] = pos[0];
                packet.positions[i * 3 + 1] = pos[1];
                packet.positions[i * 3 + 2] = pos[2];

                // Rotation (quat)
                packet.rotations[i * 4] = rot[0];
                packet.rotations[i * 4 + 1] = rot[1];
                packet.rotations[i * 4 + 2] = rot[2];
                packet.rotations[i * 4 + 3] = rot[3];

                // Scale (vec3)
                packet.scales[i * 3] = scale[0];
                packet.scales[i * 3 + 1] = scale[1];
                packet.scales[i * 3 + 2] = scale[2];
            }

            packet.visibleCount = instances.length;
        }
    }

    getPackets(): RenderPacket[] {
        return [...this.packets.values()];
    }

    clear() {
        for (const packet of this.packets.values()) {
            packet.visibleCount = 0;
        }
    }
}

/**
 * High-level extraction pipeline:
 * ECS ΓåÆ SpatialGrid (frustum cull) ΓåÆ RenderPackets
 */
export function extractFrame(
    culledEntities: number[],
    getMeshId: (e: number) => number,
    getMaterial: (e: number) => number,
    getTransform: (e: number) => { pos: [number, number, number]; rot: [number, number, number, number]; scale: [number, number, number] },
    ctx: ExtractionContext
): RenderPacket[] {
    ctx.clear();

    // For demo: assume all entities same archetype
    // In practice, group by archetype then extract per arch

    const byMaterial = new Map<string, number[]>();
    for (const e of culledEntities) {
        const key = `${getMeshId(e)}:${getMaterial(e)}`;
        if (!byMaterial.has(key)) byMaterial.set(key, []);
        byMaterial.get(key)!.push(e);
    }

    for (const [key, instances] of byMaterial) {
        const packet = ctx.getPacket(key);
        const [meshIdRaw, matIdRaw] = key.split(":");
        const meshId = Number(meshIdRaw ?? 0);
        const matId = Number(matIdRaw ?? 0);

        for (let i = 0; i < instances.length; i++) {
            const e = instances[i];
            if (e === undefined) continue;
            const { pos, rot, scale } = getTransform(e);

            packet.meshId[i] = meshId;
            packet.materialId[i] = matId;
            packet.positions[i * 3] = pos[0];
            packet.positions[i * 3 + 1] = pos[1];
            packet.positions[i * 3 + 2] = pos[2];
            packet.rotations[i * 4] = rot[0];
            packet.rotations[i * 4 + 1] = rot[1];
            packet.rotations[i * 4 + 2] = rot[2];
            packet.rotations[i * 4 + 3] = rot[3];
            packet.scales[i * 3] = scale[0];
            packet.scales[i * 3 + 1] = scale[1];
            packet.scales[i * 3 + 2] = scale[2];
        }

        packet.visibleCount = instances.length;
    }

    return ctx.getPackets();
}

/**
 * Leximorph HTTP Client
 * Typed client for calling the FastAPI leximorph service
 *
 * Usage:
 * ```ts
 * const client = new LexiMorphClient('http://127.0.0.1:8001');
 * const result = await client.analyze('getUserName', 'js', 'identifier', { store: true });
 * const results = await client.query('User', { limit: 10 });
 * ```
 */

export interface AnalyzeRequest {
    text: string;
    language: string;
    kind: string;
    store?: boolean;
    db_path?: string;
}

export interface AnalyzeResponse {
    id?: number;
    entry: string;
    kind: string;
    language: string;
    parts: Record<string, unknown>;
    meta: Record<string, unknown>;
    created_at_utc: string;
}

export interface QueryResponse {
    id: number;
    entry: string;
    kind: string;
    language: string;
    parts: Record<string, unknown>;
    meta: Record<string, unknown>;
    created_at_utc: string;
}

export interface HealthResponse {
    ok: boolean;
    db_path: string;
}

export class LexiMorphClient {
    constructor(private baseUrl: string = 'http://127.0.0.1:8001') {
        // Normalize base URL (remove trailing slash)
        this.baseUrl = this.baseUrl.replace(/\/$/, '');
    }

    async analyze(
        text: string,
        language: string,
        kind: string,
        options?: { store?: boolean; db_path?: string }
    ): Promise<AnalyzeResponse> {
        const req: AnalyzeRequest = {
            text,
            language,
            kind,
        };
        if (options?.store !== undefined) req.store = options.store;
        if (options?.db_path !== undefined) req.db_path = options.db_path;

        const resp = await fetch(`${this.baseUrl}/leximorph/analyze`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(req),
        });

        if (!resp.ok) {
            throw new Error(`Leximorph analyze failed: ${resp.statusText}`);
        }

        return resp.json();
    }

    async query(contains: string, options?: { limit?: number; db_path?: string }): Promise<QueryResponse[]> {
        const params = new URLSearchParams({
            contains,
            limit: String(options?.limit ?? 50),
        });

        if (options?.db_path) {
            params.append('db_path', options.db_path);
        }

        const resp = await fetch(`${this.baseUrl}/leximorph/query?${params}`);

        if (!resp.ok) {
            throw new Error(`Leximorph query failed: ${resp.statusText}`);
        }

        return resp.json();
    }

    async init(db_path?: string): Promise<{ ok: boolean; db_path: string }> {
        const req = db_path ? { db_path } : {};

        const resp = await fetch(`${this.baseUrl}/leximorph/init`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(req),
        });

        if (!resp.ok) {
            throw new Error(`Leximorph init failed: ${resp.statusText}`);
        }

        return resp.json();
    }

    async health(): Promise<HealthResponse> {
        const resp = await fetch(`${this.baseUrl}/leximorph/health`);

        if (!resp.ok) {
            throw new Error(`Leximorph health check failed: ${resp.statusText}`);
        }

        return resp.json();
    }

    async export(db_path?: string): Promise<{ ok: boolean; db_path: string; export_path: string; rows: number }> {
        const params = new URLSearchParams();
        if (db_path) params.append('db_path', db_path);

        const resp = await fetch(`${this.baseUrl}/leximorph/export?${params}`);

        if (!resp.ok) {
            throw new Error(`Leximorph export failed: ${resp.statusText}`);
        }

        return resp.json();
    }
}

