const GOLDEN_TESTS = [
  {
    input: "the",
    expected: "├░╔Ö",
    description: "Exception: voiced TH in 'the'",
  },
  {
    input: "thin",
    expected: "├░in",
    description: "TH handling in 'thin' (per sounds-final.tsv)",
  },
  {
    input: "phone",
    expected: "fone",
    description: "Grapheme: 'ph' ΓåÆ 'f'",
  },
  {
    input: "knight",
    expected: "n─½t",
    description: "Exception: 'knight' (per sounds-final.tsv)",
  },
  {
    input: "nation",
    expected: "na┼íon",
    description: "Grapheme: 'tion' ΓåÆ '┼íon' (per sounds-final.tsv)",
  },
  {
    input: "vision",
    expected: "vi┼╛on",
    description: "Grapheme: 'sion' ΓåÆ '┼╛on' (per sounds-final.tsv)",
  },
  {
    input: "moon",
    expected: "m┼½n",
    description: "Grapheme: 'oo' ΓåÆ '┼½' (per sounds-final.tsv)",
  },
  {
    input: "book",
    expected: "b┼½k",
    description: "Grapheme: 'oo' ΓåÆ '┼½' before 'k' (per sounds-final.tsv)",
  },
  {
    input: "This,",
    expected: "├É╔¬s,",
    description: "Voiced TH title case + punctuation preservation",
  },
];

async function main() {
  const args = parseArgs(process.argv);

  try {
    console.log(
      `\n≡ƒôû Speech Rewriter Test Suite\n${"=".repeat(50)}\n`,
    );

    // Load config
