        console.log(`         Got:      "${result}"\n`);
      }
    }

    // Determinism checks
    console.log(`\n≡ƒöä Determinism Verification (${GOLDEN_TESTS.length} samples):\n`);

    const deterministicSamples = [
      "the quick brown fox jumps over the lazy dog",
      "nation, vision, phone, knight, thistle",
      "MOON book PHONE KNIGHT",
    ];

    let determinismOk = true;

    for (const sample of deterministicSamples) {
      const run1 = rewriter.rewriteText(sample);
      const run2 = rewriter.rewriteText(sample);

      if (run1 === run2) {
        console.log(`  Γ£ô [DETERMINISTIC] "${sample.substring(0, 40)}..."`);
      } else {
        console.log(`  Γ£ù [NON-DETERMINISTIC] "${sample.substring(0, 40)}..."`);
        console.log(`         Run 1: "${run1}"`);
        console.log(`         Run 2: "${run2}"`);
        determinismOk = false;
      }
    }

    // Summary
    console.log(`\n${"=".repeat(50)}`);
    console.log(
      `\n≡ƒôè Results: ${passCount}/${GOLDEN_TESTS.length} golden tests passed`,
    );

    if (failCount > 0) {
      console.log(`   ΓÜá∩╕Å  ${failCount} test(s) failed\n`);
    }

    if (determinismOk) {
      console.log(`   Γ£ô Determinism check: PASSED\n`);
    } else {
      console.log(`   Γ£ù Determinism check: FAILED\n`);
      process.exit(1);
    }

    if (failCount === 0) {
      console.log(`\n≡ƒÄë All tests passed!\n`);
      process.exit(0);
    } else {
      console.log(`\nΓ¥î Some tests failed.\n`);
      process.exit(1);
    }
  } catch (err) {
    console.error(`\nΓ¥î Error: ${err.message}\n`);
    if (args.verbose) {
      console.error(err.stack);
    }
    process.exit(1);
  }
}

main();

#!/usr/bin/env node
/**
 * Compile canonical sounds-final.tsv ΓåÆ rewriter.config.json
 *
 * Input schema (sounds-final.tsv):
 * - Comments: lines starting with #
 * - Data rows: kind, input, output, position [, context_before] [, context_after]
 *
 * Outputs:
 * - rewriter.config.json with deterministic rules (priority assigned by order)
 */

import fs from "node:fs/promises";
import path from "node:path";
import process from "node:process";

function stripBom(s) {
  return s.replace(/^\ufeff/, "");
}

function normalizeEmpty(v) {
  const s = (v ?? "").trim();
  return s === "" || s === "Γêà" ? "" : s;
}

function splitTsvLine(line) {
  return line.split("\t");
}

function buildConfig({ rules, exceptions, vowels, voicedThList, sourceFile }) {
  return {
    schemaVersion: "1.0.0",
    kind: "speech.rewriter.config",
    generatedAt: new Date().toISOString(),
    source: {
      tsv: sourceFile,
    },
    settings: {
      vowels,
      voicedThList,
    },
    exceptions,
    rules,
  };
}

async function main() {
  const inputFile = process.argv[2] ?? "sounds-final.tsv";
  const outputFile = process.argv[3] ?? "rewriter.config.json";

  const inputPath = path.resolve(process.cwd(), inputFile);
  const outputPath = path.resolve(process.cwd(), outputFile);

  // Load and parse TSV
  const raw = stripBom(await fs.readFile(inputPath, "utf8"));
  const allLines = raw.split(/\r?\n/g);

  // Filter: skip empty and comment lines
  const lines = allLines.filter((l) => {
    const trimmed = l.trim();
    return trimmed.length > 0 && !trimmed.startsWith("#");
  });

  if (lines.length === 0) {
    console.error(`[tsv] No data rows in ${inputFile}`);
    process.exit(1);
  }

  // Parse header
  const header = splitTsvLine(lines[0]).map((h) => h.trim());

  // Check if first row is a header or data
  // Header would be: kind, input, output, position, ...
  // Data would be: grapheme/exception, <word>, <output>, ...
  const isHeader = header[0] === "kind" && (header[1] === "id" || header[1] === "input");
  const dataStartIdx = isHeader ? 1 : 0;

  if (isHeader) {
    console.log(`[debug] Header: ${header.join(", ")}`);
  } else {
    console.log(`[debug] No header, treating all ${lines.length} lines as data`);
  }

  const exceptions = {};
  const rules = [];
  let priority = 10000; // Start high, decrement for deterministic order

  // Parse data rows
  for (let li = dataStartIdx; li < lines.length; li++) {
    const parts = splitTsvLine(lines[li]);
    const kind = normalizeEmpty(parts[0]).toLowerCase();
    const input = normalizeEmpty(parts[1]);
    const output = normalizeEmpty(parts[2]);
    const position = normalizeEmpty(parts[3]).toLowerCase() || "any";
    const contextBefore = parts.length > 4 ? normalizeEmpty(parts[4]) : "";
    const contextAfter = parts.length > 5 ? normalizeEmpty(parts[5]) : "";

    if (!input || !output) continue;

    if (kind === "exception") {
      // Exceptions are whole-word keyword overrides
      exceptions[input.toLowerCase()] = output;
      console.log(`[debug] Row ${li}: Exception "${input}" ΓåÆ "${output}"`);
      continue;
    }

    if (kind === "grapheme") {
      // Rules are grapheme substitutions
      const ruleId = `G${String(li).padStart(4, "0")}_${input.toUpperCase()}`;
      rules.push({
        kind: "grapheme",
        id: ruleId,
        priority,
        notes: `grapheme rule: ${input} ΓåÆ ${output}`,
        pattern: input,
        replace: output,
        pos: position === "start" || position === "end" || position === "any" ? position : "any",
        flags: [],
        before: contextBefore,
        after: contextAfter,
      });
      priority--; // Decrement for next rule
      console.log(`[debug] Row ${li}: Rule "${input}" ΓåÆ "${output}" at "${position}"`);
      continue;
    }

    if (kind !== "") {
      console.log(`[debug] Row ${li}: Skipping (unknown kind="${kind}")`);
    }
  }

  console.log(`[ok] Parsed ${rules.length} grapheme rules + ${Object.keys(exceptions).length} exceptions`);

  // Build config
  const config = buildConfig({
    rules,
    exceptions,
    vowels: "aeiouy",
    voicedThList: [
      "the", "this", "that", "these", "those", "there", "their",
      "they", "then", "than", "thee", "them", "thus",
    ],
    sourceFile: path.relative(process.cwd(), inputPath).split(path.sep).join("/"),
  });

  // Write output
  await fs.writeFile(outputPath, JSON.stringify(config, null, 2) + "\n", "utf8");
  console.log(`[ok] Wrote ${path.relative(process.cwd(), outputPath)}`);
  console.log(`[ok] Rules: ${rules.length}, Exceptions: ${Object.keys(exceptions).length}`);
}

main().catch((err) => {
  console.error(`[fatal] ${err?.stack ?? String(err)}`);
  process.exit(1);
});

#!/usr/bin/env node
/**
 * TSV -> rewriter.config.json
 *
 * Input TSV schema (header row):
 * kind, id, priority, notes, pattern, flags, replace, exception_in, exception_out,
 * grapheme, out, pos, before, after
 *
 * Supports:
 * - kind=grapheme rules
 * - kind=exception whole-word overrides
 *
 * Determinism:
 * - exceptions win
 * - grapheme rules sorted by priority desc, then id asc
 */

import fs from "node:fs/promises";
import path from "node:path";
import process from "node:process";

function usage() {
  return `
Usage:
  node tooling/speech/tsv-to-rewriter-config.mjs [input.tsv] [output.json] [--vowels aeiouy] [--voiced-th the,this,that]

Defaults:
  input:  tooling/speech/sounds-final.tsv
  output: tooling/speech/rewriter.config.json

Examples:
  node tooling/speech/tsv-to-rewriter-config.mjs (uses defaults)
  node tooling/speech/tsv-to-rewriter-config.mjs tooling/speech/sounds-final.tsv tooling/speech/rewriter.config.json
  node tooling/speech/tsv-to-rewriter-config.mjs tooling/speech/sounds-final.tsv tooling/speech/rewriter.config.json --vowels aeiouy
`.trim();
}

function parseArgs(argv) {
  const args = {
    input: null,
    output: null,
    vowels: "aeiouy",
    voicedThList: [
      "the",
      "this",
      "that",
      "these",
      "those",
      "there",
      "their",
      "they",
      "then",
      "than",
      "thee",
      "them",
      "thus",
    ],
  };

  const pos = [];
  for (let i = 2; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--vowels") args.vowels = argv[++i] ?? args.vowels;
    else if (a.startsWith("--vowels=")) args.vowels = a.split("=")[1] ?? args.vowels;
    else if (a === "--voiced-th") {
      const raw = argv[++i] ?? "";
      args.voicedThList = raw.split(",").map((s) => s.trim().toLowerCase()).filter(Boolean);
    } else if (a.startsWith("--voiced-th=")) {
      const raw = a.split("=")[1] ?? "";
      args.voicedThList = raw.split(",").map((s) => s.trim().toLowerCase()).filter(Boolean);
    } else {
      pos.push(a);
    }
  }

  args.input = pos[0] ?? "tooling/speech/sounds-final.tsv";
  args.output = pos[1] ?? "tooling/speech/rewriter.config.json";
  return args;
}

function stripBom(s) {
  if (s.charCodeAt(0) === 0xfeff) return s.slice(1);
  return s;
}

function splitTsvLine(line) {
  // TSV is simple here: no quoted tabs expected.
  return line.split("\t");
}

function normalizeEmpty(v) {
  const s = (v ?? "").trim();
  return s === "" ? "" : s;
}

function toInt(v, fallback = 0) {
  const n = Number.parseInt(String(v), 10);
  return Number.isFinite(n) ? n : fallback;
}

function parseFlags(rawFlags) {
  const s = (rawFlags ?? "").trim();
  if (!s) return [];
  // allow comma or space separated
  return s
    .split(/[,\s]+/g)
    .map((x) => x.trim())
    .filter(Boolean);
}

function safeKey(k) {
  return String(k ?? "").trim();
}

function buildConfig({ rules, exceptions, vowels, voicedThList, sourceFile }) {
  return {
    schemaVersion: "1.0.0",
    kind: "speech.rewriter.config",
    generatedAt: new Date().toISOString(),
    source: {
      tsv: sourceFile,
    },
    settings: {
      vowels,
      voicedThList,
    },
    exceptions, // { [lowerWord]: output }
    rules, // sorted list
  };
}

async function main() {
  const args = parseArgs(process.argv);

  if (!args.input || !args.output) {
    console.error(usage());
    process.exit(1);
  }

  const inputPath = path.resolve(process.cwd(), args.input);
  const outputPath = path.resolve(process.cwd(), args.output);

  const raw = stripBom(await fs.readFile(inputPath, "utf8"));
  const lines = raw.split(/\r?\n/g).filter((l) => l.trim().length > 0);

  if (lines.length < 2) {
    console.error(`[tsv] Not enough lines in ${args.input}`);
    process.exit(1);
  }

  const header = splitTsvLine(lines[0]).map((h) => h.trim());
  const idx = new Map(header.map((h, i) => [h, i]));

  function col(name) {
    const i = idx.get(name);
    if (i === undefined) throw new Error(`Missing TSV column: ${name}`);
    return i;
  }

  // Validate minimal columns
  const required = ["kind", "id", "priority"];
  for (const r of required) col(r);

  const exceptions = {}; // lower -> output
  const rules = [];

  for (let li = 1; li < lines.length; li++) {
    const parts = splitTsvLine(lines[li]);
    const kind = normalizeEmpty(parts[col("kind")]).toLowerCase();

    const id = safeKey(parts[col("id")]);
    const priority = toInt(parts[col("priority")], 0);
    const notes = normalizeEmpty(parts[col("notes")]);

    // exception columns in your file: exception_in / exception_out
    const exceptionIn = idx.has("exception_in") ? normalizeEmpty(parts[col("exception_in")]) : "";
    const exceptionOut = idx.has("exception_out") ? normalizeEmpty(parts[col("exception_out")]) : "";

    if (!id) continue;

    if (kind === "exception") {
      const key = (exceptionIn || "").trim().toLowerCase();
      const out = (exceptionOut || "").trim();
      if (key && out) {
        exceptions[key] = out;
      }
      continue;
    }

    if (kind !== "grapheme") continue;

    // For grapheme rules in sounds.tsv, data is in columns 9, 10, 11
    // Column 9: pattern (e.g., "tion"), Column 10: replace (e.g., "┼íon"), Column 11: pos (e.g., "end")
    const pattern = parts.length > 9 ? normalizeEmpty(parts[9]) : "";
    const replace = parts.length > 10 ? normalizeEmpty(parts[10]) : "";
    const pos = (parts.length > 11 ? normalizeEmpty(parts[11]) : "any").toLowerCase() || "any";

    if (!pattern) continue;

    const flags = idx.has("flags") ? parseFlags(parts[col("flags")]) : [];
    const before = parts.length > 12 ? normalizeEmpty(parts[12]) : "";
    const after = parts.length > 13 ? normalizeEmpty(parts[13]) : "";

    rules.push({
      kind: "grapheme",
      id,
      priority,
      notes,
      pattern,
      replace,
      pos: pos === "start" || pos === "end" || pos === "any" ? pos : "any",
      flags,
      before,
      after,
    });
  }

  // Deterministic sort: priority desc, id asc
  rules.sort((a, b) => {
    if (b.priority !== a.priority) return b.priority - a.priority;
    return a.id.localeCompare(b.id);
  });

  // Build output config
  const config = buildConfig({
    rules,
    exceptions,
    vowels: args.vowels,
    voicedThList: args.voicedThList,
    sourceFile: path.relative(process.cwd(), inputPath).split(path.sep).join("/"),
  });

  await fs.writeFile(outputPath, JSON.stringify(config, null, 2) + "\n", "utf8");
  console.log(`[ok] Wrote ${path.relative(process.cwd(), outputPath)}`);
  console.log(`[ok] Rules: ${rules.length}, Exceptions: ${Object.keys(exceptions).length}`);
}

main().catch((err) => {
  console.error(`[fatal] ${err?.stack ?? String(err)}`);
  process.exit(1);
});

#!/usr/bin/env node
/* tooling/test-compilers.mjs
 *
 * Determinism gate:
 * For each tool, run it twice back-to-back.
 * The second run must produce ZERO file changes (added/modified/deleted).
 *
 * This is the fastest, most reliable "engine-grade" gate you can add without
 * hardcoding output paths or maintaining golden files.
 */

import { spawn } from "node:child_process";
import path from "node:path";
import process from "node:process";
import { fileURLToPath } from "node:url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const REPO_ROOT = path.dirname(__dirname); // go up from tooling/ to repo root
const RUNNER = path.join(REPO_ROOT, "tooling", "run.mjs");

function runNode(args) {
  return new Promise((resolve) => {
    const child = spawn("node", args, { cwd: REPO_ROOT, stdio: ["ignore", "pipe", "pipe"] });
    let out = "";
    let err = "";
    child.stdout.on("data", (d) => (out += d.toString()));
    child.stderr.on("data", (d) => (err += d.toString()));
    child.on("close", (code) => resolve({ code: code ?? 0, out, err }));
  });
}

function sumChanges(diff) {
  return (diff.added?.length ?? 0) + (diff.modified?.length ?? 0) + (diff.deleted?.length ?? 0);
}

async function listTools() {
  const r = await runNode([RUNNER, "--list"]);
  if (r.code !== 0) throw new Error(`Failed to list tools:\n${r.err}`);
  return r.out
    .split("\n")
    .map((l) => l.trim())
    .filter(Boolean)
    .map((l) => l.split(/\s+/)[0]);
}

async function runToolJson(toolId) {
  const r = await runNode([RUNNER, toolId, "--json"]);
  if (r.code !== 0 && !r.out.trim()) {
    throw new Error(`Tool '${toolId}' failed without JSON output:\n${r.err}`);
  }
  const parsed = JSON.parse(r.out);
  const result = parsed.results?.[0];
  if (!result) throw new Error(`No JSON result for tool '${toolId}'. Raw:\n${r.out}`);
  return { exitCode: result.exitCode, changes: result.changes, artifactsDir: result.artifactsDir, raw: r };
}

async function main() {
  const argv = process.argv.slice(2);
  const only = argv.filter((a) => !a.startsWith("--"));
  const verbose = argv.includes("--verbose") || argv.includes("-v");

  const toolIds = only.length ? only : await listTools();
  if (!toolIds.length) {
    console.error("[tooling/test-compilers] No tools found.");
    process.exit(1);
  }

  let failed = 0;

  for (const toolId of toolIds) {
    console.log(`\n≡ƒº¬ ${toolId}`);

    const first = await runToolJson(toolId);
    if (first.exitCode !== 0) {
      failed++;
      console.error(`  Γ¥î first run failed (exit=${first.exitCode})`);
      if (verbose) {
        console.error(first.raw.err);
        console.error(first.raw.out);
      } else {
        console.error(`  artifacts: ${first.artifactsDir}`);
        console.error("  (re-run with --verbose for logs)");
      }
      continue;
    }

    const second = await runToolJson(toolId);
    if (second.exitCode !== 0) {
      failed++;
      console.error(`  Γ¥î second run failed (exit=${second.exitCode})`);
      if (verbose) {
        console.error(second.raw.err);
        console.error(second.raw.out);
      } else {
        console.error(`  artifacts: ${second.artifactsDir}`);
        console.error("  (re-run with --verbose for logs)");
      }
      continue;
    }

    const changed2 = sumChanges(second.changes);
    if (changed2 !== 0) {
      failed++;
      console.error(
        `  Γ¥î non-deterministic: second run produced changes (+${second.changes.added.length} ~${second.changes.modified.length} -${second.changes.deleted.length})`
      );
      console.error(`  artifacts: ${second.artifactsDir}`);
      if (verbose) {
        console.error(JSON.stringify(second.changes, null, 2));
      }
    } else {
      const changed1 = sumChanges(first.changes);
      console.log(`  Γ£à ok (first run changes=${changed1}, second run changes=0)`);
      console.log(`  artifacts: ${second.artifactsDir}`);
    }
  }

  if (failed) {
    console.error(`\n[tooling/test-compilers] FAIL ΓÇö ${failed} tool(s) non-deterministic or errored.`);
    process.exit(1);
  } else {
    console.log(`\n[tooling/test-compilers] PASS ΓÇö all tools deterministic.`);
  }
}

main().catch((err) => {
  console.error(`[tooling/test-compilers] Fatal: ${err?.stack ?? String(err)}`);
  process.exit(1);
});

#!/usr/bin/env node
import crypto from "node:crypto";

function sha256(s) {
  return crypto.createHash("sha256").update(s).digest("hex");
}

function newId(prefix) {
  return `${prefix}_${crypto.randomBytes(8).toString("hex")}`;
}

function nowMs() {
  return Date.now();
}

function clamp01(x) {
  if (x < 0) return 0;
  if (x > 1) return 1;
  return x;
}

/** ---- Bus (local) ----
 * Replace this with WS publish later.
 */
class EnvelopeBus {
  constructor() {
    this.listeners = new Map();
  }

  on(type, cb) {
    const set = this.listeners.get(type) ?? new Set();
    set.add(cb);
    this.listeners.set(type, set);
    return () => set.delete(cb);
  }

  publish(envelope) {
    const set = this.listeners.get(envelope.type);
    if (!set) return;
    for (const cb of set) cb(envelope);
  }
}

/** ---- Envelope Factory ---- */

function createEnvelopeFactory({ source, traceId }) {
  return function env(type, data, span = {}) {
    const spanId = span.spanId ?? newId("span");
    return {
      v: 1,
      id: newId("msg"),
      ts: new Date().toISOString(),
      type,
      source,
      traceId,
      spanId,
      parentSpanId: span.parentSpanId,
      severity: span.severity ?? "info",
      data,
    };
  };
}

/** ---- Input Kind Detection ---- */

function detectInputKind(text) {
  const t = text.trim();

  if (/```/.test(t)) return "code";
  if (/<[a-z][\s\S]*>/i.test(t) && /<\/[a-z]+>/i.test(t)) return "code";
  if (/import\s+.+from\s+['"]/.test(t) || /\bexport\s+(default|const|function|class)\b/.test(t))
    return "code";
  if (/\bfunction\b|\bconst\b|\blet\b|\bvar\b|\bclass\b/.test(t) && /[;{}]/.test(t)) return "code";
  if (/=>/.test(t) && /[;{}]/.test(t)) return "code";

  const codePunct = (t.match(/[{}();]/g) || []).length;
  const words = (t.match(/[A-Za-z]+/g) || []).length;
  if (words > 0 && codePunct / words > 0.12) return "code";

  return "prose";
}

/** ---- Prose Pipeline ---- */

const OrthographicRules = {
  yToI: (stem, affix) => {
    if (stem.endsWith("y") && !/[aeiou]y$/i.test(stem) && affix && affix.length > 0) {
      return stem.slice(0, -1) + "i";
    }
    return stem;
  },
  dropSilentE: (stem, affix) => {
    if (stem.endsWith("e") && /^[aeiou]/i.test(affix)) return stem.slice(0, -1);
    return stem;
  },
  doubleConsonant: (stem, affix) => {
    const CVC = /[^aeiou][aeiou][^aeiouhwxy]$/i;
    if (CVC.test(stem) && /^[aeiou]/i.test(affix)) return stem + stem.slice(-1);
    return stem;
  },
};

function toyMorphAnalyze(token) {
  const lower = token.toLowerCase().replace(/[^a-z']/g, "");
  const suffixes = [];
  let stem = lower;

  const commonSufs = [
    "ness",
    "ing",
    "ed",
    "ly",
    "tion",
    "sion",
    "er",
    "est",
    "able",
    "less",
    "ment",
  ];
  for (const suf of commonSufs.sort((a, b) => b.length - a.length)) {
    if (stem.endsWith(suf) && stem.length > suf.length + 2) {
      suffixes.unshift(suf);
      stem = stem.slice(0, -suf.length);
      break;
    }
  }

  const prefixes = [];
  const commonPrefs = ["re", "un", "in", "im", "dis", "pre", "post", "non", "sub", "super"];
  for (const pre of commonPrefs.sort((a, b) => b.length - a.length)) {
    if (stem.startsWith(pre) && stem.length > pre.length + 2) {
      prefixes.push(pre);
      stem = stem.slice(pre.length);
      break;
    }
  }

  const pos = suffixes.includes("ly")
    ? "ADV"
    : suffixes.includes("ness")
      ? "NOUN"
      : suffixes.includes("ing")
        ? "VERB"
        : "UNK";

  return { root: stem, prefixes, suffixes, pos };
}

function proseDecompose(input) {
  const tokens = input.split(/\s+/).filter(Boolean);
  return tokens.map((t, i) => ({ token: t, index: i, morph: toyMorphAnalyze(t) }));
}

function proseSuperpose(atoms) {
  return atoms.map((a) => {
    const hyps = [{ val: a.morph, prior: 1.0 }];
    if (String(a.token).toLowerCase().endsWith("ed")) {
      hyps.push({ val: { ...a.morph, pos: "ADJ" }, prior: 0.85 });
    }
    return { token: a.token, index: a.index, hyps };
  });
}

function proseCollapse(superposed) {
  const rootCounts = new Map();
  for (const s of superposed) {
    for (const h of s.hyps) {
      rootCounts.set(h.val.root, (rootCounts.get(h.val.root) || 0) + 1);
    }
  }
  for (const s of superposed) {
    for (const h of s.hyps) {
      if ((rootCounts.get(h.val.root) || 0) > 1) h.prior *= 1.15;
    }
  }
  for (const s of superposed) {
    for (const h of s.hyps) {
      if ((h.val.root || "").length < 2) h.prior *= 0.4;
    }
  }
  return superposed.map((s) => s.hyps.slice().sort((a, b) => b.prior - a.prior)[0].val);
}

function checkWellFormedness(val) {
  const v = (val.match(/[aeiou]/gi) || []).length;
  const d = val.length ? v / val.length : 0;
  return d > 0.12 && d < 0.65 ? 1.0 : 0.5;
}

function applyAffixGrammar(atom) {
  let surface = atom.root;
  const logs = [];

  if (atom.prefixes?.length) surface = atom.prefixes.join("") + surface;

  if (atom.suffixes?.length) {
    for (const suf of atom.suffixes) {
      const before = surface;
      surface = OrthographicRules.yToI(surface, suf);
      surface = OrthographicRules.dropSilentE(surface, suf);
      surface = OrthographicRules.doubleConsonant(surface, suf);
      if (surface !== before) logs.push(`stem:${before} -> ${surface} before +${suf}`);
      surface += suf;
    }
  }

  return { surface, logs };
}

function proseSynthesize(collapsedAtoms) {
  return collapsedAtoms
    .map((a, idx) => {
      const { surface, logs } = applyAffixGrammar(a);

      const wellFormed = checkWellFormedness(surface);
      const fit = 0.75;
      const novelty = 0.15;
      const complexity = ((a.prefixes?.length || 0) + (a.suffixes?.length || 0)) * 0.1;

      const score = 0.45 * wellFormed + 0.35 * fit + 0.2 * novelty - 0.15 * complexity;

      return {
        id: `prose_cand_${idx}_${sha256(surface).slice(0, 10)}`,
        kind: "lexical_synthesis",
        value: surface,
        score: clamp01(score),
        provenance: { atom: a, transforms: logs },
      };
    })
    .sort((a, b) => b.score - a.score);
}

/** ---- Code Pipeline ---- */

function codeDecompose(input) {
  const t = input.trim();
  const motifs = [];

  if (/\bmap\s*\(|\bfilter\s*\(|\breduce\s*\(/.test(t)) motifs.push("data_pipeline");
  if (/<[a-z][\s\S]*>/.test(t)) motifs.push("html_component");
  if (/:\s*root\b|--[a-z0-9-]+\s*:/.test(t)) motifs.push("css_vars");
  if (/\bfetch\s*\(|\baxios\b/.test(t)) motifs.push("network_call");
  if (/class\s+\w+/.test(t)) motifs.push("class_def");
  if (/function\s+\w+|\(\)\s*=>/.test(t)) motifs.push("fn_def");

  return { raw: t, motifs };
}

const StructuralTemplates = {
  js_map_filter: (data, transform, predicate) => `${data}.map(${transform}).filter(${predicate});`,
  html_component: (tag, className, content) => `<${tag} class="${className}">${content}</${tag}>`,
  css_variable_root: (vars) => `:root { ${vars.map((v) => `--${v.name}: ${v.value};`).join(" ")} }`,
};

function mkCodeCand(value, lang, motif, logs) {
  return {
    id: `code_cand_${sha256(lang + ":" + value).slice(0, 12)}`,
    kind: "structural_synthesis",
    lang,
    value,
    score: 0,
    provenance: { motif, transforms: logs },
  };
}

function validateCode(code, lang) {
  try {
    if (lang === "javascript") {
      new Function(code);
      return 1.0;
    }
    if (lang === "html") return /<[^>]+>/.test(code) ? 0.9 : 0.4;
    if (lang === "css") return /{[^}]*}/.test(code) ? 0.9 : 0.4;
    return 0.6;
  } catch {
    return 0.1;
  }
}

function codeSynthesize(block) {
  const cands = [];

  for (const motif of block.motifs) {
    if (motif === "data_pipeline") {
      const out = StructuralTemplates.js_map_filter("items", "x => x", "Boolean");
      cands.push(mkCodeCand(out, "javascript", motif, ["template:js_map_filter"]));
    }
    if (motif === "html_component") {
      const out = StructuralTemplates.html_component("div", "nexus-node", "");
      cands.push(mkCodeCand(out, "html", motif, ["template:html_component"]));
    }
    if (motif === "css_vars") {
      const out = StructuralTemplates.css_variable_root([{ name: "accent", value: "#eda338" }]);
      cands.push(mkCodeCand(out, "css", motif, ["template:css_variable_root"]));
    }
  }
  cands.push(mkCodeCand(block.raw, "unknown", "as_is", ["pass_through"]));

  for (const c of cands) {
    const wf = validateCode(c.value, c.lang);
    const complexity = Math.min(1, c.value.length / 400);
    c.score = clamp01(0.7 * wf + 0.3 * (1 - complexity));
  }

  return cands.sort((a, b) => b.score - a.score);
}

/** ---- EvidencePacket ---- */

function makeEvidencePacket({ runId, kind, input, stageStats, chosen, candidates }) {
  return {
    v: "1",
    runId,
    kind,
    inputHash: sha256(input),
    ts: new Date().toISOString(),
    stageStats,
    chosenId: chosen ? chosen.id : null,
    candidatesTop: candidates.slice(0, 5).map((c) => ({
      id: c.id,
      score: c.score,
      kind: c.kind,
      lang: c.lang,
    })),
  };
}

/** ---- Unified Runner (Envelope-emitting) ---- */

export function createUnifiedRunnerWithEnvelopes({
  source = "tooling.unifiedRunner",
  bus = new EnvelopeBus(),
} = {}) {
  async function run(input) {
    const kind = detectInputKind(input);
    const runHash = sha256(input).slice(0, 16);
    const runId = `run_${runHash}_${Date.now().toString(16)}`;

    const traceId = `trace_${runHash}_${Date.now().toString(16)}`;
    const env = createEnvelopeFactory({ source, traceId });

    const inputHash = sha256(input);
    const t0 = nowMs();

    // RUN STARTED
    bus.publish(env("pipeline.run.started", { runId, kind, inputHash }, { spanId: newId("span") }));

    const stageStats = [];
    let chosen = null;
    let candidates = [];

    const runSpan = newId("span");

    const stage = async (stageName, fn, statsFn) => {
      const spanId = newId("span");
      bus.publish(
        env(
          "pipeline.stage.started",
          { runId, stage: stageName },
          { spanId, parentSpanId: runSpan },
        ),
      );
      const s0 = nowMs();
      try {
        const payload = await fn();
        const ms = nowMs() - s0;

        const stats = statsFn ? statsFn(payload) : {};
        stageStats.push({ stage: stageName, ok: true, ms });

        bus.publish(
          env(
            "pipeline.stage.completed",
            { runId, stage: stageName, ok: true, ms, stats },
            { spanId, parentSpanId: runSpan },
          ),
        );
        return payload;
      } catch (e) {
        const ms = nowMs() - s0;
        stageStats.push({ stage: stageName, ok: false, ms });
        bus.publish(
          env(
            "pipeline.stage.completed",
            {
              runId,
              stage: stageName,
              ok: false,
              ms,
              stats: {},
              error: {
                code: "STAGE_FAILED",
                message: String(e?.message ?? e),
              },
            },
            { spanId, parentSpanId: runSpan, severity: "error" },
          ),
        );
        throw e;
      }
    };

    if (kind === "prose") {
      const atoms = await stage(
        "prose.decompose",
        () => proseDecompose(input),
        (p) => ({ atoms: p.length }),
      );
      const superposed = await stage(
        "prose.superpose",
        () => proseSuperpose(atoms),
        () => ({ hyps: "beam=toy" }),
      );
      const collapsed = await stage(
        "prose.collapse",
        () => proseCollapse(superposed),
        (p) => ({ collapsed: p.length }),
      );
      candidates = await stage(
        "prose.synthesize",
        () => proseSynthesize(collapsed),
        (p) => ({ candidates: p.length }),
      );
      chosen = candidates[0] ?? null;

      const evidence = await stage(
        "memory.write",
        () =>
          makeEvidencePacket({
            runId,
            kind,
            input,
            stageStats,
            chosen,
            candidates,
          }),
        () => ({ stored: true }),
      );

      const msTotal = nowMs() - t0;
      bus.publish(
        env(
          "pipeline.run.completed",
          {
            runId,
            kind,
            inputHash,
            msTotal,
            chosenId: chosen ? chosen.id : null,
          },
          { spanId: runSpan },
        ),
      );

      return { runId, kind, candidates, chosen, evidence, traceId };
    }

    // code
    const block = await stage(
      "code.decompose",
      () => codeDecompose(input),
      (p) => ({ motifs: p.motifs.length }),
    );
    candidates = await stage(
      "code.synthesize",
      () => codeSynthesize(block),
      (p) => ({ candidates: p.length }),
    );
    chosen = candidates[0] ?? null;

    const evidence = await stage(
      "memory.write",
      () =>
        makeEvidencePacket({
          runId,
          kind,
          input,
          stageStats,
          chosen,
          candidates,
        }),
      () => ({ stored: true }),
    );

    const msTotal = nowMs() - t0;
    bus.publish(
      env(
        "pipeline.run.completed",
        {
          runId,
          kind,
          inputHash,
          msTotal,
          chosenId: chosen ? chosen.id : null,
        },
        { spanId: runSpan },
      ),
    );

    return { runId, kind, candidates, chosen, evidence, traceId };
  }

  return { run, bus };
}

/** ---- CLI ---- */

if (import.meta.url === `file://${process.argv[1]}`) {
  const input = process.argv.slice(2).join(" ").trim();
  if (!input) {
    console.error('Usage: node tooling/unified-pipeline-runner.bus.mjs "your input here"');
    process.exit(1);
  }

  const { run, bus } = createUnifiedRunnerWithEnvelopes();

  // Simple console tap: show stage envelopes
  bus.on("pipeline.stage.completed", (env) => {
    const d = env.data;
    console.log(`Γ£ö ${d.stage} ok=${d.ok} ms=${d.ms}`);
  });

  const res = await run(input);
  console.log("\nChosen:");
  console.log(res.chosen);
  console.log("\nEvidence:");
  console.log(res.evidence);
  console.log("\nTraceId:");
  console.log(res.traceId);
}

