 */

import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";

const resultsDir = process.argv[2] ?? "pipeline_results";

function sha256File(p) {
  return crypto
    .createHash("sha256")
    .update(fs.readFileSync(p))
    .digest("hex");
}

function ok(msg) {
  console.log(`Γ£à ${msg}`);
}

function info(msg) {
